window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_037"]={"n":"李之世","dyn":"明","poems":[{"t":"拟古","f":"五言律诗","c":["左手持一缣，右手持一素。","昨日是新人，今日新人故。","将缣来比素，祇在两手间。","怜新与弃故，翻手作波澜。"]},{"t":"感怀","f":"五言律诗","c":["孤松生绝壑，萝生松树巅。","严风摧松枝，茑萝安得完。","如何相郁抱，中道忽弃捐。","行行白日暮，驱马度高原。"]},{"t":"为园效陶体","f":"五言古诗","c":["托迹城市久，不能事远耕。","为园向东皋，今岁始得成。","编麻插疏篱，周折互相撑。","开畦列高下，凿沼注清泠。","细雨鱼儿长，菜甲亦以生。","钓鱼持作馔，剪蔬持作羹。","邻父偶然过，不用相逢迎。","浊醪出行厨，对酌还尽倾。","虽谈不甚解，而自爱其情。","从此罢琴书，来读种树经。"]},{"t":"效挽歌","f":"五言古诗","c":["逝水自东驰，浮云自西徂。","与我周旋久，形影渐以疏。","明知不可度，药饵强相扶。","岩风动罗帏，吹我骨髓枯。","讣音忽远闻，爱憎异悲愉。","家人罗前庭，为我身后图。","一身不自保，宁问妻与孥。","妻孥浑不解，袒跣悲以呼。","凌晨设祖奠，门外驾灵舆。","室庐让与人，逼我山泽居。","出郭独彷徨，四野冢累累。","向来携手伴，执绋共前驱。","车徒空杂遝，祇为观者娱。","长揖谢世人，来与魍魉俱。"]},{"t":"录别 其一","f":"五言古诗","c":["一年一别君，兹别情逾恋。","红颜能几时，鬒发将无变。","群居不自保，况及异乡县。","风尘各飘荡，安知定相见。","关河冻雪深，故乡日以远。"]},{"t":"录别 其二","f":"五言古诗","c":["灿灿中林月，迢迢夜向徂。","游子不能别，忼忾悲以呼。","行役无远近，出门尽畏途。","况值严冬日，身上无完襦。","非无室家好，其奈饥所驱。"]},{"t":"录别 其三","f":"五言古诗","c":["飞埃黯河梁，回飙卷枯藿。","天寒毒雾昏，挥鞭出郊郭。","缅兹倦游情，临岐泪纷落。","行人即远道，居者念离索。","风尘事事违。","行矣不如归。"]},{"t":"录别 其四","f":"五言古诗","c":["女萝附松柏，托根亦于兹。","根株不相结，安能长相持。","青阳有回晷，紫艳无重披。","何以吐君怀，写作生别离。","恻怆不成音，君怀谁复知。"]},{"t":"述归 其一","f":"五言古诗","c":["原无干世术，抱璞祇自珍。","穷途一回首，翻为泣玉人。","侵晨理征帆，迢迢向河津。","行李莽无光，童仆亦逡巡。","川途已脩阻，浊浪复崩奔。","且辨还山服，沿江采白蘋。"]},{"t":"述归 其二","f":"五言古诗","c":["江云暝以阴，束峡哀湍泻。","篙师戒前途，晚泊古榕下。","舍舟沿圻岸，砑然见旷野。","荒池环竹阴，篱落开茆舍。","渔翁不相识，细语聊慰藉。","酒熟还共斟，班荆对长夜。"]},{"t":"述归 其三","f":"五言古诗","c":["滩流怒不平，两岸闻鸡鸣。","寒风振大壑，咿咿杂橹声。","推篷一以望，烟岛纷纵横。","古戍连秋草，残流带曙星。","的的渔灯乱，迢迢塞雁征。","朝日映扶桑，因之凌东溟。"]},{"t":"送杨亦琳上春官","f":"五言古诗","c":["携馀一尊酒，送子长河湄。","征途八千里，行役在京师。","是时冬正深，冻雪胶河澌。","玄云澹不流，我马东西驰。","赠君从此去，云霄会有期。","鸿雁起天末，鹪鹩巢深枝。"]},{"t":"舟次横江上春官","f":"五言古诗","c":["夙昔秉柔翰，抗志事遨游。","驾言不得意，各各守故邱。","今晨当别离，何由展绸缪。","玄冬十二月，霜露欺重裘。","冠盖趋河曲，声华满帝州。","努力赴风云，明良固所求。"]},{"t":"舟次横江","f":"五言古诗","c":["凌晨发江门，其夕抵东渚。","西流下崩湍，方舟逆相拒。","危樯牵巨缆，十步九回顾。","滩声怒如雷，杂以萧骚雨。","游人终夜叹，大半思乡土。","却望猪头山，三朝又三暮。"]},{"t":"舟中玩月","f":"五言古诗","c":["孟秋苦积霖，经旬不肯歇。","晚色稍澄霁，开窗陶嘉月。","金波荡漾明，半侵瑶池阙。","乍如一钩悬，散作千流沫。","孤云袅袅垂，忽与渔灯没。","舟人趁暮潮，进棹暗相拨。","水宿厌滞淫，临流暂披豁。","安得任公钓，下捣鼋鼍穴。"]},{"t":"十八滩","f":"五言古诗","c":["奇情因险见，山水亦人然。","山水适相遇，此地得其偏。","水性柔而滑，山亦静而专。","相触为波涛，终古此熬煎。","怒气横中流，贲育不敢前。","造物多不平，险乃归山川。","轴翻江倒流，一鏬走青天。","奇态纷百出，意匠若为传。","山水遇奇人，幽灵始一宣。"]},{"t":"由圭峰历蒲涧作","f":"五言古诗","c":["兹山信奇秀，嵂屼中天峙。","丹梯郁盘纡，岩峦回清閟。","赤日吐大江，朝霞共明媚。","半空出楼阁，隐隐宿雪际。","六月凉飔生，泠然透衣袂。","攀萝鸟道长，漱石泉声细。","中岭出层霄，度者如磨蚁。","一径转幽深，千流汇清泚。","临流撷涧蒲，荷锸斲石髓。","须臾日就颓，明灭林光霁。","策杖还故山，偶与高僧值。","茗分石窦泉，饭索香厨米。","因耽一日閒，恍焉忘人世。"]},{"t":"醉中书事","f":"五言古诗","c":["处世如浮萍，大都无不可。","昨日与今朝，头颅渐非我。","有酒不肯醉，坐惜流光过。","何来美少年，娉婷复婀娜。","下马闯柴扉，长揖当阶坐。","中厨出浊醪，荐以秋园果。","一觞复一酌，颓然白日堕。","客子殊未阑，主人已高卧。"]},{"t":"即事","f":"五言古诗","c":["初月澹微明，寒我莽回薄。","端居不自好，呼朋走东郭。","同游有童冠，步履亦参错。","周折历纡途，凭凌陟层崿。","峨峨百尺台，中有读书阁。","古堂绝潇洒，长檠罩翠幕。","有美共联翩，狂吟间浪谑。","城头更漏深，半下葳蕤钥。","送送出城闉，还订复还约。","黑云弥四山，骤雨天边落。","欲留不可留，欲去行且却。","屏憩石桥阴，高谈共商略。","邻翁借馀照，瓜果随意剥。","须臾雨色收，广陌净如濯。","携手踏歌还，褰裳复濡脚。","入门雨复滋，空斋转萧索。","呼童更旧衣，苦茗进一杓。","终宵不成寐，悬灯照屋角。"]},{"t":"上林明府","f":"五言古诗","c":["单父奏鸣琴，东阿铸耕器。","弦歌叶雅化，憺泊襄上理。","我侯清庙材，治行洵可儗。","游刃馀盘错，挥斤恢髋髀。","恩覃海澨欢，绩奏彤廷最。","圣主繁萦绥，舆情周眷注。","披云仙舄还，揽辔朱轮驻。","忻兹被和风，嘘咈甘棠树。"]},{"t":"重游西山","f":"五言古诗","c":["回车遵广术，重眺西山麓。","古台绝潇洒，晴景恣遐瞩。","穿云俯危磴，叠石架幽屋。","鸣蝉号枯林，馀响袅相续。","冥心百虑遣，游目千态足。","日影澹林坰，前冈闻伐木。"]},{"t":"经绿护屏陈公甫先生读书处","f":"五言古诗","c":["青山围碧玉，中有读书台。","颓垣鞠草莽，伊人安在哉。","唯馀山丹树，花落点苍苔。"]},{"t":"将出京上大座师张玄中魏肖中二先生","f":"五言古诗","c":["希世无长略，挟策干明时。","时髦应景运，迂薄畴见知。","仆徒理装具，言与京邑辞。","倦鸟思安巢，遥遥恋南枝。","岂不怀初服，眄睐属恩私。","誓将策驽劣，报德以为期。"]},{"t":"途中即事 其一","f":"五言古诗","c":["红尘匝地起，白日何濛濛。","骄马东西驰，徒御不可踪。","长安道如弦，而我泣途穷。","行行遵广术，即次已闻钟。","故人具鸡黍，尊酒何从容。","为欢自一时，叹息北征篷。"]},{"t":"途中即事 其二","f":"五言古诗","c":["燕山环海甸，金河日夜流。","北地多奇寒，春条莽未抽。","眷言怀故土，立马此夷犹。","昔来霜始降，今去冰解胶。","如何奄忽间，坐使时运遒。","古人爱景光，树德乃良畴。"]},{"t":"登济上酒楼 其一","f":"五言古诗","c":["谪仙本沈冥，季真亦萧爽。","霾名供奉班，浪迹鉴湖长。","纵酒全天真，论诗契玄朗。","乘兴非夙期，间值或偕往。","金龟时自解，宫袍醉相傍。","兹地留芳踪，怀古惬遐想。","兀兀孤城间，危楼自高敞。"]},{"t":"登济上酒楼 其二","f":"五言古诗","c":["济上有酒楼，醉仙像在兹。","我来一瞻拜，怅矣不同时。","孤城临孔道，处处飏青旗。","当时贺李辈，偶此泛金卮。","后人表芳躅，就地搆魏祠。","因悟贤达徒，所过留音徽。","方其混酒廛，悠悠孰见知。","饮者留其名，斯语信戏辞。"]},{"t":"江上有怀舍弟文度 其一","f":"五言律诗","c":["翔禽应候鸣，柔芳变时条。","自予徂京邑，悠悠岁运交。","离萍恋本根，羁兽求匹曹。","如何连枝亲，形影滞江皋。"]},{"t":"江上有怀舍弟文度 其二","f":"五言律诗","c":["江皋洵难越，烟涛复崩奔。","宵行倦睇览，夜宿惊营魂。","岂不同枝体，莽莽异寒温。","幸果还山诺，为欢在晤言。"]},{"t":"江上有怀舍弟文度 其三","f":"五言律诗","c":["晤言能几时，朱陆变玄阴。","翳翳匿颓景，槭槭就衰林。","牵世罗区累，怀古有遐心。","引领翘芳讯，冥泪遗飞沈。"]},{"t":"江上有怀舍弟文度 其四","f":"五言律诗","c":["飞沈杳无象，纷复搅余思。","池草既漫披，园柳亦鬖垂。","缅兹劳梦魂，玄赏惬心期。","长怀强中咏，菲薄不可追。"]},{"t":"为园","f":"五言古诗","c":["蘼芜日以青，枫橘日以黄。","柑柿与红梨，长条饱德霜。","嫩蕊不禁寒，移之植中堂。","有客远方来，嘉卉勤相将。","宁知物有性，终不改其常。","严风动地来，身上无完裳。","但谓机中人，好好理蚕桑。"]},{"t":"江行夜泊","f":"五言古诗","c":["涉川振遐楫，遵坎沿脩渚。","江势拍鸿濛，荡漾摩天宇。","蔽日下千艘，逗浪危帆阻。","溯流舣圻岸，投篙侧浦溆。","辨火知渔舟，依依泊孤屿。","风汎菰蒲偃，棹触凫鹥举。","沙际见遥村，烟中闻夜语。","水族纷回诡，波光澹来去。","戒徒念屡忉，信履道无沮。","因书成短谣，庶用劳同旅。"]},{"t":"江行晓发","f":"五言古诗","c":["宵行惮昏晦，迅迈及崇朝。","孤月媚中川，残星纚奔涛。","中流澹容与，投策没轻篙。","鼓枻溯冯夷，挂席属招摇。","初日照枌榆，流影披林皋。","阴崖发紫芝，阳陆灿红桃。","川陵径回复，廛邑互周遭。","欣兹届归期，云与初愿交。","纡思把瑶翰，陶然命浊醪。","排闷谢怀土，无营神已游。"]},{"t":"过牛渚温太真然犀处","f":"五言古诗","c":["地岫滔东溟，天倾荡南纪。","混沌想初辟，微茫天为理。","元气互吐欱，谁能测终始。","水族并流形，万象纷呈诡。","鲛室胡扃闭，龙宫孰造址。","坤元何糺轧，真采或韬閟。","兹理自茫茫，笑彼然犀子。"]},{"t":"陪王老师鸣山宴集得地字","f":"五言古诗","c":["云壑郁芊绵，瑶林耸苍翠。","冠盖盛遨游，良辰惬胜地。","岩际张华组，花前驱小队。","鸟啼山籁寂，鹤舞松阴碎。","轻霞槛外浮，落蕊杯中坠。","閒听单父琴，暂辍东山妓。","相看倒接䍦，宛似习池醉。"]},{"t":"伤逝 其一","f":"五言古诗","c":["奔湍宁驻壑，颓云岂归山。","眷我室中人，一逝永无还。","结发事中闺，柔嘉静且閒。","冰操亮为矢，服约志所欢。","漫云沾薄禄，与尔共岁寒。","万里赴燕台，执手涕汎澜。","穷途思比翼，中道忽摧残。","生平一寸心，付此七尺棺。","丈夫虽刚肠，坐感百忧攒。","即事犹可了，循念始难安。"]},{"t":"伤逝 其二","f":"五言古诗","c":["候纩良已窅，叩音亦云寂。","昔日深闺人，今为泉下客。","芳华犹未歇，零露忽成夕。","重衿结罗襦，珍重藏遗魄。","黄肠一以掩，百年不复觌。","欲掩还踟蹰，临诀重悽恻。"]},{"t":"伤逝 其三","f":"五言古诗","c":["仪床虚自设，灵爽亦何之。","伫立望空帏，姗姗来何迟。","謦欬如可即，长寐乃于兹。","抚棺寂不闻，恸擗复逾时。","痛定还嘿嘿，咄嗟此情痴。"]},{"t":"伤逝 其四","f":"五言古诗","c":["嬿婉倏已捐，室庐亦芜漫。","遗器经手泽，狼籍任漂散。","束素妥冥魂，虚位陈遗玩。","镜台永谢影，蕙草空依幔。","凄凄风动壁，沈沈秋方晏。","盘餐徒在兹，无人来举案。"]},{"t":"伤逝 其五","f":"五言古诗","c":["悲风从何来，流响度长廊。","静聆怯营魂，潜身归洞房。","兰缸犹未灭，黯淡杳无光。","触物易萦绪，忧来讵有方。","残椸积埃尘，颠倒乱衣裳。","针刺存箧笥，刀尺委巾箱。","高壁留遗挂，香奁卸旧妆。","缄封时一觌，纡回自忖量。","弥恋知无益，弃置复难忘。"]},{"t":"对庭树","f":"五言律诗","c":["不见室中人，空对庭前树。","庭树发新葩，攀条人已故。","荒苔封旧径，犹记游行所。","幽禽亦何知，两两花间语。"]},{"t":"閒馆书怀","f":"五言古诗","c":["单居寡灌悰，含悽即空馆。","瑶琴久绝御，架上残书乱。","愁绪纷无次，据案漫捉管。","对影怜影只，约带减腰半。","恍恍坐如驰，一夕玄鬓换。"]},{"t":"拨闷","f":"五言古诗","c":["悼往事已延，绵思耿如昨。","门楹亦洒扫，香闺仍封钥。","流尘结绮窗，丝罥罥罗幕。","燕归旧巢空，蜂度馀花落。","悟彼芳景徂，如何不欢谑。","冥心谢区累，达生庶可托。"]},{"t":"悲永日","f":"五言古诗","c":["滞绪已恹恹，迟景倦方永。","谁云酒破愁，愁来复难整。","虚槛飒回飙，萧条山阁静。","几案俨遗翰，丹青幻留影。","对此还如梦，悟来方一省。"]},{"t":"行家园","f":"五言律诗","c":["端居旷时序，谁怜偕隐心。","园庐一经涉，欢晤永沈沈。","昔时手种树，槭槭欲成阴。","后来谁攀折，叹息思难任。"]},{"t":"经外家","f":"五言古诗","c":["来过故人宅，不见故时人。","庭卉犹含绿，萧条空复春。","忆昔同拜庆，花下列文茵。","苍苔留芳躅，閒阶想袜尘。","犹馀欢赏地，坐此怅佳辰。","时芳宛如昨，翻令人意新。"]},{"t":"对月","f":"五言律诗","c":["秋宇何寥廓，澹宕来轻飔。","皓月流空庭，清光鉴薄帏。","坐揽方盈抱，迟回不在兹。","逾怀平生欢，延睇独移时。"]},{"t":"秋夜","f":"五言律诗","c":["重纩亦不暖，辗转对空房。","谁谓百年促，偏令此夜长。","白露涂前除，崇兰委令芳。","端居独无偶，坐惜此时光。"]},{"t":"营墓","f":"五言古诗","c":["东郊卜隐地，今为埋玉坟。","凄凉一抔土，芳草无冬春。","曾当同燕寝，岁月尚逡巡。","松楸手自植，为尔表贞珉。","重泉尚虚左，旦暮谁为亲。","百年鼎鼎流，嗟此暂时人。"]},{"t":"苦雨柬陈宪副吴山人","f":"五言古诗","c":["终宵苦淫潦，檐溜如倾盎。","泽国成沮洳，萧斋更飒爽。","入帘讶淅沥，迸阶倏沆漭。","谛听耳目骇，静憩营魂恍。","推枕不成梦，端居纡閒想。","拨炉香已烬，挑灯焰不朗。","奔雷时一吼，划电光相荡。","避湿徙藜床，张帷护书幌。","纸窗任模糊，木屏恣偃仰。","枝丫惊果坠，林欹搅叶响。","傍砌移盘卉，当阶决淤坏。","怀人在城闉，如隔东西瀼。","青尊时自把，玄言谁共奖。","安得桃叶舟，移泊荷花荡。"]},{"t":"吴非熊同梁伯静过访山斋分得里字","f":"五言古诗","c":["柴门日夕扃，委巷谢尘轨。","自非素心人，寻幽曷至此。","晤言无俗韵，酬对绝繁礼。","间庭纵遐玩，班坐周苔戺。","山厨任简率，狼藉置杯匕。","香脆剪秋莼，寒日剖霜柿。","颓阳下夕阴，茶烟在竹里。"]},{"t":"过非熊馆问病同杨亦琳","f":"五言古诗","c":["周南岂留滞，文园聊卧疾。","閒馆肃沈沈，残架卷书帙。","窗隙逗流光，晶荧见朝日。","宵眠乡梦馀，晨起梳头毕。","芝捡秘丹方，石铛养苓朮。","羁居寡尘萦，寝坐兴非一。","渊明既止酒，维摩亦持律。","北户来轻飔，负暄对扪虱。"]},{"t":"閒斋对雨同吴非熊作","f":"五言古诗","c":["凉雨滴未收，微阳复放景。","烁叶助澄鲜，连山带远净。","况此对知心，萧然发清兴。","返照犹在壁，新月出林顶。","笋舆唤不来，念子归途泞。"]},{"t":"喜非熊再访","f":"古风","c":["乘兴非夙期，园林恣游诣。","何须惊剥啄，荆扉任启闭。","萧斋午梦馀，对客尚蒙袂。","爱此盘石閒，袅袅荫丛筀。","商风搅林木，纠干互相?。","语长觞可命，坐久肴一继。","何处有清音，高柳玄蝉嘒。"]},{"t":"重过非熊馆","f":"五言律诗","c":["金风虽零露，园林尚葱蔚。","以我过从数，谅子羁怀慰。","窗隙挂蟏蛸，墙隈啼络纬。","中坐有馀清，茶烟鼎初沸。"]},{"t":"将北征书示同志","f":"五言古诗","c":["夙昔综文苑，委志赴明时。","姓名误通籍，六载乃于兹。","栖迟两遭刖，抱璞翻自疑。","投策返故林，开径剪茆茨。","容膝谅可安，宁复较崇庳。","北窗纳远岫，南荣列秀蕤。","幽谷变时禽，芳塘漾碧漪。","对此欣有悟，偃息忘其疲。","倦鸟思安巢，岂不恋旧枝。","云胡牵远役，行与家山辞。","云萝恰相恋，猿鹤有馀悲。","登堂慰慈母，且复念群儿。","中馈久无人，寒燠谁当知。","童仆三五辈，各各顾其私。","居者自为欢，行者惨不怡。","残书粗检点，琴剑莽无姿。","敝絮足禦寒，裋褐固其宜。","曰余婴世网，业已谢耘耔。","干世非长略，征途杳何之。","自咤还自哂，书为同调贻。"]},{"t":"送舍弟应试","f":"五言律诗","c":["少年识事浅，所志学干禄。","虽误点贤书，不饱侏儒粟。","子当奋脩翎，余亦理征轴。","薄技倘一售，还山艺松竹。"]},{"t":"送吴非熊还新安","f":"五言古诗","c":["曰余抱微尚，息影卧邱樊。","托交在文翰，投契比金兰。","晚得吴非熊，使我吐肺肝。","芳词郁春蕙，素波扬清澜。","高齐啸咏馀，澹语皆成欢。","萝径莽森羽，修竹荫檀栾。","夜寝连襟裯，晨兴共盘餐。","良晤方在兹，胡令别绪攒。","余将游燕市，子言归故山。","故山邈以远，广川间层峦。","疲策惮脩坂，颓颜鉴逝湍。","风波已倦涉，况乃岁时殚。","脾衰妨旅食，形怯讶衣单。","行橐正萧条，归梦徒盘桓。","送君从此去，关河杳漫漫。","还山饵芝术，洞中日月宽。"]},{"t":"见郊外掩骼慨然有赋示同社诸子","f":"五言古诗","c":["恻帽睇崇冈，迟迟遵古路。","不知何人骨，何年饱霜露。","撑拄乱如麻，填委半新故。","蟠坭穴蚁蝼，带胔饲狐兔。","蜕残不辨形，棺朽空留蠹。","衾赗久已縻，顶趾纷异处。","轻轻似解萚，栩栩如堕羽。","白经野烧燔，青含宿草互。","风雨洗膻秽，尘沙蚀垢污。","荒凉谁是主，狼藉那能数。","飞鸟惨不鸣，行人却且顾。","衣殣有遗言，掩骼岂虚募。","瓦棺恰盖藏，丛冢就安措。","生前异趋舍，托体同邱墓。","姓字原不谙，宁复知生娶。","无碑可勒铭，有坟不封树。","丁癸无定向，圹域弛禁步。","立石祀土神，牛羊任颠仆。","杳杳青郊迥，萧萧白杨暮。","巫阳讵可招，冥漠谁当愬。","前身已茫昧，曷解辨冥趣。","且置蒙庄说，枕髅聊待寤。"]},{"t":"戏咏古翁仲","f":"五言律诗","c":["蹲蹲立两旁，寒暑罔移易。","既作巨人观，胡为墓下役。","穷泉永不晨，徒留石人迹。","不知年代深，暮雨空山碧。"]},{"t":"閒斋对月","f":"五言律诗","c":["夕阴忽已敛，皓魄夜流明。","娟娟来媚人，揽之有馀清。","伫立望河汉，不知霜露零。","群动皆有息，伊余独何营。"]},{"t":"邻哭","f":"五言律诗","c":["但闻邻人哭，未知哭者谁。","眷彼哭中人，悲欢宁复知。","闻者亦何关，顾令心不怡。","振衣步前除，中庭露下时。"]},{"t":"秋日同万益之刘平子梁伯静李世桢张嘉脩舍弟文度登圭峰得北字","f":"五言古诗","c":["阳林半委蕤，芳郊澹野色。","出郭面寒山，泉流暗通洫。","小桥石径转，岗势周纡直。","萝深樵术微，石埼云磴仄。","遥涧绝超距，崇巘顿跻陟。","宛见长空外，冥濛辨水域。","同游兴飞翻，余憩禅房息。","午钟清梦残，香厨荐斋食。","忻然聊一饱，缓步云崖侧。","山花偏殢人，山鸟如旧识。","洞閜阴飔生，峰亏阳景匿。","蝉鸣谷籁幽，鲂跃潭光湜。","浮觞汎瀑渟，纪韵刊苔蚀。","清晖憺可娱，宴坐移景刻。","前山夕霭敛，髣髴故蹊惑。","逢僧乞食归，导我过桥北。"]},{"t":"山中呈万益之刘平子用平子韵","f":"五言古诗","c":["连岗径回复，踰洞复深广。","吐欱通元气，峥嵘擘仙掌。","嵌空石乳垂，注壑寒流瀁。","同游有二仲，俱抱烟霄想。","崖欹袅自攀，葛弱扪可上。","泠然发长啸，罡风来飒爽。","青莎匝径繁，红蓼沿溪长。","访道憩松阴，礼磬来方丈。","禅关如可托，于此契幽赏。"]},{"t":"赠万益之","f":"五言古诗","c":["常闻静者言，澹泊栖精魂。","之子抱微尚，抗志谢世樊。","原无昏浊染，安用漱灵根。","五岳游其四，九州何足论。","察人洞腑脏，撷草辨寒温。","断酒持清斋，端居不立言。","和光世可混，抱冲道自存。","余怀方外踪，于子情弥敦。"]},{"t":"赠刘平子","f":"五言古诗","c":["刘生伯伦裔，沈冥亦耽酒。","饮可容数升，其才有八斗。","半酣濡墨沈，挥笔如埽帚。","清如风入篁，细似丝抽藕。","余本畸世人，迂疏独相耦。","晨游袂必联，清夜门可叩。","摊书曰满床，压酒亦盈缶。","子来聊共斟，且把新诗纠。"]},{"t":"同万益之刘平子梁伯静嘉荐侄出郭酹吴非熊","f":"五言古诗","c":["出郭霜气微，孤村澹斜阳。","依依闻邻笛，我怀憯以怆。","眷彼同心人，胡为委山岗。","海国三千里，游魂归路长。","入门不见人，但见此黄肠。","旅葵蔓荒阶，枯藓上颓墙。","思子平生欢，微吟暗自伤。","蔬盘罗野簌，且复荐壶觞。","放声聊一哭，掩袂出长廊。"]},{"t":"春日答何文起见怀","f":"五言古诗","c":["韶景延初霁，晨曦灿中林。","未测西林里，春华几许深。","阳陂擢新荑，幽谷啭鸣禽。","流辉如曳练，兴霞似卓簪。","恻恻岁光迈，悠悠恋赏音。","岂不眷西皋，轸念滞愁霖。","故人枉惠好，投我怀春吟。","以彼玄栖想，怜余畸世心。","劲翮知投薄，脩鳞思泳浔。","嘤鸣自有感，长谣报断金。"]},{"t":"和平子寄宿中林","f":"五言古诗","c":["只在此林庐，同欢不同宿。","书声近相闻，得句还相续。","凉雨澹幽轩，宵吟恒达旭。","晨兴理盥栉，散虑恣遐瞩。","叶光鉴初影，房栊霭新绿。","池鱼弄浅漪，谷鸟啼深竹。","耳目既无营，舒散任童仆。","入林虽未深，喜无往来躅。"]},{"t":"月上","f":"五言古诗","c":["前山白一点，林木未分晓。","凉露濯素辉，薄云承初照。","虚壁乍流光，隔帘看尚窅。"]},{"t":"溪馆夜坐 其一","f":"五言律诗","c":["空阶草露泫，乍闻凉雨滴。","不觉池流入，潮痕添一尺。","残月印波光，遥遥荡孤石。","风林叶一声，恍若有人迹。"]},{"t":"溪馆夜坐 其二","f":"五言律诗","c":["开门无远近，淡漠孤烟生。","林光火乍迸，短桥人独行。","众鸟方归息，草虫时一鸣。","溪流杂雨响，断续间疏更。"]},{"t":"溪馆夜坐 其三","f":"五言律诗","c":["野竹乱无次，昏鸦栖不定。","灯寒四壁青，坐久春衣冷。","纷虑忽以閒，微酲亦初醒。","榻畔来疏钟，泠然发空警。"]},{"t":"溪馆夜坐 其四","f":"五言律诗","c":["人语稍停喧，夜作犹未歇。","隔浦悬疏灯，斜照疏林月。","清溪漫以涨，衣荇近可掇。","凌波望若空，孤光去复没。"]},{"t":"游通天岩","f":"五言古诗","c":["团团俯众岫，岩峦夐茜峭。","凿磴曲盘空，沿溪共缭绕。","阴壁炫霞光，残林间疏照。","始入洞如迷，屡穷胜未了。","居然一壑尊，俯揽众岫小。","潦倒石疑崩，撑云复夭矫。","一岭千重岩，千岩千佛绕。","随相露庄严，因势藏窈窕。","初作洞閜观，转疑入冥窅。","箭括微通天，攀扪出象表。","如来丈六躯，蹲立云峰渺。","天龙周拥护，狮象莽奔跳。","遐哉开辟初，洵矣良工妙。","苍崖题字遍，阅人知多少。","云盖石层层，倒卓莲花袅。","孤高难久立，注视营魂掉。","搴萝才一憩，循径出松杪。","石龛闻钟声，馀响咽虚窍。","阳光渐匿景，阴飔来悄悄。","清境恋遐搜，疲力阻延眺。","暂与山灵辞，后期还杳杳。"]},{"t":"游滴水岩","f":"五言古诗","c":["怪底兹山奇，而无泉与潭。","山僧聆我言，指我滴水岩。","扪萝才一上，片石亦崭崭。","既无瀑布喷，亦非水镜涵。","石面微沾润，点滴才二三。","手接不盈掬，舌餂有微甘。","借问僧徒众，何以救渴馋。","山僧笑不言，引我度粗蓝。","香厨间石壁，暗用竹笕探。","青涧泻无声，沄沄注虚墰。","墰下疏清渠，馀流分绕龛。","霖暵无增减，冬夏常湛湛。","酌我香钵盂，令我解烦惔。","始疑造物私，旋悟智者耽。","涓涓成江河，斯语匪虚谈。"]},{"t":"游忘归岩","f":"五言古诗","c":["兹岩号忘归，我是怀归客。","于焉展芳游，忻赏迨晨夕。","前峰登陟倦，来就岩际息。","石梁架丹岭，蜿蜿苍龙脊。","琳宇摩穹霄，阴房透地脉。","恍疑仙子居，尘凡通一隙。","乍闯已飞腾，旋入转警悟。","欹崖倒欲垂，箭光忽注射。","叫窱壁留飔，砰硡籁生舄。","却疑鼠斗穴，翻似鲮穿碛。","穷崖别有天，顿与前境隔。","蒙茸缀涧花，怪崄露巉石。","灵迹既韬秘，游人遂克斥。","虚亭占绝巘，恰可布筵席。","山影摇深杯，夕阳对岸帻。","尊罍渐以罄，仆马频催逼。","聊舒一日悰，怅矣牵缘役。"]},{"t":"洞口僧房","f":"五言古诗","c":["洞口莽回复，石径亦盘纡。","茆茨藏山腹，云是老僧居。","问僧何名氏，住山几臈馀。","岁月浑不记，暗想结茆初。","檐树高于屋，草长没阶除。","自来此山住，迥与世人疏。","下山为汲水，入园为摘蔬。","同在山中人，不到老僧庐。"]},{"t":"庄家","f":"五言古诗","c":["林里桔槔悬，咿咿辘轳响。","郊原雨尚稀，车水灌蔬壤。","崩塘差补葺，预防春潦涨。","菜甲已破坭，鱼苗亦吹浪。","邻里助辛勤，樽酒相遗饷。","瓶盎幸馀储，牛羊渐壮旺。","生事泊无忧，开怀且尽量。"]},{"t":"庄田僧舍","f":"五言律诗","c":["山僧不住山，庄上结茆屋。","川原新雨过，处处啼布谷。","农家春事忙，晓出驱黄犊。","蔓草偃荆扉，山僧还独宿。"]},{"t":"过东华旧寺访凌空上人不遇因赠御空上人","f":"五言古诗","c":["溪边寻古院，迢迢向草莱。","微雨洒郊坰，禅扉傍晓开。","山僧不相识，借问客何来。","十年重到此，殿宇委尘埃。","补葺成新搆，非复故亭台。","却觅临池处，僧指沙砾堆。","留题壁已没，空想旧莓苔。","高基半就夷，洼涧积嵬嵬。","因悟世界浮，还将陵谷推。","随讯主院僧，答言往天台。","门徒亦星散，客至若为陪。","香饭供蒲笋，破例款良醅。","嘿嘿自萦抱，开怀且尽杯。"]},{"t":"游兴隆庵","f":"五言古诗","c":["断碛绝行径，石溜崩湍泻。","盘山几转深，竹院殊疏野。","云壑藏诸天，嵬嵬搆广厦。","游人占画桥，山僧闭兰若。","摊经尚未收，晒衲古廊下。"]},{"t":"游观音岩","f":"五言古诗","c":["陡绝一悬崖，跻攀断云术。","却从烟际渡，如捣鼋鼍窟。","洞口出波心，萦阶琢山骨。","扪摩石压面，登顿头低膝。","涧绝施层栈，厓巉引脩繂。","缭绕蜗旋壳，高庳蚁封垤。","诡幻非一态，奇崄难具悉。","行人去窅窅，忽讶半空出。","大士趺莲花，慈容照慧日。","阳鏬漏天光，阴窦秘泉潏。","碍石过云迟，飘帆转溜疾。","蹑景忽如驰，回睇惘若失。","清游难久恋，灵迹洵无匹。"]},{"t":"新置斗室颜曰不住庵因纪以诗","f":"五言古诗","c":["双脚似转蓬，如何得暂住。","我身随脚转，歘若空中雾。","何况身外居，亦复等行路。","新置一间房，副以常供具。","何须用此房，如行小歇步。","竹帘和木榻，茶铛并酒瓠。","草草略完整，一一就安厝。","坳池潴积水，小有濠濮趣。","盆鱼四五头，时花两三树。","我来粗洒扫，我去暂扃锢。","不借俗人居，墙壁忌沾污。","不用家童守，无甚可将护。","辟如解绦鸟，岂必恋空笯。","以我幻来身，权寄遽芦寓。","取名不住庵，庵非常住故。"]},{"t":"访卢一清次其见赠韵","f":"五言古诗","c":["夕霭澹城阴，寻君到水石。","门外新潮涨，瀰漫迸阶入。","爽然衡宇清，琴书散幽寂。","庭桧留轻飔，恰与炎歊敌。","宾朋既数过，雅韵时相及。","閒拈壁上题，雌黄任胸臆。","境閟夏如秋，阴虫已唧唧。","烟里闻歌声，渔灯泊沙脊。"]},{"t":"答赠高斗仲学博","f":"五言古诗","c":["我有一素琴，寥寥韵在兹。","缅怀钟子期，惜我不同时。","流泉封玉匣，清响为谁挥。","高凉有韵士，雄情太古姿。","大雅振洪音，明堂奏清夷。","顾我爨下质，泠然惬心知。","为君重拂拭，长鸣安敢辞。","胶漆亮不渝，永言嗣夙徽。"]},{"t":"登漱流石吊朱少贞处士","f":"五言古诗","c":["众山忽皆响，泠泠激石音。","何年寺飞来，石乃遗至今。","幻迹半明昧，灵气无销沈。","不见漱流人，空闻石上吟。","流水自千古，登临谁晤心。","日暝孤猿嗥，凄寒不可任。"]},{"t":"别后寄龙门张明府","f":"五言古诗","c":["停云在何处，渺渺天一隅。","龙门百尺浪，高高不可踰。","欲附长风翼，路远不我需。","忼慨临江干，我怀正郁纡。","古人感知己，不惜捐其躯。","平生国士心，欲报将焉如。","愿言流景铄，千秋竹帛垂。","缄书托来鸿，聊以蔽余思。"]},{"t":"重九登高","f":"五言古诗","c":["山期不约同，九九敦嘉节。","兹辰虽云迈，时芳尚可悦。","薄言展燕游，欢赏偕时哲。","冠履既骈辏，尊罍亦互挈。","崇冈才登践，遂乃凌巀业。","孤亭踞其胜，空翠若可撷。","苔石随所据，区豆离离列。","风萝入杯影，菊蕊亦纷缀。","游情竟日晡，猿鸟助清切。","馀花插帽檐，归路穿松垤。"]},{"t":"舆梦","f":"五言古诗","c":["破梦登篮舆，舆中成一梦。","形神恍不交，微息寄人踵。","低昂与之俱，方酣忽一动。","视听两参差，魂飘体亦纵。","零乱少成章，痴人说何用。"]},{"t":"尘浪","f":"五言古诗","c":["舆行尘浪中，有如江上船。","长风吹沙立，白埃漫苍天。","油幕随飘蓬，肩趾失其权。","平坡亦登顿，十步九翻颠。","借憩古树阴，枝搅软如绵。","疲役思投止，青野断人烟。","殷勤慰仆御，尽力更挨延。"]},{"t":"即次","f":"五言古诗","c":["酸风射眸子，尘堁莽迷离。","遥闻犬吠声，行近见茆茨。","主人揖客入，不暇交言辞。","衣裘刚抖擞，沙砾上鬓髭。","倦马向枥鸣，童仆亦苦疲。","权迂一日程，即次暂于兹。"]},{"t":"迁馆","f":"五言古诗","c":["久假而不归，乌知非我室。","千金重卜邻，况乃连兄侄。","以此为因依，周旋日已密。","侍儿知花性，权令司纸笔。","频来藉花茵，琴尊间编帙。","或往叩邻扉，胡床欢促膝。","一年周一迁，光景流波疾。","芘身久仰人，茫茫余自失。","物贵返厥初，旭日行当出。","图书归旧厨，几案留净室。","庭木醉霜华，朱柿与黄橘。","人禽竞扳窥，呵护从此毕。","我身等蘧芦，宁暇儿女恤。","谢主兼别邻，返钥仍封鐍。"]},{"t":"暑甚呼童取车帱障日色戏咏","f":"五言古诗","c":["油碧作车帱，周遭八九尺。","向来御霜霰，今以顿高壁。","燕京六月天，骄阳酷了得。","炎埃捲白涛，地作龟文坼。","行渴望眢井，无荫可憩息。","居人惮种树，蚊虻之所宅。","炎暑尚可那，蚊虻嘴太螫。","停午火轮飞，家家匿檐隙。","庭庑下布帘，聊以遮日炙。","间有缚高棚，紬箔编丛荻。","余居僦委巷，蜗庐矮且窄。","欲作棚箔遮，千钱亦可惜。","猛然思敝帱，堪与骄阳敌。","先乃擞埃尘，次以清泉涤。","悬梯上屋牙，施绳垂两纆。","展开琉璃幔，恰恰当甔甋。","洞户散郁蒸，兼豁疏棂格。","砌除屏诸有，绀绿摇空碧。","回风捲翠旗，似洒蕉窗色。","又如行风涛，布帆饱半席。","热恼想顿蠲，兴居随以适。","南海蒲葵扇，湘潭斑竹席。","几席虽不良，揩抹净如拭。","笔研差不恶，副以奇书籍。","平头持秃帚，扫灭苍蝇迹。","倦来枕书卧，兴或弄笔墨。","以此閒功课，颓阳易向夕。","纵非羲皇侣，权谢褦襶客。"]},{"t":"九日区彦斯昆玉置酒黄云山宴集余不终席去寻得贻诗辄有此答","f":"五言古诗","c":["公子敬邀客，鲜服盛遨游。","遨游叶佳节，爽然挹清秋。","晴天敛微云，空壑野烟收。","轩盖临广陌，华筵敞崇邱。","张祖披林皋，移觞泛曲流。","山厨出桂醑，列俎荐琼羞。","流连展欢谑，洵美非余俦。","抗手谢徒侣，回镳遵道周。","良朋眷清睇，顾我不可留。","沈吟逸响发，结念灵思抽。","耽寂多违豫，思离常轸忧。","兴言申斯咏，庶以敦好仇。"]},{"t":"送蒋伯瑞游北雍","f":"五言古诗","c":["金飙肃桂宇，噭噭征鸿呼。","之子事远游，马首傃川涂。","计程八千里，抵役在帝都。","帝都何巨鹿，九域十二衢。","东阁罗英髦，西昆储图书。","观光来上国，策名在修途。","大鹏负六翮，安能恋枌榆。","浮沈各异尚，何以慰区区。","愿言崇令德，爱子千金躯。"]},{"t":"读说命三篇有感","f":"五言古诗","c":["一木支大厦，梁栋奠弘基。","从来师济辈，弼亮为先资。","维帝锡良弼，陬野彰容仪。","谁知版筑人，俨然帝者师。","金砺木从绳，济川调鼎彝。","煌煌三命篇，对扬乃在兹。","览编三叹息，千古渺难追。","白骑匪无良，帝赉此其时。"]},{"t":"杂怀 其一","f":"五言律诗","c":["羁兽走索群，离禽恋俦匹。","以兹蓬藋心，钦子蕙兰质。","雄谈驱今占，高谊薄云日。","何以表余衷，以胶投于漆。"]},{"t":"杂怀 其二","f":"五言律诗","c":["世途多陷缺，倾覆有千端。","悠悠复悠悠，贫交古所难。","苍蝇施点缀，白壁滋其盘。","素心苟不渝，相视但忘言。"]},{"t":"杂怀 其三","f":"五言律诗","c":["西方有一鸟，五色美而都。","非鸿亦非鹄，曰凤乃其雏。","群鹗甘腐鼠，嚇嚇竞噪呼。","相将厉六翮，一举凌天衢。"]},{"t":"杂怀 其四","f":"五言律诗","c":["屏居谢尘营，委志事文艺。","一语破鸿濛，便欲当吾世。","名山无改移，金石有刓敝。","落落千秋情，伊谁得深谛。"]},{"t":"杂怀 其五","f":"五言律诗","c":["鸷百不如鹗，于人亦复然。","一人是知己，胡用客三千。","悠悠行路间，凉炎迭为权。","去去勿复道，索居且自全。"]},{"t":"杂怀 其六","f":"五言律诗","c":["岂无绿绮琴，尘埃不复理。","拂拭向君弹，泠然中宫徵。","古有钟子期，斯人今已矣。","抱琴试问君，高山定流水。"]},{"t":"杂怀 其七","f":"五言律诗","c":["峨峨百尺台，高高与云齐。","中有千仞松，飒飒凌丹梯。","清夜不能寐，揽衣步空阶。","徘徊复徘徊，皓月照苍崖。"]},{"t":"杂怀 其八","f":"五言律诗","c":["方舟溯浅流，息棹临河岸。","深雨洒轻飔，滴滴珠光乱。","薄言采菲芷，聊以恣燕婉。","盈盈衣带水，一望肝肠断。"]},{"t":"杂怀 其九","f":"五言律诗","c":["翩翩谁家子，玉勒青骢马。","经过大道旁，鲜服都而冶。","杯酒矜豪雄，颜色轻相假。","而我独閒居，闭户寒窗下。"]},{"t":"杂怀 其十","f":"五言律诗","c":["少年学书剑，老大无成名。","黄金结客尽，白眼递相轻。","薄有盈尊酒，与子话寒盟。","一斟复一酌，悠悠见平生。"]},{"t":"走笔答蒋慰功见邀","f":"五言古诗","c":["平生不饮酒，三酌即颓然。","有时倾一石，白眼望青天。","浊醪有妙理，可以对少年。","公子雅敬客，高馆张华筵。","玉盘贮霜蕤，朵朵压金钱。","殷勤枉惠好，飞翰洒瑶笺。","但能对绿蚁，我来瓮底眠。"]},{"t":"晚步","f":"五言古诗","c":["端居不自好，散步出城闉。","偶然适相值，俱是意中人。","交谈未及毕，坦率露清真。","寒云弥江干，中天月一轮。","徘徊不忍别，各各恋情亲。"]},{"t":"调诸子七首 其一 邓山人","f":"五言律诗","c":["山人少机心，语嘿恣胸臆。","木盘盛青蕉，擎出当街食。","双鬓影婆娑，皓月与之白。","放浪少年间，乃自得其得。"]},{"t":"调诸子七首 其二 陈生","f":"五言律诗","c":["陈生工画眉，湾湾似新月。","每对月华生，忧心以惙惙。","离家将一载，思家无断绝。","何日大刀头，相看圆又缺。"]},{"t":"调诸子七首 其三 麦道人","f":"五言律诗","c":["麦生颇好道，时时茹青斋。","虽然不吃酒，却看太常妻。","有琴不会弹，摩娑惬所怀。","诺诺复尔尔，油油与之偕。"]},{"t":"调诸子七首 其四 梁生","f":"五言律诗","c":["梁生破素产，佔毕学为儒。","间为人卜地，母乃饥所驱。","策杖凌高巅，猿猱也不如。","得钱不作活，时时收古书。"]},{"t":"调诸子七首 其五 杨生","f":"五言律诗","c":["杨生雅可亲，呐呐不出口。","含笑当百言，逢人却且走。","一片少年心，誓死不相负。","那知末路交，雨云翻覆手。"]},{"t":"调诸子七首 其六 蒋生","f":"五言律诗","c":["矫矫蒋生郎，微尚差不俗。","千金买阿娇，贮之黄金屋。","时时屏之去，曰母溷我目。","独呼小奚童，案头展书读。"]},{"t":"调诸子七首 其七 嘉荐侄","f":"五言律诗","c":["阿荐固善贫，厥性寡所谐。","时时倾绿醑，顿顿啖青齑。","胡不放两眉，跌宕恣心怀。","有酒醉便得，无钱使亦佳。"]},{"t":"送菊蒋懋功","f":"五言古诗","c":["金葩耀素节，的□吐奇姿。","绚云被灼灼，溥露宛垂垂。","对此娱芳辰，眷言赠故知。","朝荐君子堂，百卉竞葳蕤。","宁知岁寒心，忻赏必于兹。"]},{"t":"周明府席中赋赠","f":"五言古诗","c":["使君昔朝天，凫影傍云翔。","今日瞻双凫，还集旧河阳。","河阳千万户，处处沾化雨。","仙萼被华阴，映带甘棠树。","树影何离离，偏萦去日思。","居人严呵护，父老望旌旗。","使君褰帷入，甘雨随车湿。","冠盖夹毂迎，吏人捧案立。","吏散官衙清，瑶琴拂匣鸣。","泠然发新韵，彷佛旧清声。","声清何浏浏，疑是南薰奏。","一弹氛埃涤，再弹民物阜。","愿君理此曲，长奏南风前。","更以献明廷，天子寿万年。"]},{"t":"生日","f":"五言古诗","c":["今辰复何辰，杪秋月既望。","三十三年前，此时吾以降。","流光倏如驶，毕竟成何状。","去日已悠悠，来者亦莽莽。","酌酒以欢怀，颓然且自放。"]},{"t":"古瓦盆〔歌〕","f":"五言古诗","c":["兹物谁知贵，沙土埏埴成。","既无瑰异姿，了不殊众形。","为器充庖■，受水同瓶罂。","幸不遭毁残，犹然保坚贞。","年深貌质故，摩久刓廉棱。","黯如入土色，叩作戛木声。","同尘受涅缁，止水湛澄泓。","清可鉴毛发，澹能怡野情。","即此已可爱，玩弄幽意生。"]},{"t":"题松泉雅适卷","f":"五言古诗","c":["泠泠百丈泉，迸流穿石罅。","上有千仞松，盘拿互相亚。","寒飙六月起，惊涛莽崩泻。","龙鳞珠雾喷，麈尾箭波射。","葱郁似含春，清凉可消夏。","閟岩夐深靓，悬磴绝潇洒。","兰楣支杏梁，缥缈连云架。","药臼倚松根，茶寮当竹下。","石几净无尘，丹书研露写。","苔印芒履滑，枝碍罗巾絓。","观世得沈冥，寄怀任骚雅。","名利两蜗牛，乾坤一指马。","言从静者居，请息俗士驾。"]},{"t":"别韩孟郁","f":"五言古诗","c":["夙昔奉君子，妙言契金兰。","摘文奋逸藻，绝景蹑高坛。","大雅久沈冥，沦代在其间。","竦身赴瑶池，接翮汎清澜。","云胡中道乖，临风戢飞翰。","羽毛正催颓，文采失斓斑。","流波逝东海，卷蓬没西山。","轸念属睽违，何由展话言。","京洛盛遨游，鲜服簪华冠。","敝裘履霜雪，谁怜范叔寒。","岂无绿绮琴，知音久不弹。","因风扬妙曲，泠泠中肺肝。","所贵心不渝，母令积思攒。"]},{"t":"端午舟中述怀","f":"五言古诗","c":["凌冬辞乡邑，盛夏滞京师。","戒途理舟楫，行行赴郊圻。","水宿淹宵晨，我思如渴饥。","江流汩滔天，逆浪愆还期。","况及陶嘉节，怅焉念旧畿。","游子自有怀，明发心不怡。","哀哀我二人，何由见容仪。","揆辰双讳届，旬日乃于兹。","沿流撷芳芷，欲荐不能持。","弥恨亘终天，悠悠当告谁。","怀禄既不逮，浮名空尔为。","誓将理素业，馌饷耕东菑。"]},{"t":"课圃","f":"五言古诗","c":["搆室邻榛莽，为园亦于兹。","讵云久不窥，荒蔓良易滋。","禽鱼习主懒，花睡亦无时。","念我当远行，灌锄应属谁。","疏畦刚拣砾，删冗暂披枝。","先乃去其甚，馀亦以次为。","室庐众共处，偏我独园私。","宁为圃场植，草木养閒姿。","人情狎故昵，厌每生于离。","顾我为园心，去住罔间之。","刺刺语园子，童亦笑予痴。"]},{"t":"元旦即事","f":"五言古诗","c":["闻鸡未觉晓，辨色始知旦。","谯楼鼓一声，惊起晨鸦散。","墙隈爆竹响，屋角岁灯烁。","门前已戒御，中厨方进盥。","罗衣御旧尘，榆火试新爨。","望门投空刺，东里复西闬。","蹲蹲衢巷窄，楚楚冠裳焕。","儿童庆岁添，老大祝违算。","日月双跳丸，暗把流光弹。"]},{"t":"题梁伯静斋壁","f":"五言律诗","c":["山人不近山，一廛还近市。","柴门日掩开，市声不到耳。","斋中何所有，一榻而已矣。","举案对山妻，挟书授儿子。"]},{"t":"胭脂花","f":"五言古诗","c":["山林有蔓卉，香色亦纤新。","绾髻能增艳，和铅可点唇。","空斋宁用此，聊藉缀苔茵。"]},{"t":"陈宪副招同吴非熊集大云寺，分得怀字","f":"五言古诗","c":["黝壑莽回互，绀宇藏其厓。","金风度檐铃，堕叶满庭阶。","夙负云林想，兹忻朋好偕。","纡回历郊坰，登践穷幽崖。","香厨戒衲子，促席唤歌娃。","徐倾北海罍，复啖太常斋。","竹戛棋声碎，风回舞袖徘。","入云磬袅枭，出谷鸟喈喈。","草色偏萦袂，苔文欲印鞋。","剥藓看残碣，窥林拾堕钗。","延赏偕欢悰，沈吟叶所怀。","山霭晚逾翠，秋容望转佳。","林翳光忽暝，露泫径深霾。","归路忘其疲，暮雨糁长街。"]},{"t":"金粟泉","f":"五言古诗","c":["诸天空际浮，海水周其外。","颢气吹鸿濛，天水相映带。","荷叶漾珠光，泓碧在深霭。","渟潴不见流，众酌任所丐。","海味搅盐汁，一点如甘霈。","空洞何吐茹，香粟喷金濑。","仙葩不依凡，著土仅芽蒂。","冥心观物始，兹理曷茫昧。","天风吹海涛，众灵莽奔会。","冷然毛骨清，三酌营魂怖。"]},{"t":"白龙泉","f":"五言古诗","c":["毒龙所止处，水必浑以腥。","兹泉名白龙，水味何清泠。","澄澄鉴毛发，龙曷遁其形。","阴风时怒号，微吟或可听。","川脉发神光，尤物藉其灵。","白龙化为人，鱼服昔焉经。","何必家于水，后人赘以亭。","我来酌斯泉，醉荷不肯醒。","龙乎亦来不，视之如蝘蜓。"]},{"t":"东坡井","f":"五言古诗","c":["颜城数眼井，井井号东坡。","坡仙若不来，其如此水何。","点尝任去取，水味亦靡它。","舌本失其据，耳与口传讹。","白龙与金粟，兼此无乃多。","图经争不定，碑碣空嵯峨。","品藻生风云，弃置则岩阿。","世人梦不醒，徒为双井魔。"]},{"t":"天宁寺","f":"五言古诗","c":["驰道夹椰阴，暝风吹冽冽。","笋舆踏山影，岚重炬难彻。","初日发海光，白处天疑缺。","俄而诸天霁，群象灿可阅。","明明蛟蜃宫，窣堵鳌背孑。","何物镇山门，如来石所锲。","其石滑如脂，其音清以越。","僧以梃来试，禁之毋乃亵。","云自海藏来，洵与震旦别。","法鼓冶以金，镂文细似缬。","冥思浩劫因，扪摸證石碣。","天水共荒唐，难凭老衲说。","我欲纪异闻，咄哉缄其舌。"]},{"t":"题五里亭禅室","f":"五言古诗","c":["劳劳五里亭，禅关亦在兹。","往来冠盖人，驻马暂经时。","轮蹄纷杂遝，供张错路岐。","尘劳遍大地，佛力津梁疲。","我来登法堂，拈花一问之。","苦海几由旬，尘海亦如斯。","眷兹尘界人，彼岸到何期。"]},{"t":"重过黄氏园访〔李〕影九","f":"五言古诗","c":["翳然一林水，蒲稗相因依。","昔我届春游，涉夏转芳菲。","宿雨潴众浍，池痕漫以肥。","萝竹争空阶，灌莽司垣扉。","人影交湿光，深碧在巾衣。","薄日照难彻，绀绿蓊成围。","境寂虫逾武，人閒鸟息机。","蛙响竞中夜，到午力稍微。","一为摊书坐，散虑憺忘归。"]},{"t":"次答友人池馆閒步见怀","f":"五言古诗","c":["秋光荡人怀，霁景媚澄池。","况乃琴书暇，水木憺多思。","因病谢朋侣，行行鸥鹭随。","阒寂见成感，羁閒多生悲。","忽听玄蝉噪，怅焉恋别离。","岂无携手好，要非心所私。","同为异乡人，聚散天之涯。","大海窅以深，萍槎安可期。","恻恻缄中情，毋令鱼鸟知。"]},{"t":"闻蝉","f":"五言古诗","c":["露虫动秋感，切切号枯林。","一声声断续，沁入离人心。","寥韵发空谷，馀响曳墙阴。","掩抑知情重，纡回觉思沈。","此时方静嘿，况复闻城砧。"]},{"t":"别王尧韭","f":"五言古诗","c":["墙东王居士，傲骨凌千秋。","手持七寸管，旁无作者流。","胸既破万卷，目亦横九州。","岂学醯鸡儒，但为妻子谋。","淡香然古炉，白茗点瓷瓯。","有时对韵士，枯桐与纹楸。","品卉商瓶史，移泉问水邮。","空馆听蛙鸣，高树聆禽啾。","片语證无生，莲花上上头。","离合海中蘋，怆焉岁已周。","天水憺空迥，浩思方悠悠。"]},{"t":"题熙东侄园馆","f":"五言古诗","c":["市居厌烦嚣，山栖讶岑寂。","惟此半亩园，可以恣吾适。","远可揽溪山，近不越篱壁。","周垣缀牡蛎，甃坛斲方石。","庭庑不必宽，胡床只数尺。","中间列图书，兼以置琴奕。","盆鱼畜数头，时花随意植。","充圈有鸡豚，良酝储庖■。","佳朋过即留，客散掩关息。","从容理编帙，兴至弄笔墨。","何必问舍田，谋道即谋食。","我有一小园，亦有耽书癖。","其奈尊常空，宾至无颜色。","尔今食稍饶，可以延嘉客。","拥书对良朋，此乐有何极。"]},{"t":"树萱有感","f":"五言古诗","c":["真忧不可忘，忧是心头草。","浇以泪淋漓，培以思懊恼。","向风顿发生，离离不堪扫。","大地为愁城，播种遍穹昊。","其根不可芟，其叶不可槁。","谁云万斛忧，疗以一茎草。","家家人树萱，食萱如食稻。","忘忧是阿谁，殷忧人易老。"]},{"t":"和苏新男见赠草堂初成","f":"五言古诗","c":["鹿性走丛薄，蝉吟翳高枝。","结茅依廨宇，丹垩不复施。","花间围竹格，引蔓疏离离。","短檐碍巾帻，人室始一披。","海风荡雨尘，椰影莽参差。","就湿浚渠浍，向隆叠城基。","北窗午梦甜，直可傲轩羲。","开门逢大苏，把臂一游之。","琅琅矢嘉咏，四座照摩尼。","瀹茗款清言，剪韭荐山卮。","戏为蛮语吟，娵媀跃清池。"]},{"t":"木下庙","f":"五言古诗","c":["觌面相欺瞒，山灵藏眉目。","石骨标遒隽，地偏景亦缩。","詹桥铿怅策，过尽巉山麓。","水石争喧豗，能豁耳根俗。","沿冈踏陂衍，步步殢心足。","万石忽奔骞，共赊天一曲。","溪回石亦驻，似攫还似伏。","腻叶交湿光，脩藤缘老木。","渐远城市嚣，亦敌炎州燠。","神据胜而灵，阴风助肃肃。","伏腊走儿女，登荐刑鸡鹜。","草木贬幽奇，溪山亦折福。","踞石我沈冥，披扪任童仆。","阳曦薄崦轨，注光射山腹。","迟景不可延，订我重来躅。"]},{"t":"再渡海纪梦和坡公行琼儋间肩舆坐睡梦中得句","f":"五言古诗","c":["长天带远水，孤岛浮于中。","风利扬半帆，疾如箭离弓。","环观积气周，天水但一空。","静然耳目内，难以物理穷。","惯来狎海若，尚欲叩天翁。","噫气起萍末，谁为辨雌雄。","潮何以应蚌，草何以知风。","惝恍梦魂间，耳畔闻铎钟。","百幻肆以陈，迭奏殊未终。","我时骖白凤，夹驾两青童。","照路一摩尼，擎之以秃龙。","万丈白毫光，照耀紫金容。","稽首奏玉墀，绘天语难工。","丹书许我求，三度访龙宫。"]},{"t":"可庐经燬另搆小苑因和东坡新居","f":"五言古诗","c":["祝融妒我庐，幸宥垂杨影。","改筑面南离，旧搆成新境。","盘卉经烧残，劫灰同一屏。","月来竟入之，转觉虚堂永。","槿篱芟枯蘖，得雨仍抽颖。","客来始一叹，沧桑亦俄顷。"]},{"t":"和食槟榔","f":"五言古诗","c":["千柱撑云幪，著土没其础。","炎洲未是炎，万箑扇残暑。","丹粒结翠房，似为饥禽禦。","仙掌苞凤卵，葡萄垂马乳。","鲜食珍土人，致远藉蒸煮。","千艘与万轴，输挽无停阻。","咽津一快喉，暂嚼滓还吐。","味回橄榄甘，亦带蕨笋苦。","发赪助颜酡，点绛增唇妩。","园既擅素封，利亦殖富贾。","推垢兼破块，能以导为补。","常飧等蔬稻，药用些些许。","黎水涎带醶，腹瘕似抱鼓。","恶风旋鬼轮，时为头目侮。","毒雾霁不开，炎沙烁日午。","天施辟瘴丹，厥效为君数。","最哉浮海人，眠餐力当努。","地产山海珍，食谱难尽举。","惟有药材悭，以此助穷旅。","一钱买盈握，昏暮求必与。","南中藉享奢，难为北客语。"]},{"t":"和贫家静〔净〕扫地","f":"五言古诗","c":["琼人不货帚，教童缚数头。","贫家无长物，阶净竹脩脩。","巧月到庭除，偏能为我留。","窗明地亦洁，此乐安可媮。","净秽关至性，如味别薰莸。","士品亦如斯，入室人焉廋。"]},{"t":"和夜烧松明火","f":"五言古诗","c":["穷冬憺阴晦，海气交冱寒。","我无绛蜡炬，斗帐围红鸾。","樵人割松脂，焚著青烟团。","琼人轻沈檀，嗅此如茝兰。","覆瓦炷其烟，收煤有一槃。","我闻龙香剂，乃出松火残。","恨无和胶法，弃置殊可叹。","良材贵有遇，太息坐更阑。"]},{"t":"和籴米","f":"五言古诗","c":["饥鼠徙邻家，山僮赴米市。","虽傍海人居，常餐少鲜味。","顿顿摘青葵，八口仰空地。","束带不任锄，蔬食犹怀愧。","遥望南桥坡，青苗早抽穟。","纵乏豚蹄祝，颇谙老农意。"]},{"t":"咏止酒","f":"五言古诗","c":["欢伯招我游，愁城域我止。","悲欢各有缘，不落杯匕里。","两渡琼海洋，孑身抛妻子。","中馈乏酒储，曷为嘉宾喜。","况乃逢俗宾，投觞辄欲起。","强作解事言，浊醪有妙理。","知音不在弦，得趣酒可已。","今我欲还山，此瓢永弃矣。","辟如鼠饮河，岂必窥其涘。","怀哉阮步兵，瓣香聊以祀。"]},{"t":"和浴罢","f":"五言古诗","c":["帽束滋头垢，眼昏忌脑沭。","惟此土木躯，间日须一浴。","一洗阴埃消，阳明始来复。","兰汤候温煦，浇背徐濯腹。","伸臂按其胯，摩顶遂至足。","颓然四大蠲，跏趺瞑双目。","放体效戏禽，齿门戛哀玉。","吐纳以绵绵，灵泉任灌沃。","百孔顿嘘蒸，似烟喷钻竹。","暂入无怀乡，希夷路正熟。","小劳身乃泰，琴书间诵读。","涉趣防其流，回光湛内瞩。","逝止随流坎，何须詹尹卜。","庄叟赋逍遥，至人守缘督。"]},{"t":"和旦起理发","f":"五言古诗","c":["金鸡海上鸣，白气发龙宫。","晨起搔短鬓，如霜摧秃松。","茸茸不受栉，堕絮飏游风。","结束神观整，颒嗽耳目通。","冠簪甫云毕，朝谒何太匆。","头岑体复惫，污渍衣重重。","倦骥思枥槽，长鸣擞鬣骢。","闻头责子羽，于我将无同。","富贵不可求，神仙不可逢。","讵无置身策，东郭灌园公。"]},{"t":"和午窗坐睡","f":"五言古诗","c":["家有癯仙椅，坐卧便首肘。","海舶致之来，今复为吾有。","久失还故乡，坐忘不知久。","偃息妥营魂，安閒舒足手。","侍僮疑入定，客到讶中酒。","我生同草木，不材以为寿。","华巅难返童，神理当不朽。","此中别有缘，睡觉两不受。","无想亦无因，非净亦非垢。","纵然化蝶去，不梦漆园叟。"]},{"t":"和夜卧濯足","f":"五言古诗","c":["海南无冬春，单衣裹袷裯。","生事亦云足，官贫了不忧。","萤火熠幽轩，黑林叫夜鹠。","洗足未登床，竹屋瓦灯留。","劲风捲檐瓦，墙隙鸣飕飕。","分火烹新泉，聊以芳茗投。","此生愿无馀，何苦利名韝。","飘泊海中槎，身世一沤浮。","地既产狂泉，谁以独醒瘳。","茫茫大块圈，今古跳猕猴。"]},{"t":"瞑投海口庵和入寺","f":"五言古诗","c":["野寺半无门，老佛忘其尊。","院残僧不守，流散寄他村。","我以寺为家，见佛即慰存。","海天流日夜，送月复迎暾。","欲持锡杖尖，挑破黄金盆。","阶树定猿守，风檐怖鸽莽。","街鼓严净夜，人语寂黄昏。","剔起佛前灯，残经聊自温。"]},{"t":"余畜一黄犬行时留以守衙比再渡琼此犬衔衣跳舞感而赋诗和坡公乌喙","f":"五言古诗","c":["邻舍产一獒，乞养权为主。","我行三叮咛，慎勿膏砧俎。","遂与衙役依，晨昏守空户。","及我再来兹，衔衣相向舞。","似欢还似悲，垂首泪如雨。","此畜颇异人，食后浴于浦。","入水性如獭，搏狸气似虎。","别我一岁周，不谓再见汝。","尽识家人貌，兼复解其语。","何物无因缘，三生叩佛祖。"]},{"t":"和连雨独饮","f":"五言古诗","c":["旷怀览千古，事有然不然。","我心古人心，相视在其间。","云胡一体内，强分儒佛仙。","此屈不可伸，连语叫苍天。","混沌无首尾，何物是天先。","茫茫针孔内，今古相往还。","举杯浮积雨，但愿雨连年。","沈冥杯斝中，万事可醉言。"]},{"t":"夜雨衣衿尽湿抱书三徙因诵坡公一夕成三迁之句即用其句和其韵","f":"五言古诗","c":["夜气凉复佳，夕寝方陶然。","我居海之南，老屋阅岁年。","习久安其陋，讵云选地偏。","独恨微官系，未便营舍田。","常思枝鹿游，此地可卜廛。","万感攒中夜，雷声复搅眠。","破屋雨重重，一夕成三迁。","侍儿抱残书，堆拥向案前。","冷灶已沈火，敲石又无烟。","因叹在官贫，或不愧昔贤。"]},{"t":"生朝自寿示诸生和子由生日","f":"五言古诗","c":["蠕动皆含灵，脩短亦不一。","偶然脩短之，岂必天所骘。","俗士强安排，持券邀所必。","至人冥于虚，君子践其实。","体堕形匪拘，神藏聪可黜。","潜然返厥初，生理亦云毕。","我年过半百，所遇半凶吉。","流坎乘化运，憺漠守神室。","未免与俗缘，所欠焚研笔。","我自观其生，君勿庆余日。"]},{"t":"怀归和送芝道人","f":"五言古诗","c":["有士不可名，强字曰长度。","戴发依空门，绾绶仍儒步。","一苇泛重溟，四年海上住。","琼南非我乡，海北将问渡。","水云道者装，瓢衲僧行具。","问我归时因，即是来时路。"]},{"t":"茅斋夜酌示诸生和迁居之夕闻邻舍儿读书","f":"五言古诗","c":["蛙宫陈乐部，阶树应时禽。","虽无山水缘，耳畔足清音。","斋中何所有，木榻与布衾。","门庭多韵士，弦诵间豪吟。","灵气归海潮，自北以至南。","海霞朝夕变，涛声自古今。","人生如风萍，一别即商参。","念此恻中肠，惟赖酒杯深。","坐客扬清歌，歌罢还复斟。","颓然遂至醉，无言对韵琴。"]},{"t":"和饮酒 其一","f":"五言古诗","c":["我不能饮酒，酒亦厌薄之。","试问清醒徒，何如浊醉时。","清浊两不受，醉醒宁在兹。","未饮颜先酡，客亦不我疑。","空杯谎枯肠，权为酷客持。"]},{"t":"和饮酒 其二","f":"五言律诗","c":["酒肠比沧海，醉骨像邱山。","山水仁知徒，醉醒何足言。","中山千日醉，一饮当三年。","借问蜉蝣世，深杯能几传。"]},{"t":"和饮酒 其三","f":"五言古诗","c":["醉翁不在酒，而得酒中情。","达士逃于酒，而争酒中名。","我亦两置之，陶陶乐其生。","醉吟泣风雨，落笔鬼神惊。","古来才仙者，多以酒而成。"]},{"t":"和饮酒 其四","f":"五言古诗","c":["鸠鴳附鹏背，我姑从汝飞。","风高不得下，魄丧神亦悲。","茑萝与松语，毕世为君依。","长松摧为薪，问茑将安归。","欢轮有时竭，爱席有时衰。","当其欢爱时，尊酒莫相违。"]},{"t":"和饮酒 其五","f":"五言古诗","c":["梦中闻檐溜，恍惚江浪喧。","醉里下阶除，有似乘舟偏。","好语不相投，觌面隔邱山。","劝君但饮酒，世上少往还。","醒来莫输心，醉后莫献言。"]},{"t":"和饮酒 其六","f":"五言律诗","c":["五十觉前非，过此仍非是。","身如衣绣刍，巫觋任赞毁。","我固自为我，尔亦自为尔。","从教麻与枲，不羡缟与绮。"]},{"t":"和饮酒 其七","f":"五言古诗","c":["少年从我饮，照座亦英英。","与语人间世，一往有快情。","何必胜公荣，当杯便可倾。","枝头有黄鸟，嘤嘤求匹鸣。","繄我独无徒，悠然念友生。"]},{"t":"和饮酒 其八","f":"五言古诗","c":["海滨逢一叟，翛翛云鹤姿。","终日自行歌，手执青松枝。","世人莫知识，但讶行径奇。","笑指海东云，子能从我为。","举头欲问之，摇手去莫羁。"]},{"t":"和饮酒 其九","f":"五言古诗","c":["谷以春而获，花逢腊亦开。","海上真仙都，其俗号无怀。","我欲受一廛，乘桴志靡乖。","勺水亦可饮，支林亦可栖。","鸿雁遵沙渚，宁顾指爪泥。","自来生分薄，良愿不我谐。","今是昨诚非，一悟了不迷。","茫茫汎苦海，是岸我即回。"]},{"t":"和饮酒 其十","f":"五言古诗","c":["遵驾古城麓，路转东北隅。","前冈车骑盛，蹲沓隘道途。","是身如车轮，终日受人驱。","从来名利场，所得孰留馀。","饮酒读离骚，百城南面居。"]},{"t":"和饮酒 其十一","f":"五言古诗","c":["造化本无私，朝廷今有道。","禽鸣桑柘间，鸡豚醉父老。","炎洲气如煦，经冬苗不槁。","三登嘉谷熟，四季春华好。","海内未休兵，圣人方却宝。","水国有波臣，拟贺平奴表。"]},{"t":"和饮酒 其十二","f":"五言古诗","c":["乘箄入鼠穴，大梦颠倒时。","人间醉所言，俱是醒中辞。","谓梦而非觉，觉亦在于兹。","朝闻夕可死，尼父岂吾欺。","形神将接间，请君一问之。"]},{"t":"和饮酒 其十三","f":"五言古诗","c":["天地一生灭，何处是真境。","偶然幻作人，幻醉仍幻醒。","呼我为马牛，我亦从人领。","但得处于囊，不必露其颖。","玄豹隐雾中，奚羡文之炳。"]},{"t":"和饮酒 其十四","f":"五言古诗","c":["伊人各有品，贵自成其至。","莫以我之醒，而笑彼之醉。","醉醒一瞬间，循还以其次。","辟如巢许清，不碍夔龙贵。","云壑别有缘，清朝亦有味。"]},{"t":"和饮酒 其十五","f":"五言古诗","c":["瀛海几由旬，中区浮为宅。","我亦云水居，一官徒寄迹。","山经岛有三，福地洞踰百。","蜃嘘幻楼红，鳌涌雪山白。","不作海上游，醯鸡亦可惜。"]},{"t":"和饮酒 其十六","f":"五言古诗","c":["家世学为儒，传家只一经。","砚田粗有获，不必计其成。","先人叨俎豆，子孙兑践更。","少小习文翰，微名达天庭。","清时靡所竖，何用经术鸣。","举杯浮苍天，孰测余中情。"]},{"t":"和饮酒 其十七","f":"五言律诗","c":["屋瓦飞欲尽，沙石走狂风。","海水如沸羹，大地簸其中。","但愁坤轴拆，遂与河伯通。","半酣逐奔潮，手挽二石弓。"]},{"t":"和饮酒 其十八","f":"五言古诗","c":["倚杖听鸣泉，欣然若有得。","十年尘土梦，一洗耳根惑。","洞然镜古初，兹理无通塞。","何事繁音聒，嘈嘈满蛙蝈。","对酒弄无弦，冥心返于嘿。"]},{"t":"和饮酒 其十九","f":"五言古诗","c":["陶公无宦情，饥乃驱之仕。","行藏不问天，卷舒惟任己。","荣膴非所钦，薄禄非所耻。","束带见督邮，不必问乡里。","自我浮于海，悠悠历星纪。","卑疏虽易容，迂薄亦可止。","白发已盈冠，青尊尚足恃。"]},{"t":"和饮酒 其二十","f":"五言古诗","c":["与我周旋者，何物最为真。","惟此坏尊内，陶然太古醇。","气味久不渝，一挹一清新。","悠悠交中人，肝胆为越秦。","流光汎酒海，大地扬曲尘。","古人百不恋，惟于此物勤。","我量不能胜，要令风谊亲。","天上有酒星，乘槎一问津。","地下有酒泉，可以漉我巾。","聊和饮中诗，窃比于酒人。"]},{"t":"读书柳子厚牛赋有感效坡公体","f":"五言古诗","c":["琼土恬杀牛，食之以当粟。","吉凶昏丧事，杀牛媚亲族。","家大视牛多，宴颁皆取足。","上以荐祖祢，下以饫僮仆。","牛自海渡来，头头皆就戮。","有牛不以耕，但用恣口腹。","又有生黎种，嗜牛尤太酷。","杀牛不用刀，毙之仅一镞。","剥皮以当锅，燔烧取半熟。","入口尚闻腥，鸾刀带血漉。","毛骨委山野，肠胄弃深谷。","厥地产沈香，还以生牛鬻。","以此腥膻禽，易此芳馨木。","灾木与刑禽，其理等笺僇。","牛鸣泻厥悲，香泪亦当哭。","胡为东坡老，忍木而仁畜。","热喝醒沈梦，痛棒创狂俗。","供佛以沈香，即是烧牛肉。","余性酷烧香，不忍牛觳觫。","二者讼于中，曷以平兹狱。","空香入斧斤，有斫而非触。","我即罢购香，牛命不可赎。","不若勤烧香，为牛姿冥福。"]},{"t":"怀息庐和坡翁息轩","f":"五言古诗","c":["吾家有息庐，息身未有日。","古人悼无闻，四十而五十。","百年可例推，想亦无间隙。","莫若早回头，可以息则息。","果腹惟三餐，容身祇一席。","古昔有良训，归当书之壁。"]},{"t":"食南椰面和坡翁意苡","f":"五言古诗","c":["南中少霜霰，麦性不淳良。","惟此南椰面，饱食胄不伤。","我亦核其性，山经早已亡。","但闻产黎落，其树径丈长。","胡天有嘉植，偏厚于遐荒。","始疑椰实粉，或曰捣桄榔。","登筵贶佳客，讵云俭岁粮。","搜和净且滑，作饵亦馨香。","乃知膻食者，徒以饫肥肠。","温冰与软玉，翠盘别有光。"]},{"t":"羽甫家兄招游石涧同区茂对区君玉犹子仲昭流连迨暮归途狼藉赋此纪兴","f":"五言古诗","c":["山水本相须，往往不相假。","孰若兹山奇，石泉两绝也。","石自泉中出，泉自石中泻。","泉味既甘寒，石貌亦萧野。","点缀俱玲珑，布置极幽雅。","平者如匡床，窔者如广厦。","艳如青莲蕊，古如紫芝把。","如蟾复如蛛，如狮复如马。","此是石恢奇，请说泉潇洒。","或飘如曳帛，或纷如掷瓦。","或沸如茶铛，或镕如金冶。","如鱼张口吸，如沫齿缝下。","有响击空山，无声走石罅。","泉石既相遇，相聒不肯舍。","流来经委折，转入更虚閜。","连峰列如屏，其下荫松槚。","有草碧如染，有花鲜如楮。","是石皆可憩，是林皆可藉。","逢岩可安灶，遇坎可泛斝。","坞可名藏春，湾可题销夏。","水从岩际度，人向石上跨。","悬厓时戟面，淙流或没踝。","磴苔置屐滑，箭风当面打。","恋赏成久淹，入暝转惊讶。","昏黑度前冈，迷路穿樵舍。","鬼灯光如漆，的的照篱笆。","咒力厌怖魂，齐声诵般若。","溪回路忽断，危桥独木槎。","游人颠坠厓，坭泞交喧咤。","衣帻不及顾，时时伤髀胯。","溪山到处有，好事人恒寡。","堕崄与啼厓，胜事古来诧。","我欲纪兹游，钝笔不堪写。","一死博河豚，戏语同游者。"]},{"t":"羽甫兄采松花和茯苓作饼饵见贻诗以酬答","f":"五言古诗","c":["并刀剪龙髯，长镵斲木瘿。","蝶粉糁玄霜，撚作松苓饼。","石臼碾轻尘，冰纨筛枯梗。","和以蜜脾脂，清沁灌肺冷。","微黄似鸦雏，丹的点妆靓。","又如累滇棋，数十不盈皿。","萧斋苦宿霜，午睡方才醒。","竹扉犹未启，墙外闻人警。","贻来金盒儿，颗颗周完净。","初观委难辨，小咀亦深省。","问渠来何方，松花撷山顶。","间渠和何味，茯苓收药箵。","道人戴竹冠，羽扇临丹鼎。","少妇纤手调，玉童汲阶井。","念彼百艰成，供我一馋领。","顿嚼三十九，似砾投深井。","石火试陶铛，沃以松萝茗。","轻松乍迸牙，香韵才灌顶。","冷然两腋风，谡谡吹松影。","枵腹藉一充，饕涎欲再逞。","呼童走药肆，为买茯苓莛。","百钱刚一斤，铢两犹未整。","二月松树花，开遍閒冈岭。","长竿打一遭，粉腻沾衣领。","谁云解疗饥，如虎得蚱蜢。","闻君山厨内，采摘盈筐秉。","愿作拷栳团，一餍淘河颈。"]},{"t":"岭上逢何文起","f":"五言古诗","c":["相逢梅岭上，问我何时归。","休问我来归，看我去时衣。","我衣去时新，归来化淄尘。","岂但化淄尘，点点渍泪痕。","男儿志四方，非我恋乡里。","我病日缠绵，我归良有以。","问我病中情，我病难取譬。","一日复一日，但觉形神瘁。","君语曰无损，强饭善自将。","去路与来程，一一为我详。","自从十一月，辛苦离家乡。","是月廿九日，办装发五羊。","陆路殊劳顿，雨雪又难当。","沾病抵濛里，信宿驿馆旁。","馆舍荒凉甚，居人逐虎狼。","病间礼南华，催程过黄塘。","是时有一仆，苦病泪汪汪。","初十度梅岭，就买南安船。","舟次善将息，稍觉体气痊。","立春到赣州，吉安过小年。","一程到市汊，前病又复然。","阻风彭蠡口，归心日日煎。","却与舍弟别，涕泗交潺湲。","元旦又五日，买舟始言旋。","屡屡写家书，无人寄一字。","时时望家乡，无由缩地至。","今朝逢故人，恍如隔世事。","我有家中人，大小平安否。","君言俱平安，我恐顺应口。","我有中怀绪，仓卒难记忆。","就中所记者，略语难周悉。","君行年初四，我返年初五。","两行皆逆水，舟行那得驶。","来时乡中事，约略为我陈。","乡景想如昨，乡情果日新。","浓淡园中景，聚散社中人。","那处过从数，那个来往亲。","扶留青叶翠，新鲜槟榔核。","持出共对嚼，珍重故乡物。","家僮来问讯，软语相宽慰。","还顾波涛侣，唧唧复娓娓。","大小各情亲，人情亦复尔。","离合见悲欢，所贵同臭味。","君今荣趋府，我独倦垂翅。","浮沈各异路，浊水清尘比。","前村笳鼓闹，人来迓车骑。","旌旄蔽崇冈，蹲蹲走官吏。","登车君于迈，策蹇我回避。"]},{"t":"题松柏同春卷","f":"古风","c":["陟彼高冈，松柏楚楚。","于日于朝，以风以雨。","日月之行，荡乎其中。","山川喷薄，不出其所。","根盘太古，苍鬣虬枝。","洗髓泬漻，濯魄玄夷。","白云在天，红日在地。","精灵出没，与之游戏。","二仪一象，四气唯春。","松耶柏耶，后众卉存。"]},{"t":"和泂酌亭诗","f":"古风","c":["往来井井，于彼于兹。","众口如瓶，曷辨渑淄。","一土攸生，厥味莫齐。","舌司鉴衡，匪曰泉私。","清圣浊贤，君子是仪。","既好其辨，爰系之诗。"]},{"t":"和观棋","f":"古风","c":["登岸造极，筑基累址。","义取其争，和不为美。","设险似兵，坐隐若士。","雌雄未分，黑白唯二。","投鞭断流，探穴取子。","袖手徒观，当局忘味。","惊矢落雕，游丝系鲤。","制胜以谋，纵擒在指。","败还自葺，胜勿浪喜。","艺之云乎，道如斯耳。"]},{"t":"久旱悯农因和停云 其一","f":"古风","c":["停云薄空，有风无雨。","欲叩帝阍，祝融伊阻。","三春云迈，良辰空抚。","孰捣龙宫，操豚是伫。"]},{"t":"久旱悯农因和停云 其二","f":"古风","c":["西郊作云，厥气冥濛。","有赫震雷，倒岳掀江。","掩耳避之，闭户塞窗。","天意叵测，莫之适从。"]},{"t":"久旱悯农因和停云 其三","f":"古风","c":["眷彼良苗，悴不再荣。","哀哀孑遗，嘿轸余情。","祠川祷岳，岂惮宵征。","昊天不恤，不如靡生。"]},{"t":"久旱悯农因和停云 其四","f":"古风","c":["液不荣根，叶辞其柯。","民之不禄，孰沴天和。","及此降霖，获少丧多。","其复不尔，嗟嗟民何。"]},{"t":"和劝农 其一","f":"古风","c":["天沃尔土，不敕尔民。","一耕三食，劳逸谁真。","三时弗若，兵馑相因。","劝尔务农，自利利人。"]},{"t":"和劝农 其二","f":"古风","c":["市利莫争，艺我黍稷。","金贱谷贵，贷不可殖。","驱此劳民，以稼以穑。","地产明珠，饥不可食。"]},{"t":"和劝农 其三","f":"古风","c":["天祻尔琼，珍饶川陆。","地发秘奇，民破淳穆。","惰农弗耕，奸贾利逐。","环琼百室，舂粮不宿。"]},{"t":"和劝农 其四","f":"古风","c":["积玉堆金，家弗可久。","上智明农，相戒其偶。","坊市勿嬉，并力南亩。","农亦有閒，不为游手。"]},{"t":"和劝农 其五","f":"古风","c":["谋食有方，务本不匮。","纵不逢年，勤则有冀。","物岂余悭，唯力弗至。","耕凿嬉游，帝力何愧。"]},{"t":"和劝农 其六","f":"古风","c":["垦我疆场，拓我边鄙。","无地不毛，唯亩是履。","既登嘉谷，盈箱溢轨。","伏腊鸡豚，酒浓肴美。"]},{"t":"打鱼歌 其一","f":"七言律诗","c":["清江八月潮头涨，渔父拦江呼举网。","江头少妇趁潮归，觅得鲤鱼置兰桨。","提刀欲剖且踟蹰，中有情人锦字书。","绛鳞赪尾蠕蠕动，投向江波信所如。"]},{"t":"打鱼歌 其二","f":"七言律诗","c":["渔人使船如使犊，出没波心似平陆。","船头抛网如抛梭，往来欸乃唱渔歌。","江潭黝杳不见底，网入如胶提不起。","投竿掷网撇波去，恍见仙人骑赤鲤。"]},{"t":"打鱼歌 其三","f":"古风","c":["小鱼掇荇带，翻与大鱼会。","大鱼啖小鱼，跳入罟中居。","渔人得鱼换酒沽，一饱旋复弃其馀。","白浪如山罟如簇，竭泽穷源探水族。","樯倾柁折须臾事，渔子亦饱江鱼腹。","赢输物理皆自然，弱肉谁司造化权。"]},{"t":"青镜引","f":"古风","c":["妾有七宝青铜之古镜，重之不减青琅玕。","香罗绣帕鸳鸯结，碧玉妆台龙凤蟠。","流光团团似明月，清辉烱烱鉴毛发。","规影微含翠羽斑，钮环半蚀虫文绝。","芙蓉帐暖睡迟迟，夫婿临妆对画眉。","兰房昼永垂珠幕，宝靥香凝透玉肌。","朱颜冉冉岂相待，青镜迢迢看渐改。","憔悴芳心不自持，凄迷春梦知谁在。","孤鸾惊影日光沈，镜能照貌不照心。","君心安得长如镜，妾貌难于镜里寻。","沈吟抚镜三叹息，香帕玉台长拂拭。","愿持明镜赠夫君，留与后人照颜色。"]},{"t":"叹落花","f":"古风","c":["花开花更落，花落花更开。","便是春风多翻覆，那得君心无去来。","红颜楼上探春女，看花摘尽春花蕊。","管取新妆斗丽华，宁论憔悴委泥沙。","南邻思妇当阶坐，手撚残花泪交堕。"]},{"t":"送春吟同社中诸子赋","f":"古风","c":["惜春春不留，送春春自愁。","春愁荏苒春风起，春草春花总相似。","残云澹月吐春华，曳絮游丝乱春渚。","春渚迢迢连春郊，春禽队队归春巢。","此时思妇上春楼，此时游子折春梢。","春梢何袅袅，春楼何杳杳。","垂杨蔽日结春丛，飞骑如云簇春晓。","万户千门春鸟啼，九衢八道春气迷。","有钱便可买春酒，无钱何须踏春堤。","春堤一带浮春水，水逝花飘春不语。","朝泻红妆春黛残，暮浣绣裙春溅驶。","春流九派长，春花百和香。","春眠春梦短，春望春思忙。","春眠春望春萧索，春草春花春冷落。","春游公子跃归鞭，春尽佳人深闭阁。","东邻少妇春思阑，行春拾得双玉环。","持环往问春闺女，春色如环可待汝。"]},{"t":"官仓行","f":"七言古诗","c":["官仓近在东城下，颓垣断壁连四野。","芃芃白草没行人，屋鼠清晨窜古瓦。","去年乡落多流民，富者给糜啖四邻。","邻人得糜仰大屋，官仓都无半粒粟。","富儿入粟并入官，稛载车量几万斛。","此粟应从何处支，此仓之发几经时。","县官何繇徵子粒，仓吏或窃饱妻儿。","旦暮周身元草草，当年官吏且不保。"]},{"t":"徐济伯画白鹰歌","f":"古风","c":["徐郎写白鹰，肃肃毛欲动。","铁爪盘挐大石间，其下冲波万丈涌。","素波霓裳一色明，照见愁眉双目睛。","长天远浦云飞断，老树一枝纵复横。","徐郎真好手，胸中别作禽兽囿。","摩挲落笔分翅翎，烂熳临池开花柳。","曾扫上林春曙图，骨相形神色色殊。","信手招云雾，决眦入毫铢。","扶桑半映万林西，孤凤初鸣百鸟啼。","菰蒲菡萏汎汎出，荆棘橐梨隐隐栖。","此鹰一出众禽避，半空袅袅流云气。","垂头一叫众鸟号，奔涛破山风动地。","顿觉四壁间，滴沥水花起。","阳侯入户鲛人笑，松窗漂入风湍里。","水声嘈嘈下碧滩，回看却在几席间。","莫是天河决，将无地轴翻。","吾闻鹰是搏击鸟，此鹰此画得其妙。","当日临风刷羽翰，一举万里绝云峤。","即今孤崖栖，侧目江天渺。","吁嗟夫威鸟文鹓世所稀，鸱鸮乱啅稻梁肥。","深山大泽吾能到，尽斩蓬麻任尔飞。"]},{"t":"送方上舍还江右","f":"古风","c":["方郎手提三尺剑，云是延津跃出双龙子。","自言此物信有神，水斩蛟龙陆豹兕。","张华去后少人知，匣里寒光漾秋水。","君曾携之燕市头，醉来拂拭声啾啾。","秋风走猎上林苑，月明高宴娼家楼。","秋风明月自年年，半生行乐马蹄烟。","縢囊时出济人药，藜杖空馀沽酒钱。","我政逢君君欲别，对酒无欢共呜咽。","驿亭春尽柳花斑，莺语鹃啼草树间。","兰桡晓趁三江水，马首晴开五岭山。","兴来倘上滕王阁，好寄音书双鲤还。"]},{"t":"送阮生游琼海","f":"古风","c":["海树郁青青，人烟白浩浩，乃是琼厓中州之别岛。","东来巨浸碧濛濛，欱沓似与元气通。","水底神鱼或作雨，溪边种草能知风。","怜君万里穷名胜，狂来气与波涛猛。","鼓柁遥临黎母江，垂纶欲钓鱼爷井。","朝来海气蒸成霞，扶桑高傍岭云赊。","河源杳杳知何许，转忆张骞八月槎。"]},{"t":"勾漏歌赠高山人","f":"古风","c":["我闻勾漏之峰亘万里，丹梯碧落浮云气。","山人家住彩云西，荷锸被云斲石髓。","千壑万壑云冥冥，云里依稀鸡犬声。","曾是葛洪飞度处，至今丹灶留翠屏。","翠屏黝窱连石屋，山人夜傍绳床宿。","云磴崔嵬斸玉芝，瑶函缥缈开金箓。","山人出入云气随，山人放歌铁篴吹。","鸾璈凤管世不识，别有霓裳羽衣词。","醉来拓笔扫丹嶂，倏忽烟霞开万状。","解衣遥临磅礴前，传神偏在阿堵上。","自从浪迹遍江山，转觉壶中日月閒。","漫说鸱夷浮海外，那知方朔在人间。","我是玉皇香案吏，一谪泥涂今若此。","自分宜置丘壑中，烦君貌我丹青里。"]},{"t":"醉中题壁","f":"古风","c":["读书破万卷，拈笔无一字。","结客近三千，缓急不可恃。","闭门谢客客从呼，焚书烧笔坐虚无。","饱饭三时无一事，坦腹击缶歌乌乌。"]},{"t":"蟠木几歌","f":"七言古诗","c":["千盘万盘互纠纷，嵚巇历落可笑人。","下垂两股蹋至地，宛似踯躅兽蹄奔。","左撞右突相撑拄，其上衍平无削痕。","玩之疑石又疑铁，乃是槎枒老树根。","此树蟠根几许年，此根入土沦黄泉。","未睹繁阴碍白日，定有偃盖摩苍天。","霜餐雨蚀干柯尽，根含神理郁缠绵。","天翻地转如驱毂，深谷为陵陵为谷。","淘沙汨浪孤根出，尘埃谁识真面目。","水石樵人太好事，移我中林之幽屋。","自来野性百不爱，爱此离奇伴幽独。","蓬头坦腹据豪吟，偃仰摩挲看不足。","我闻汉时有古桐，中郎拔之煨烬中。","深山大泽宁无此，斧斤狼藉恣蕴崇。","孤性不随劫火尽，出世或凭神鬼工。","轮囷堪为万乘器，雕锼无人谁先容。","吁嗟无人谁先容，且置中林幽屋中。"]},{"t":"宝剑篇赠陈子明","f":"古风","c":["吁嗟宝剑何神异，莫是鬼国之铁、昆吾之炭铸炼而成此。","请看龟文与缦理，色与青蛇差相似。","灵气莽莽含天晴，混元太如合流形。","阴阳媾交五行会，神工鬼哲殚经营。","尘埃安得此奇物，白虹赤电降其精。","世人见此三尺铁，看与铅刀差无别。","即看铅刀居然别，就中神异不可说。","鸊鹈模糊血花明，一种霜风寒冽冽。","千年玉匣秘不开，龙虎盘拿蛟螭结。","此剑一出无所藏，直之无上横无旁。","左熻右㸌不可当。","划然天地倏低昂，中宵北斗悬清光。","含辉遁景无人见，此物由来镇非常。"]},{"t":"题何文起云卧轩","f":"七言古诗","c":["何人高敞苾云堂，云窗雾栋驾虹梁。","白目看云卧不足，晴天云景悬清光。","团云隐隐如倾盖，飞甍直豁翔云外。","谁向云林种白榆，谁引云槎泛碧海。","朝朝暮暮云重重，云来云去杳无踪。","白云时或化苍狗，黑云时或乘赤龙。","世间万事浮云变，心似閒云任舒卷。","主人雅得看云趣，云卧忘机自仰偃。","问君云卧几经时，看君年少青云姿。","万里云衢争蹀躞，百尺云柯光陆离。","休讶无心云出岫，暂尔云栖依泽薮。","懒云高处枕书眠，云关静掩无人叩。","瑶函金歼盛云缃，丹梯碧戺缭云房。","云岩露滴茶烟冷，云阁霞分藜焰光。","侍童双双傍云宿，时拥云车骖白鹿。","閒持玉锸斲云根，拾得灵芝莳云谷。","鸡犬云中寂不闻，云璈翠管杂缤纷。","过逢半是云仙侣，多暇时删云笈文。","君住云西我云北，披云一见增颜色。","何当理棹水云边，与尔烂醉卧云石。"]},{"t":"长歌寄赠苏汝载","f":"古风","c":["苏郎意气落落谁与俦，自言欲托放浪游。","出门东西南北无一可，而况六合与九州。","嗟哉世途倾仄不自由，何必太行百折之峻阪，与夫瞿塘万叠之洪流。","蓦然平地风涛起，雨覆云翻掌上收。","弓蛇往往分杯影，谈笑之下藏戈矛。","君今欲度而无楫，欲济又无舟。","酌君酒，劝君留。","胡不回车辍棹且夷犹，卧游八索并九丘。","此地中藏十千界，延览大可豁心眸。","一人知己无不足，万事杜门死即休。","得句还应自唱酬，疑处须与古人谋。","沈冥可以周八极，瞬息可以穷千秋。","不然扁舟棹入水竹洞，与尔散发垂钓终日坐溪头。"]},{"t":"尔汝行赠陈子明","f":"古风","c":["陈郎听我击节歌尔汝，古人结交重意气。","呜呼覆雨复翻云，此道于今已扫地。","鸢肩鹤膝蛇为行，百态千容工巧媚。","由来木疆性所宜，随俗纤趋我不为。","相逢一笑惟尔汝，世上悠悠那得知。"]},{"t":"矞云轩为鲁子湛题","f":"七言古诗","c":["黄云城边云气流，千朵万朵压城头。","中有蜃楼驾雾阁，青天幻出昆崙邱。","瑞云一道腾腾起，其色内青外复紫。","青者如蓝半拂烟，紫处流霞初散绮。","非烟非雾碧冥濛，如囷如轮满太空。","宛凝湛露金茎晓，忽洒轻埃玉树笼。","曦阳隐隐纡丹毂，注景含辉并纷郁。","缥缈长依天际浮，氤氲自抱重岩宿。","翠微深锁读书台，暮霭朝霞去复来。","即看清夜燃藜处，定有祥光烛上台。"]},{"t":"秋夜汎舟有约不至","f":"七言古诗","c":["月上未上半衔烟，与客携壶舣舸船。","乍看潮涨流涓涓，倏忽汪洋溢百川。","须臾雾散进婵娟，金波荡漾不成圆。","疏篱茆屋两三椽，野人濯足临溪边。","冷然一棹去如仙，中流击楫更扣舷。","放歌宛转酒杯传，半酣白眼望青天。","美人家住城之偏，重门关钥信杳然。","思而不见空回旋，沈竿没缆水溅溅。","入竹穿萝袅袅牵，主人呼酒尚流连，客子披襟拥露眠。","此中胜事难尽宣，人生行乐须少年。"]},{"t":"代柬答梁叔熹","f":"古风","c":["去年南浦南，珠江北，送子惨澹无颜色。","九江冥冥庐山远，岭树迢遥望不极。","两年不见定何如，赖尔鸿书报消息。","新诗往往堪解颐，无乃偏得江山力。","我有閒吟数百篇，非子之好谁记忆。","自从一病掩柴扉，镇日沈吟卧枕席。","向来促膝谈诗伴，经月何曾通一刺。","偶然思子但寄诗，从今亦懒拈笔墨。"]},{"t":"送梁生游江右","f":"古风","c":["春水碧如油，春光淡宕浮。","离亭数斗酒，彭蠡一扁舟。","彭蠡湖边一雁度，白云冉冉依江树。","到日萱花明寿杯，别来池草添新句。","滕王阁前新水生，徐孺宅前孤月明。","君行觅得西江鲤，好向天南一寄声。"]},{"t":"过采石吊李太白","f":"楚辞体","c":["长江碧潆洄，青山莽明灭。","采石流朱英，灿烂瑶台阙。","忆昔夜郎初度时，宫锦袍鲜湛羽卮。","一杯浊酒一篇诗，忽然骑鲸蹑斗箕。","迩来不知千百载，但见文采照江湄。","冯夷宫，鲛人窟，奔涛逆浪不能平。","万顷烟波沈海月，月沈犹可掇，水逝无还期。","孤云叆叇晴天没，与尔停杯一问之。","阳乌何东升，玉兔何西驰。","纵有长生药，那管鬓边丝。","贤达既寂寞，饮者谁留名。","吸尽长江水，不能实瓶罂。","升沈贵贱何曾定，请看离离水上萍。","险莫险兮马嵬之回湍，难莫难兮蜀道之七盘。","人情倾仄与波澜，谁将一日醉，易此供奉班。","长安市上红尘满，归来沧海弄潺湲。","沈香亭，金銮殿，伊昔豪华不可见。","蛾眉翠黛波盈盈，髣髴太真擎玉砚。","我来访古不胜愁，缥缈长空倚暮楼。","澄波一抹飞云尽，三山点点若浮沤。"]},{"t":"戏赠医士从戎限韵","f":"七言古诗","c":["梁生家世八闽人，少小学书并学剑。","近得龙宫不死方，炼就昆吾跃冶焰。","朝寻山顶采黄精，夜倚旄头看紫电。","匣里龙蛇或一吼，袖中黄白将九转。","逃名岂学吴门隐，排难儗飞聊城箭。","朅来海上请缨去，漫尔壶中施药遍。","芙蓉七宝冲星孤，芝草三花带露碾。","隔垣且窥越人脏，射生须溥单于面。","功成铸剑来种药，海外三山任游衍。"]},{"t":"过孟尝君食客处","f":"古风","c":["齐王昔全盛，公子擅豪华。","三千食客今何在，此地空馀弹铗嗟。","猿啼露白自黄昏，月印苍苔疑履痕。","空山隐隐闻鸡犬，犹是当年侠客魂。"]},{"t":"赋得望罗浮寄赠尼邱山司理","f":"七言古诗","c":["罗浮四百七十峰，峰峰秀结青芙蓉。","璇房瑶室纷窈窕，金书瑶检秘奇踪。","石楼夐出绛霄上，铁桥迤逦屼相向。","竹叶长含鸟篆文，昙花似擘仙人掌。","何处仙人去不还，空馀流水声潺潺。","丹灶烟笼绛幕冷，石林苔蚀紫衣班。","武夷仙子风流客，近署罗浮列仙籍。","篴吹梅花五岭春，笔染明霞千嶂色。","日观峰头贮綵云，朱明洞中凌紫氛。","因风为招洪崖侣，授我长生玉笈文。"]},{"t":"赋得楚天春雁送友人","f":"古风","c":["春雁南归何迢迢，家在衡阳万里遥。","衡岳去天不盈尺，上有回雁之高标。","行行刷羽摩青霄，家山云树郁岧峣。","潇湘夜雨寒芦暗，黄陵苦竹垂新条。","九疑九曲纷相似，此中零雨暮仍朝。","云梦平吞若八九，君山一点似萍飘。","大王雄风起天末，神女行云漾翠翘。","送君行，行且谣。","人生可似随阳雁，相看南浦别魂销。","今日南浦头，明日湘江渚。","苍梧云去湘水深，犹记啼痕染竹处。","断行且莫怨离群，缄书为寄洞庭君。","黄鹤楼空山月白，好去吹箫弄綵云。"]},{"t":"南山樵客歌","f":"古风","c":["朝采南山樵，暮采南山樵。","南山高高，白石嶕峣。","黝壑无人，阴风飂?。","风飂?，多古木。","云里缀荷衣，岩际搆萝屋。","渴饮沆瀣，饥餐玉禾。","朝朝暮暮，南山嵯峨。","灵风吹我襟，甘露洒我发。","薄暮采樵归，肩头两明月。","采樵复采樵人，间方外共逍遥。","世间甲子何曾记，洞口碧桃花自飘。"]},{"t":"庐江叟","f":"古风","c":["庐江叟，庐江叟。","扁舟横竹竿，得鱼且沽酒。","朝钓庐江浔，暮宿庐江口。","秋晚庐江木落时，风袅垂杨飏钓丝。","绿蓑细雨归何处，炊烟一缕傍江湄。"]},{"t":"余彩震斋中古瓦盘歌","f":"古风","c":["兀兀棱棱一古瓦，是谁良工范而冶。","塼沙摸土近千年，可惜沈霾尘土下。","怜君清高雅相宜，中庭贮水漾沦漪。","浇花芳径添新润，洗砚閒斋澹古姿。","世人贵耳不贵目，纷纷好古翻成俗。","不见魏朝宫寝久无踪，后人埴瓦犹衒鬻。"]},{"t":"赋得钱塘歌送张仪吉","f":"古风","c":["君不见钱塘波浪动地来，奔流喷薄共潆洄。","张郎笔底驱河岳，气与秋涛争喧豗。","当年早谢儒冠累，耻学低头事权贵。","漫尔江湖作浪游，亦向云山称典记。","以此蹉跎秋复春，棕袍布袜忘其贫。","袖中虽有龙蛇璧，世上徒逢按剑人。","君今倦游归闾里，锦帆欲指三江水。","杖履晴霞岭外春，烟花夜月吴门市。","吴山一片石峨峨，西湖绿水漾微波。","他时兑得馀杭酒，与汝同醉金叵罗。"]},{"t":"赠医士王明心","f":"七言古诗","c":["城中十室五药肆，朱牌粉额纷相向。","十指茫茫看病人，恰似捉月虾蟆状。","我爱山人王明心，指头了了现诸相。","为悯众生受病多，不辞身寄江湖上。","平头童子负奚囊，到处名山一相访。","曾从庐顶掘仙茅，今在岭南食蒟酱。","中林亦有餐霞人，时时相过问无恙。"]},{"t":"刘仲安以青山草堂诗见贻寄题一首","f":"古风","c":["城里有佳山，沈霾如许久。","浑沦气色疑未分，恰似精华今始剖。","刘郎本自天台流，今来却是云山友。","城郭劳劳到者稀，扪历方知岩岫陡。","前山如揖复如趋，中岭峨然似拱受。","万瓦鳞鳞睥睨间，炊烟几缕萦林薮。","峰头古木不知年，阴森或有精灵守。","閟林黝壑悄无人，偕游必与烟霞耦。","刊木随方借卜居，小构茆亭仅数肘。","镌石磨崖记岁年，我与山灵良匪偶。","岭上白云堪赠谁，缄题为寄中林某。","剩水溪头侬是家，薄有园庐宽似斗。","非无圭山一片翠，望里迢迢隔窗牖。","君今振衣千仞岗，笑我红尘地下走。","纸上分明寄卧游，云关有路何时叩。","看君不是山泽癯，广额棱棱河似口。","暂尔云山狎主盟，它日移文君讶否。"]},{"t":"赠琴僧","f":"七言律诗","c":["古桐斑驳冰纹断，雪色湖丝七缕绊。","凭将指下悟禅机，轻霜拂林秋籁微。","梵语清圆呗音细，吾师传琴即传偈。","身如槁木心如灰，一派清声空里曳。"]},{"t":"余以怪石两枚赠平子五年于兹矣今来过访袖出相示摩弄之馀辄赋短章","f":"七言古诗","c":["长河淘出璚砂粒，纤指螺纹绾细发。","琉璃潋滟珠光明，净滑擘开安榴核。","绀绿铜柈贮碧漪，照胆光丝凛寒骨。","青逼摩尼映法筵，借与刘郎供古佛。","乞来圣水浴云根，散香多在维摩室。","休言超劫出污坭，前身恰是中林物。","五年重饮剩溪水，石共点头私作语。","分明记得旧精魂，前度刘郎从此去。"]},{"t":"戏作调文起兼以自嘲","f":"七言古诗","c":["银蒜押帘镇绣箔，宝篆烟馩罩翠幕。","公子兰房深又深，玉绨半臂犹嫌薄。","屏外酸风刮刮寒，玉围遮煖排香阁。","蜃窗光送日曈曈，梦中犹抱玉玲珑。","美人香额初描黛，何郎粉面半流红。","热情偎得如炽炭，仙袖飘来尚倚风。","中林措大竹方床，梅花帐里伴蟾光。","休云冷落鸳鸯债，省得金钱买药王。"]},{"t":"高台古树行为区茂对昆玉作其树先大夫手植也","f":"七言古诗","c":["此树生来如许久，闻道台成树已有。","树根入土知几深，土面蟠根已半朽。","暗想累台覆土时，根株著土一齐移。","台高不改旧规格，树古年年发新枝。","五马门前一径深，森森台畔表乔林。","为言世远思培植，更筑崇基护绿阴。"]},{"t":"江上观野烧","f":"七言古诗","c":["黑云叆叇天模糊，火龙衔烛照幽衢。","却讶蚩尤喷紫雾，翻疑鲛室弄明珠。","卓起弥天锦步障，撒开大地红氍毹。","螺髻新妆初洗黛，峨眉淡晕亦施朱。","映日扶桑高万丈，红楼十二遥相向。","浮来金海漾荣光，影入银河添新浪。","惊起天鸡五夜啼，银蟾半落玉绳低。","江静老骊眠不稳，露寒惊鹊夜难栖。","带陇连岗同一色，此时目断思乡客。","渔火疑萤望不分，空月如霜照愈白。","沙雁嘹嘹向夜鸣，舟人火里认山城。","残叶原头捲欲尽，湿云洞口烧无声。","孤蓬飘荡无南北，可似游人江上迹。","已将凉燠付浮烟，还悟生身同火宅。","浩劫炎炎烬亦寒，世界应同幻影观。","侵晓推篷试一望，青山依旧郁巑岏。"]},{"t":"卖花郎","f":"古风","c":["卖花郎，卖花郎，年年月月为花忙。","六时灌溉无停手，一岁能得几春光。","男叫女啼俱不理，惜花胜于惜儿子。","花正笑时尔独颦，花睡浓时尔先起。","满园烂熳为谁春，花何富贵尔何贫。","漫道主人爱花好，奈何花开别主人。","城中日日看花醉，谁念种花人苦辛。"]},{"t":"观鸬鹚","f":"七言古诗","c":["渔翁手撚一竿竹，和烟夜傍鸬鹚宿。","编橛为槎水面浮，朝放鸬鹚下沙洲。","鸬鹚渺渺随波去，渔翁却立在槎头。","沙浅日明鱼出曝，呼群引类相追逐。","大鱼背负小鱼衔，总得鱼来不入腹。","渔翁袖手鱼满筐，鸬鹚水底为谁忙。","儿童但笑鸬鹚拙，我独临流暗自伤。"]},{"t":"游月华寺","f":"七言古诗","c":["跋陀坛边悬表志，留下菩提真种子。","百七十年似弹指，袈裟罩却坟前垒。","谁将一滴遍河沙，二叶依然结五蕊。","至今人饮曹溪沚，尽是吾师功德水。","石龛閟骨一千祀，劫火烧空永不燬。","有口无言坐堆堆，落叶归恨水见底。","瓦澄如漆绛罗委，行人瞻拜泪瀰瀰。"]},{"t":"游阳历岩观瀑布","f":"七言古诗","c":["阳历山前巉削壁。","倒挂云岩石洞黑。","未解源泉何处寻，但见长空一道白。","远望还同玉柱观。","近看却似泻冰盘。","旋和甘露灌僧顶，忽傍飘风洒客冠。","崩崖陡下数千级。","石面苔花泫泫湿。","曳来云脚共斜飞，迸出山腰还倒立。","山腰云脚路重重。","小桥转过碧冥濛。","珠幕光中开古殿，雷声吼处度遥钟。","二十琉璃鉴石室。","绛帏閟护金仙骨。","却从瀑里现龛灯，髣髴银河吐海日。","半空分沥入山厨。","竹笕探来石臼储。","敲火石头自战茗，咒泉钵底乱喷珠。","千奇百幻看难尽，闪日摇山目乍瞬。","赴壑迢迢知几深，攒峰窅窅望逾峻。","夜半磬声窟里传。","游人惊立暝林烟。","山僧却道耳根熟，偏向岩端结静缘。"]},{"t":"读陈使君赠梁山人歌因作继赠","f":"七言古诗","c":["二十年前同学易。","露珠细点虫文迹。","我犹章句守训诂，君悟无言静钩索。","离离数画玄中玄。","北窗梦到羲皇前。","叩响无声尝味淡，个中安得落言诠。","黾文点里参性命，枯草茎中决兆先。","夜半无眠升屋脊。","步景窥躔罔差忒。","却从星宿想河源，暗向昆崙觇地脉。","须弥西向舒一臂。","天下名山尽迤逦。","我读内经半信疑，凭君指出真图势。","恒持此术去救贫。","君今数口犹依人。","始知负穷亦有命，遵坎乘流是易因。","境内山川行欲半。","岳游尚为婚嫁绊。","穗石城边僦舍居，儿自执经僮执爨。","从来术高和者稀。","满腹经书不疗饥。","教儿只有床头易，日午垂帘对下帷。"]},{"t":"葵叶蒲团歌赠叶世美","f":"七言古诗","c":["江南六月火云卷。","家家人制蒲葵扇。","馀叶留将缉绿蓑，山僧巧设閒方便。","规成璧月影团团，堪作蒲团堪作簟。","碧眼胡僧航海来，手里摩挲目未见。","有时胡跪白真言，有时趺坐拈珠串。","茆檐向月转经残。","一片琉璃挂壁寒。","中林借作常供具，棐几明窗静处安。","閒阶净扫明如拭，剥啄无人户返关。","泉声战茗来松阁，花影移阴过药栏。","携将芳径衬苔滑，藉向花茵点蕊斑。","青蒲叶叶具禅意。","输与中林识真味。","销金帐里红氍毹，几人抹杀閒风致。","虚白道人口谈天。","方床木板坐无毡。","寄与中林栲栳物，倦时好枕石头眠。"]},{"t":"送玄阳道人","f":"七言古诗","c":["玄阳道人冰雪姿，铜冠羽扇鹤氅衣。","庞眉斑鬓貌婴儿，三花聚顶施华滋。","庐中丹阙白玉墀，骖驾素鸾驭赤螭。","昔在终南采蕨薇，今向罗浮撷紫芝。","相逢石上歌竹枝，挥手云山从此辞。"]},{"t":"病中承王侍御老师分惠药金赋此奉谢","f":"七言古诗","c":["五羊城中地一片。","轻车沓沓游尘卷。","柏府门前对巷居，镇掩双扉人不见。","十日九日雨迷离。","乞火不来朝烟迟。","或过禅堂趁净饭，有时淅米寄邻炊。","坊头酒价亦不贵。","病眼年来没兴味。","箧中剩有鹔鹴裘，不兑酒钱兑药费。","茆檐向日曝芝苓。","手掬清泉注瓦瓶。","按图且学轩辕势，无事但看神农经。","残方屡试效难取。","走向街头寻药谱。","可奈囊空无一钱，措大文章贱于土。","低头不肯向时人。","绣衣使者惠金频。","谁云霜威凛如许，吹入寒崖便是春。"]},{"t":"小雨池上同韩孟郁对酌","f":"七言古诗","c":["夜听滴沥溜檐响。","纸窗划电明如晃。","朝来积水漫平池，萍叶离离沿阶上。","我家剩水绕门前。","绿筱丛中泊钓船。","湘帘捲练平如席，梦里潮声到枕边。","朅来市上红尘走。","僦居徒傍官衢口。","半亩方池澹不流，更无隙地栽花柳。","今朝疑对辋川图。","曲阑干外看模糊。","强将芥子投杯沼，陆地岂必非江湖。","乡心对此全消遣，况有高人问酒沽。"]},{"t":"梁国桢寄曹溪露茶兼订住山之约答之","f":"七言古诗","c":["曹溪老僧斲石骨。","种得芽茶细似发。","白露才过三两日，青布裹头笼焙出。","嗅香果足醒心魂。","郑重封函远记存。","我曾一饮曹溪水。","中泠惠山只如此。","城中止数蟹眼潭。","三十铜钱买一墰。","我对佳茶想佳水，今年定住曹溪庵。"]},{"t":"一拂道人夜话","f":"七言律诗","c":["世事茫茫无定所。","昨日阴晴今日雨。","几场春梦梦中参，一盏青灯灯下语。","怀中心事口中言。","欲吐不吐耳属垣。","殷勤赠君一片铁。","袖里摩挲肝胆裂。"]},{"t":"长歌赠李嗣良","f":"七言古诗","c":["吾家嗣良青莲后。","新诗百篇酒数斗。","自言诗与酒相成，混沌元从醉梦剖。","瞹瞹玄黄窅未分，尔时一线灵光浏。","隍中之鹿甑边人，醒来摸捉原无有。","刮面旋风入耳轮，急沈松煤挥秃帚。","诗喉涩处酒灌浇，酒兴慵时诗擞抖。","万斛明珠似涌泉，通体琉璃含锦绣。","来游五岭不知年，酒伴诗朋靡不叩。","时过白社必攒眉，或醉红裙辄濡首。","高谈每动公卿坐，里巷酸儒或掩口。","暇叩中林手一编，顾谓髯公首肯否。","髯公亦是一酸儒，称诗只解陈窠臼。","勺酒入唇便倾倒，眼花落井扶墙走。","嗣良笑我非丈夫，我言醉醒不在酒。","譬如诗趣非关诗，千古几人露眼手。","曲栏花下写乌丝，一片斜阳挂户牖。"]},{"t":"曾文卿见赠诗扇辄答","f":"七言古诗","c":["耳君香名业已久。","卢生向我大誇口。","掌珠怀月底般明。","争似曾郎标格清。","曾郎与我才相识。","纨扇缄题劳寄忆。","诗比飞泉一派清，流出禺山千仞碧。","挹君风度读君诗。","转忆临流挥洒时。"]},{"t":"赋得衡山送张明府还龙门","f":"古风","c":["望衡山，衡山高不极。","七十二峰头，峰峰如列戟。","三十八洞泉，泉泉通地脉。","祝融崚嶒倚天外，芙蓉石廪势如掷。","瑶函漶没几千秋，中馀玉宇不可识。","非但列宿应机衡。","人文往往发休徵。","伊山古屋读书处，至今紫雾屯青冥。","我公早毓衡山秀。","气吞云梦常八九。","探奇欲蒐洪荒前。","文雅直追宋屈后。","登坛一啸雄风来。","化为云雨遍苍垓。","天南两地行云过，次第薰风桃李开。","回风披拂甘棠树。","昼永鸣琴坐清署。","彩笔雄驱七泽涛，翰墨淡扫潇湘雨。","花前小队缓辔行，章缝竹马杂交道。","不独解推怜赤子。","也能吐握下儒士。","江南二月春和煦。","星轺卑发邮亭路。","不尽扳辕卧辙情，空馀下榻鸣琴处。","岭云楚水望迢迢，中天衡岳倚晴霄。","缄情惟有衡阳雁，翘首龙门天路遥。"]},{"t":"酒保","f":"七言古诗","c":["侬家老店驰名久。","坊市人家侬居首。","千金不与瓮头方，百钱只沽壶中酒。","底须铺上悬空尊。","更深人尚打柴门。","大墰小盎搬不尽，楼头瓮底醉昏昏。","从来卖酒卖风趣。","本多利少平平兑。","海内闻名远见寻，上客嗅香旋已醉。","劝君买酒细细尝，坊头坊尾卖清水。"]},{"t":"即事","f":"七言古诗","c":["十八滩头滩浪高。","雨声滴滴水嘈嘈。","万丈巉崖挽不上，漩涡一拄没长篙。","舟人相顾戒舟楫，小港洄波冲舟入。","息棹惟闻蛙蝇鸣，篝灯自检琴书湿。","朝来拥被正高眠。","直至亭午突无烟。","儿童报道籯粮尽，野旷无人青草连。","思向邻舟贷馀粒。","欲语不语还羞涩。","林生佞佛持清斋，自啖齑盐倾米汁。","扬郎数米供晨炊，顾见釜中已生鱼。","当年不索长安米，穷途往往叹居诸。"]},{"t":"汉阙双凫卷送周明府入计","f":"七言古诗","c":["客星迢迢度南越。","化作双凫傍双阙。","乍看流影入彤霄，忽曳清声破晓月。","月色胧胧启曙辉。","九重端御正垂衣。","龙鳞光绕翠华仗，鹓侣齐趋青琐闱。","夹城日高未下殿。","离宫别馆罗清宴。","玉宇遥瞻五位尊，金茎特赐群臣遍。","周侯为政古循良。","舄影高悬紫极光。","到日定知扳睿作，会有赓歌续柏梁。"]},{"t":"有客携风木遗思卷索题时午月朔次日为先子讳辰余恫焉有感挥泪书之","f":"楚辞体","c":["白日堕西山，流波到东海。","人寿亦如斯，奄忽不相待。","岂曰无亲亲莫留。","树兮欲静风不休。","孤儿独洒终宵泪，苍天漠漠白云悠。"]},{"t":"徐生","f":"古风","c":["徐生七尺躯，少小轻投笔。","自言亲授异人编，妙精玉女及符术。","此中千年秘不传。","风云遘会岂徒然。","男儿致身须及早，毋令祖生先著鞭。"]},{"t":"有剖蛤蜊者满腹皆虫蛆再剖亦尔莫测其故余作歌示之","f":"七言古诗","c":["阎浮世界大海水，泡影光中化百族。","皮毛齿角及鳞介，下至有头若无足。","莫不含灵具至性，其中一一有佛慈。","佛慈众生无差别，佛相遍现亦如之。","应缘度生垂化迹，不争其类争其时。","迷人不解佛真性，敢向众生笺慧命。","鸾刀一启性命悲，一日不启馋难支。","弥天杀网张沙界，万劫相寻无尽期。","诸佛名为可悯者，以杀止杀应难化。","殷勤摘叶付儿啼，方便菩提證刀下。","枯壳相中转法轮，俨然大士现化身。","河目珠眉光满月，璎珞伽黎妙入神。","竖儒不察其中义，只道形模偶相似。","肯信文殊累劫因，前身曾脱蛤蜊蜕。","云何馋腹竞啖吞，依然蜷壳食蛤蜊。","菩萨如来大悯伤，不示慈容示丑类。","双壳才开百蛆攒，细似牛毛簇似猬。","投之以水蠕蠕活，谛视良久生寒悸。","须臾更剖亦如斯，倾筐一掷沟与隧。","此段因缘讵偶然，我云是佛显教权。","众生业轻犹可度，一凛慈容信且坚。","辟如刽子逞刀手，见其父母刀亦捐。","迷人业重佛不转，枉教善巧行方便。","咽喉火起业生贪，夺其所夺业不现。","蚖蛔钻额蛆腐肠，对此何如尚敢尝。","翠盘有箸不能下，何用鸾刀重创伤。","罪性空时莫问果，佛佛圆明珠颗颗。","就将蛤蜊比莲台，颗颗中具如来座。","佛遍恒河沙界中，物物应与蛤蜊同。","乍然悲喜生畏抑，是物皆现圣慈容。","有如贪喙恣豪嚼，钵盂净饭亦生虫。","此是如来秘密藏，芥子须弥纳万象。","提出吹毛颔下刀，抉去空华目里障。","不然枯骨有何灵，猪齿白骨现佛形。","狞犬衔来不敢食，难道畜生不爱腥。","狗子有无佛性也，且扫涂抹几剡藤。"]},{"t":"古研歌","f":"七言古诗","c":["古砖何年入古穴，穿井出之土脉裂。","十丈寒泉閟不泄，冷光一道吹阴雪。","金石匪儗色则铁，擘处恰似神工掣。","有渍蚀痕蘸鬼血，其纹错缀细如缬。","面稍平之微凹凸，凹者似藏轻沈涅。","以手揩摩气尚馝，锐首丰下存朴拙。","天然制与雕锼别，前人作事多不劣。","不取其全因其缺，孤赏肯留耳目亵。","誓与重泉共封闭，神气澌尽土气歇。","岂料终为后人窃，穴之所有化尘屑。","砖立其中神孑孑。","或言文士精所结，毕竟难将物理洁。","奇物从来运世阅，一砖可悟恒沙劫。"]},{"t":"赠周明府复任","f":"古风","c":["周侯挺秀自贵竹，英姿皎皎湛瑶玉。","早穷学海障回澜，上陵班马掩张陆。","九苞霅煜含灵文，万里骁腾看逸足。","当年射策谒明光，我侯弱冠何昂藏。","金镳玉勒桃花骑，横行帝里晔生光。","驰过金马门突入，麒麟殿，鸣珂散。","紫宸扬鞭挥赤电。","意气凭陵跨五侯，文采风流至尊羡。","铜章墨绶竹为符，出领专城宰大都。","排棼解错利器别，坐理弹琴古所无。","冈城亦是先儒地，衣冠礼乐号名区。","比年水旱驱盗贼，况乃榷算太烦荼。","孤城嵲嵲谁安堵，百口嗷嗷思待哺。","我侯呕喔若慈母，拔冤起殢同焦枯。","是时封狐当路衢，磨牙吮血恣所娱。","薰孤掷鼠自不惜，直探虎穴捋其须。","忠诚可以回日月，子惠宁论遍里闾。","三年治行冠南海，卓异循良汉茂宰。","忽讶王乔舄影飞，更留召伯甘棠在。","十里壶浆拥道周，万人伏阙竞遮留。","圣主独廑南顾虑，诏从借寇解民忧。","进贤之冠紫貂裘，是日承恩出凤楼。","香含玉座烟独满，露浥金茎泫未收。","看花上林苑，折柳大江头。","自从折柳度江越，清梦迢迢悬魏阙。","凫影晨飞碧海霞，琴声夜傍黄云月。","黄云佳气郁崔嵬，到日襜帷首重回。","横波旧识鲸鲵净，夹径依然桃李开。","吏人肃候干旄返，父老重迎竹马来。","余也蓬蒿一贱士，剪拂曾蒙伯乐顾。","空衔一寸明月珠，欲报深恩无处所。","去年送送出河关，双凫可望不可攀。","今日江凫下江北，扶摇更待凌风翼。","南国苍生一解颜，宣室求贤正侧席。","祇恐徵书下九重，虽欲借寇借不得。","噫嘻虽欲借寇借不得，为侯歌德铭金石。"]},{"t":"题舍弟浣句池","f":"七言古诗","c":["吾家仲子差不俗，斗如一室罗花木。","当门嵂屼对南山，白日云阴溅飞瀑。","穿云入洞几逶迤，疏脉通泉贮作池。","我有旧题浣句字，移来恰好稳置之。","此池不深亦不浅，其中可畜数鱼儿。","漱流洗耳古人事，取名浣句夫何为。","浣之又浣无不可，其句伊何文与诗。","一字经营堪呕血，片言悟心差解颐。","匡床木榻堆湘帙，倦即高眠醒即披。","我来扼腕论今古，偲偲切切复怡怡。","此道由来有宗统，譬如大海汇流澌。","狂澜一柱任颠倒，东西南北纷如驰。","何当一挽天河水，洗涤日月净昏霾。","雕虫呫哔竖儒事，千秋之业宁在兹。","高歌一曲卧池上，梦入池塘春草时。"]},{"t":"玉漱云牙卷","f":"楚辞体","c":["云有根兮玉有乳，昆邱渺渺蓬瀛渚。","三花树上素鸾栖，五色霞中丹凤驻。","谁餐玉液炼青精，谁拥云裾驾綵骈。","左拉云君右玉女，手握芙蕖觐玉京。","为君一奏霓裳曲，曲绕行云声戛玉。","天上云璈十二徽，世间弦管空局促。"]},{"t":"醉歌走笔示胡伯连","f":"七言古诗","c":["孤剑迢迢望都门，鹴裘敝尽客衣单。","清时儒冠不抵事，掷去长安博一官。","肝胆摩来手尚热，须眉向处面常寒。","昨冬驴蹶余伤手，此时肯归归已久。","南都不住北都住，满面红尘路上走。","当时射策尔如虹，胡为一堕云雾中。","同是天涯无根草，吹落沙尘任转蓬。","我昨青袍持一刺，三走朱门投不得。","恨不相携胡伯连，急向红槽占一席。","鼻头火出气如蒸，却敲铜盘呼卖冰。","呷来五内战寒热，归卧两日不能兴。","今朝强起头未栉，手持竹帚打苍蝇。","东邻彼美邀余饮，索余艳语写徐陵。","胡郎痛饮能数石，笑我量不如瓶罂。","三杯入口颓然醉，须臾一觉辄成醒。","案头残墨濡濡湿，信手狂涂几剡藤。"]},{"t":"送吴将军良卿就试大司马","f":"七言古诗","c":["燕山九月飞阴雪，画角城头声咽咽。","司马辕门牙帐开，十万材官分队列。","令旗卓处鼓三严，马首嘶澌蹄超忽。","朱缨皑甲晃寒光，满臂骍弓如抱月。","万人丛中逞好手，目快意迟惜始发。","飕飕鸣镝贯垂杨，盾鼻濡毫奏策章。","宫花插鬓袍如血，五凤楼前谒君王。"]},{"t":"送蛾眉山僧","f":"古风","c":["君不见蛾眉山高高，一抹入云霄。","紫雾濛濛暮复朝。","下视尘界千万里，宛如沧海一萍飘。","上有玉芙蓉，瓣瓣插太清。","问师何赤脚，曾踏莲花顶上行。","问师何所有，一锡并一盂。","锡底飞空常不住，盂里藏龙蜿蜿舒。","朅来行脚遍尘寰，恍如身坐蛾眉山。","火里青莲长不灭，风中幡影任飞翻。","瞿塘滟滪何壮哉，不用折芦与渡杯。","一盂?尽锦江水，卓锡横空是归来。"]},{"t":"岁暮放歌","f":"七言古诗","c":["著书十万付名山，何如抱策叩燕关。","浮名千秋俱等閒，但取黄金系肘后。","还留白眼向人间，蔡公一言夺封侯。","苏生十上仍不收，世间巧拙皆自谋。","生憎子云老执戟，草玄卧阁风飕飕。"]},{"t":"羽甫家兄斋中曲木几歌","f":"楚辞体","c":["离奇古木不中绳，以之为器器不平。","吁嗟岂是樵爨物，高人一见眼自明。","登君之堂作君几，我取离奇不取平。","古之奇人多礧砢，其貌嵚巇而可惊。","始知世俗称平者，乃是钝滞之别名。","山不奇兮不肯高，水不奇兮不肯清。","平莫平于案与椅，终日对之有何情。","请君相士如相几，但见离奇切莫轻。"]},{"t":"羽甫家兄池上白鹇歌","f":"七言古诗","c":["世间不独少閒人，人间亦复少閒鸟。","白鹇为性本幽閒，行步纡徐翮夭矫。","如今世上少閒林，不如敛翮向君沼。","君之池沼最清閒，主人与鸟立池间。","若个閒人肯伴鹇，我即开门问往还。"]},{"t":"再题金粟泉书苏公祠壁","f":"七言古诗","c":["茫茫大海汎玻瓈，奇甸波心一叶挈。","中有寒泉漾碧光，宛如荷面珠明灭。","谁云海眼与潮通，泉味夐与咸潮别。","石缝澄澄几许深，飘来金粟纷如屑。","山上常闻产玉禾，井中谁解有金埒。","僧雏誇语未足信，居人拾得为余说。","我来窥井窅无见，恰如贫子思金穴。","何须海外觅黄芽，一歃神瀵甘且冽。","曾浮杨子饮中泠，此泉堪与相颃颉。","天荒海阔无人到，羽也泉经安得列。","前余饮者苏端明，冷庙颓垣碑孑孑。","入门见像不肯拜，手自扪萝看古碣。","佳水佳山信有缘，要待奇人成三绝。","二十年前我梦游，光景明明目所阅。","却恨端明不我见，江山千古留馀缺。","今来挥手与山辞，泉声为我增幽咽。","流波滚滚送游人，五百年后何人啜。"]},{"t":"二一斋歌为俞季郎作","f":"古风","c":["浊醑一觞歌一曲，人生两事亦云足。","来日苦短去日多，有酒不饮欢不歌。","吁嗟人生奈乐何。","床头有金瓶有粟，终日忧生犹不足。","侬今不饮有何欢，侬若不歌便当哭。","生不必逢李太白，亦不必逢贺知章。","今人岂必古人让，不见西良俞季郎。","季郎胸中一物无，斋头黄卷与青壶。","閒来对酒发长咏，歌罢墙头又自沽。","不署苦吟先生，不狎高阳酒徒。","季郎自用季郎法，咽喉长润腹不枯。","长鲸一吸千江水，老蚌一喷万斛珠。","醉来不蘸张颠发，百番溪藤信手涂。","季郎不苦胡为乎，世间清福须人享，瓶罂有材亦有量。","老而材寿酒性悭，我对季郎空技痒。","冷斋无事学枯禅，冻盎梅花兀相向。"]},{"t":"题羽甫小影","f":"七言古诗","c":["昔别江头看晓晖，君从江北望余归。","琼海迢迢音信稀，思而不见重依依。","见君纸上是耶非，须眉欲动韵霏霏。","迫而叩之声息希，无言无语自按徽。","如何觌面乃相违，徙倚沈吟兴遄飞。","七弦在手倩君挥。","君如顾我笑微微，我已潸然泪满衣。"]},{"t":"题高公先画","f":"古风","c":["昔我骑秃驴，关山几万里。","当时只叹行旅苦，岂知身在画图中。","览图始知行旅好，在家宁免絷樊笼。","木叶落，小亭空，短桥东复东。","霜凄露正浓，敲诗谁是骑驴翁。"]},{"t":"大方伯王公平寇歌","f":"七言古诗","c":["枭雏叫风古木恶，火光迸地贼星落。","高牙卓处斗帐悬，八面旗门仗鼓角。","炮声一响贼移营，贼酋早向营前缚。","零星部落半无主，羁鸟吊巢鱼泣釜。","一阵风吹栅烬灰，化作营前乾白土。","马前将吏走如飞，急传令箭解重围。","村村擂鼓赛神酒，驮著牛车牵犬归。"]},{"t":"过石门访王尧韭新居","f":"七言古诗","c":["钟鼓楼前吹画角，烟火家家遍城廓。","太守祠荒径草深，居士披裘恒带索。","数武方塘接敝庐，相过不用唤篮舆。","登堂把臂忘宾主，楸局桐徽问古书。","未论胜具雅非一，交情不与流莺匹。","懒将笑语媚时人，生成一片崚嶒骨。","素业难凭清吏遗，青缃自是侬家物。","环堵萧然不是贫，布袜方袍野葛巾。","移泉不问晴和雨，听鸟常同昏与晨。","老子生来有洁癖，海南独恨少茶宾。","三日门前无履迹，便遣平头走通刺。","先生蓬巷雀张罗，居士萝轩门是席。","我从挟策望燕阍，君亦移家向石门。","石门确确石径滑，虚庭无瓦草依垣。","匡床祇有残书帙，客来何处话琴尊。","问君扩落胡为尔，吞声嘿嘿不敢言。","自古世途多偪窄，劝君舒眉莫戚戚。","沧海有日碾成尘，深谷须臾变邱垤。","胡为坠地七尺身，不寄四方寄四壁。","我今浮海即为家，君今无家亦似客。","大地何分南北居，我身仍是去留宅。","世情厌故不厌新，贺君且结石门邻。","蜗牛行处头戴屋，人生随寓可安身。","石门石门何嶙峋，门前沙井清粼粼。","愿将一掬清泠水，且浣舍田耳畔尘。"]},{"t":"赠杜玄洲将军","f":"七言古诗","c":["生来胆识最超群，掌上兵机指画分。","三入武闱魁浙水，独提偏帅领涯濆。","断鳌岛澨城依垒，射雉山椒箭没云。","驻劄恰当琼要害，长驱欲扫瘴妖氛。","弓弯满月乌号靶，旗飐垂虹虎爪纹。","碧海无波人偃甲，绿林息警燧沈煴。","鸡声晓漏屯吹角，鼍吼空江浪打鼖。","每入郭门张绿幕，径邀所辈醉红裙。","觥筹错落豪能整，诗翰纷披雅且文。","芳茗自教童子瀹，沈香时对韵人焚。","诙谈五夜殊无倦，轰饮千杯亦不醺。","白眼剧怜肝胆热，清歌微觉齿牙芬。","幕中才调真无匹，海外诗坛近有闻。","裘带昔传羊叔子，风流今许杜将军。"]},{"t":"九莲歌赠冯载赓","f":"七言古诗","c":["我闻西方极乐天，九品莲台九品莲。","栏楯七重围宝树，重重帝网空中悬。","西方极乐真难状，苦海众生尽回向。","识风鼓浪欲河深，谁向龙宫窥海藏。","龙宫金阙贝为楼，斮鳌四足奠中流。","神洲列岛琼居一，缥缈随波海面浮。","一片红轮挂树上，八面无风摇碧浪。","五指嵬嵬高戟天，捧出玉毫真佛相。","瓶持甘露洒琉璃，手翳芙蕖跨白象。","我曾折芦一问津，彼岸茫茫隔世尘。","偶逢居士掀髯笑，笑指莲花是夙因。","精庐也傍莲庵侧，滴翠门前摇冷碧。","维摩斗室一匡床，藏尽世界人不识。","度世缘深入世閒，浴日扶天手一只。","暂将高韵寄琴书，雅有閒情课水石。","昙花如掌卜成林，酌水餐霞养道心。","我来不语拈花笑，君抚无弦七尺琴。","落日衔山风在牖，竹里茶香烟缕缕。","雨觥我筹忘主宾，抹月批风笔如帚。","隔壁分来是佛灯，昏衢一点明于昼。","海潮三丈梵流音，破云隐隐木鱼吼。","滴翠山房九莲庵，截断芘刍未许谈。","同君共拈无言偈，胡床静里且须参。"]},{"t":"题昌化令张侯瑞应册","f":"七言古诗","c":["大明天子坐明堂，山陬海澨遐哉荒。","悲翠珠贝走上方，有邑淳简儋之昌。","厥侯为政古循良，则壤惟赋均且详。","鞭笞不事民乐将，桄榔树下课农桑。","有雨随车濡瀼瀼，散之原野尽天浆。","禾登于垄谷盈厢，民之乐只帝力忘。","槟榔椰实树千章，更于其下牧牛羊。","使君何必下琴堂，八风六律调宫商。","雁鸿中泽鸣载翔，鸮食其葚音则臧。","草不知风波不扬，三秀晔晔产芝房。","金砂淘粒蚌舒光，丰碑洗出峻灵王。","再拜稽首神固藏，公无渡河河汤汤。","须臾汔济河断梁，民加其额公寿康，公曰偶尔未为祥。","即今奏最上岩廊，天子曰嗟尔化昌，御屏定书昌化张。"]},{"t":"解嘲和坡公夜梦","f":"七言古诗","c":["旁人笑我士不如，终日諵諵一卷书。","龛灯常过午夜馀，是起刚及晓钟初。","胡为局局不自舒，前身定是一蠹鱼。","我言万族皆有缘，诗书于我真奇偏。","带经而仕又三年，依然旧习相搆缠。","较之博奕此为贤。","匪余癖也古有然，大圣三绝易韦编。"]},{"t":"因病閒居和闻子由瘦","f":"七言古诗","c":["近服黄连稍断肉，顿顿只啖黄粱粥。","窗灯眼缬未成眠，入作蚊声逐蝙蝠。","朝来投牒乞移疴，刚得闭门一避俗。","氍毹半拥绛帐明，冷衾未许偎红玉。","风敲短檐落叶乾，寒肌隐隐生金粟。","强调中气守黄庭，心花瞀眩奔狂鹿。","印锁空庭鸟雀哗，山厨黠鼠欺童仆。","才梳短发帽宽欹，带孔移腰形似鹄。"]},{"t":"摘荔枝和谢欧阳晦夫","f":"七言古诗","c":["往来四海五经年，制得沈香黑角冠。","土人笑指私相诧，赠我抺额青花缦。","白藤细笠黄皮屐，我今暂与俗相安。","从来入俗须从俗，且与扬波泛其澜。","万安藤枕细且滑，定安草簟冰纹寒。","携之花阴供午睡，要与家山一样看。","海风啸林夏不热，荔枝五月遍冈峦。","脱冠戴笠游其下，新衣黎葛轻如纨。","三杯粘酒颓然醉，先生颜赛荔枝丹。","倾筐倒来携满袖，饱啖还解带围宽。","东坡韶腹佞其舌，作词翻笑海翁酸。"]},{"t":"王际明以藤枕见贻拈韵答之和坡翁琴枕","f":"七言律诗","c":["七尺匡床置草屋，展开冰簟蕲州竹。","副以万州细藤枕，一生閒具亦云足。","朝来解带倦将迎，重衫脱下汗如漉。","凭君相引入华胥，钧天一鼓双门曲。"]},{"t":"寄何凤来读书西山","f":"五言律诗","c":["是尔栖迟处，西山爽气增。","孤亭悬树杪，小径入云层。","谷鸟啼窗竹，岩花缀涧藤。","冷光摇碧霭，岚彩冒疏灯。"]},{"t":"过越王故苑","f":"五言律诗","c":["废苑郁迢迢，霸图尚未销。","落花如有恨，片片度溪桥。","鸟学歌声涩，云疑舞袖飘。","谁将千古意，指点认前朝。"]},{"t":"自省还洞中作","f":"五言律诗","c":["牢落倦游归，萧然掩旧扉。","藓留题处墨，荷换去时衣。","一雨秋阴淡，孤峰倒景微。","晚来新水到，垂钓坐苔矶。"]},{"t":"寒食感怀","f":"五言律诗","c":["由来寒食节，风雨倍悽然。","人世犹如此，夜台殊可怜。","垂杨烟漠漠，荒垄草芊芊。","向晚乌啼急，双飞集墓田。"]},{"t":"林阳仲携诸子月夜过访余走逆城南不值赋此寄之","f":"五言律诗","c":["共拟探幽去，如何踏雪来。","不知萝月下，曾否荜门开。","行迹馀芳草，留题觅古苔。","冷然清兴尽，何异剡溪回。"]},{"t":"卧病","f":"五言律诗","c":["岁晚怜家居，翛然一鹤如。","常时亲枕簟，经月罢琴书。","文债犹催逼，閒缘未断除。","应门频有报，花下驻朋车。"]},{"t":"开径","f":"五言律诗","c":["开径遥分竹，疏流近接堤。","雨含湘浦泪，春入武陵迷。","细荇鱼吹浪，高枝鹊借凄。","閒情应不减，风物每撩题。"]},{"t":"泊甘竹","f":"五言律诗","c":["稍觉乡关近，移舟泊海门。","万山盘一壑，小经入孤村。","岐路心俱折，还家舌尚存。","不须吟泽畔，沙岸转黄昏。"]},{"t":"经古汶洲寄陈夷仲","f":"五言律诗","c":["此地昔为别，经过倍怆颜。","人家平贴水，日影半衔山。","一雁来何处，扁舟去独閒。","殷勤江上鲤，寄信到松关。"]},{"t":"客至","f":"五言律诗","c":["闭门缘避客，客至偶开门。","乍见不为礼，相看无一言。","烹茶分曲涧，散帙媚幽轩。","勿讶元龙傲，还令古谊存。"]},{"t":"苏汝载山房同韩孟郁杨亦琳刘觐国话别","f":"五言律诗","c":["暝色下庭阴，移觞傍竹林。","别离不在远，去住总关心。","久客乡园梦，怀人落日吟。","共怜他夜月，尊酒不同斟。"]},{"t":"泊黄村","f":"五言律诗","c":["云澹水涓涓，中天皎月悬。","松梧依静渚，墟里上孤烟。","宿桨轻鸥外，乡愁旅雁前。","空江人语寂，对此未成眠。"]},{"t":"元旦祝圣","f":"五言律诗","c":["肃仗传呼急，严城鼓吹残。","千年周镐洛，一代汉衣冠。","淑气回金阙，光风转画阑。","天南虽万里，日出是长安。"]},{"t":"荐家庙","f":"五言律诗","c":["焚香扫敝室，稽首泪沾巾。","虽有冰盘荐，何曾匕箸亲。","萧条伤往事，惨淡对芳辰。","旧种庭前橘，年年春色新。"]},{"t":"游圭峰二十首 其一 入峡望圭峰","f":"五言律诗","c":["群峰趋谷口，绾胜有危桥。","望望玉台寺，钟声来碧霄。","云迷天路迥，水接花源遥。","况复高秋日，登临野思饶。"]},{"t":"游圭峰二十首 其二 玉台寺","f":"五言律诗","c":["宝刹开灵境，慈云护法堂。","僧閒不扫地，客到但焚香。","塔影澄秋霁，松阴散晚凉。","悠然息尘想，随意礼空王。"]},{"t":"游圭峰二十首 其三 玄帝殿","f":"五言律诗","c":["北极是天都。","玄冥护赤符。","风云开法阵，营卫肃辰枢。","玉节时趋阙，商飙飒戒途。","千年香火地，斜日锁金铺。"]},{"t":"游圭峰二十首 其四 文昌宫","f":"五言律诗","c":["灵洞清虚府，天街白玉堂。","山河扶绣栱，星斗焕宸章。","独揽中峰色，还依帝座傍。","碧桃千万树，偏浥露华香。"]},{"t":"游圭峰二十首 其五 观音庵","f":"五言律诗","c":["来参大士座，妙相果庄严。","千手金轮转，双眉珠火尖。","白猿閒听法，青鸽静窥帘。","一片华池月，流光满四檐。"]},{"t":"游圭峰二十首 其六 李真人庙","f":"五言律诗","c":["空传坠履迹，犹想餐芝颜。","古庙无人到，苍苔一径閒。","云阴馀落日，秋露满空山。","何事令威鹤，千年殊未还。"]},{"t":"游圭峰二十首 其七 玄峰道士山房","f":"五言律诗","c":["群峰望不极，一室迥清虚。","莫是化人国，真成静者居。","岩花细绕径，涧水暗通渠。","我亦云中侣，来参方外书。"]},{"t":"游圭峰二十首 其八 听雨坛","f":"五言律诗","c":["扫地象圜丘，祈年事可求。","翻云开羽节，和露荐琼羞。","拥佩祠官集，飏幡真侣游。","近闻四气洽，禋祀不曾脩。"]},{"t":"游圭峰二十首 其九 真人岩","f":"五言律诗","c":["神室何年閟，灵踪久已芜。","古松巢野鹤，阴雪餐饥鼯。","石鼎三芝秀，云房五色铺。","凭高望海气，一点类蓬壶。"]},{"t":"游圭峰二十首 其十 石床","f":"五言律诗","c":["真人惟面壁，石榻仅容肱。","雨没萦裾草，云垂交户藤。","鸟王衔绛果，山鬼吹青灯。","指点灵奇迹，高风信可凭。"]},{"t":"游圭峰二十首 其十一 朝斗石","f":"五言律诗","c":["片石分云出，生成礼斗坛。","星河七曜动，环佩五更寒。","灵雨阴长润，霜华剥不刊。","飞来双白鹄，缥缈下层峦。"]},{"t":"游圭峰二十首 其十二 嘉树","f":"五言律诗","c":["嘉树蟠云固，亭亭万仞枝。","罡风吹不动，湛露泫长垂。","帝遣神工护，人钦佛力持。","林端舍利影，光蘸碧琉璃。"]},{"t":"游圭峰二十首 其十三 瀑泉","f":"五言律诗","c":["双泉悬碧落，百折度丹梯。","迸作飞空雨，泻为漱玉溪。","蒸云喷宿雾，插汉饮晴霓。","可是巫山女，垂垂珠箔低。"]},{"t":"游圭峰二十首 其十四 借宿禅堂","f":"五言律诗","c":["借榻禅居净，冷然听梵音。","灯明方丈室，香袭旃檀林。","共觅无生路，因知不染心。","月华偏法界，清夜对沈沈。"]},{"t":"游圭峰二十首 其十五 石龛","f":"五言律诗","c":["石龛锁青壁，面面有灯燃。","乍映摩尼色，偏临净乐天。","飞空流玉镜，特地涌金莲。","但悟无生灭，何须学四禅。"]},{"t":"游圭峰二十首 其十六 寒甚从道人索衣","f":"五言律诗","c":["名山采药遍，薄暮怯霜寒。","衣自霞缃出，人疑鹤氅看。","凌风云气湿，被月露光漙。","便可还初服，因之制竹冠。"]},{"t":"游圭峰二十首 其十七 从东岭度逆折而西登绝顶","f":"五言律诗","c":["直蹑云根出，方知中岭尊。","地临南极尽，山以北为藩。","曰涌双轮转，枢旋万象奔。","疑闻钧乐奏，咫尺是天门。"]},{"t":"游圭峰二十首 其十八 从真人庵降就行厨入禅堂始饭","f":"五言律诗","c":["凌晨披雾出，归始及朝炊。","香饭僧厨借，山薇野客遗。","和云烹露茗，就石撷灵芝。","顿觉颓颜变，飞仙挟可期。"]},{"t":"游圭峰二十首 其十九 诗社","f":"五言律诗","c":["重来诗酒会，耆旧几人全。","白社空留迹，青山不住年。","荒台萦蔓棘，池草莽凄烟。","寂寞千秋事，登坛一泫然。"]},{"t":"游圭峰二十首 其二十","f":"五言律诗","c":["聊持一觞酒，来就飞泉阴。","远公何处去，策杖还相寻。","同是栖真侣，谁悬出世心。","莞然成一笑，送送过东林。"]},{"t":"秋水芙蓉","f":"五言律诗","c":["朱华涵绿浪，并泻一秋光。","澹冶生閒韵，清妍濯浅凉。","飘来枝影动，散去岸痕香。","水镜如同照，流波望正长。"]},{"t":"寄嗣淳家兄","f":"五言律诗","c":["洛阳千古地，宰邑有吾兄。","露冕行□过，壶浆遮道迎。","云遄雍邱国，花重高阳城。","翘首长安近，双凫切太清。"]},{"t":"讯林阳仲落第","f":"五言律诗","c":["闻君不得意，归复掩柴关。","世路原如此，浮名亦等閒。","曲惭歌下里，书好副名山。","若问行藏事，相看镜里颜。"]},{"t":"登西山阁限韵","f":"五言律诗","c":["秋色来何处，空亭夕景衔。","山情恬鸟雀，霜意宿松杉。","寺近时闻钟，林疏忽辨帆。","平芜踏歌遍，岚重湿衣衫。"]},{"t":"访容植之山馆","f":"五言律诗","c":["山径少逢迎，幽居无俗情。","密云过户湿，细雨入池平。","插架琴书静，侵阶苜蓿荣。","高谈二三子，终日有馀清。"]},{"t":"同余彩震宿东山草堂","f":"五言律诗","c":["城头月似霜，流影入松房。","乍觉衣裳薄，全消枕簟凉。","花阴閒命酌，石几静燃香。","终夜无言说，迢迢清梦长。"]},{"t":"望临江台寄陈瑜仲陈熙父","f":"五言律诗","c":["孤台临断岸，此地昔攀登。","擘石沈危浪，盘空缀古藤。","山童横牧笛，溪妇晒鱼罾。","极目观溟涨，垂纶愧未能。"]},{"t":"赠施纯卿","f":"五言律诗","c":["四十犹未遇，生涯殊可悲。","世情看俯仰，吾道属支离。","挟有干时略，贫无买酒赀。","颓然堪一笑，何物是男儿。"]},{"t":"挽吴别驾","f":"五言律诗","c":["含砂终误毒，抱玉岂鸣冤。","一死酬臣节，千秋作礼魂。","棘林新鬼哭，白日帝城昏。","不是能尸谏，何由感至尊。"]},{"t":"寄怀罗华麓丈人","f":"五言律诗","c":["养寂衡门下，居然丘壑尊。","木奴千树橘，石室一家言。","岁月乌皮几，风花绿玉樽。","暌违今十载，幽意向谁论。"]},{"t":"秋夜访蒋伯瑞小酌","f":"五言律诗","c":["东游不得意，归兴日悠悠。","夜雨芙蓉剑，秋风芦叶舟。","寒虫偏入户，残月故当楼。","况值黄花候，清尊好共留。"]},{"t":"初发湴湖与仲昭侄别","f":"五言律诗","c":["暂尔离乡井，暮行投远村。","驿亭无长吏，稚子候柴门。","平明驱马去，露白岸微昏。","严程自兹始，羁思更何言。"]},{"t":"浈阳道中","f":"五言律诗","c":["危峰半入云，雨色霭氤氲。","向晚浈阳道，愁穿豺虎群。","路回青嶂断，石溜碧泉分。","蒙涂兼历险，于役此何云。"]},{"t":"度清溪","f":"五言律诗","c":["攒峰如列戟，古木郁凄迷。","尽日闻猿啸，长风送马蹄。","人烟茆屋午，官路板桥西。","异境何曾到，磨厓觅古题。"]},{"t":"望曹溪","f":"五言律诗","c":["招提不可到，樵径一僧逢。","问询前山路，翠微知几重。","林光浮舍利，水香藏钵龙。","居然灵境隔，立马听遥钟。"]},{"t":"夜度曹溪","f":"五言律诗","c":["一灯传影后，兹水共留名。","浩淼来何处，沿洄绕化城。","宁因浴佛洁，始辨入山清。","自笑迷津子，褰裳此夜行。"]},{"t":"途中杂咏 其一","f":"五言律诗","c":["京国数千里，悠悠去不停。","鸡声破晓雾，马首认残星。","古戍依寒草，官桥间短亭。","无情堤畔柳，憔悴不成青。"]},{"t":"途中杂咏 其二","f":"五言律诗","c":["野店临平坂，荒村人语稀。","步檐惊虎迹，登榻卧牛衣。","客至时争席，童嗔半苦饥。","天涯一翘首，能使旅情微。"]},{"t":"途中杂咏 其三","f":"五言律诗","c":["北地殊风候，兼之岁欲残。","辟尘缯覆面，冲雪革为冠。","苦水酴酥酒，腥羹苜蓿盘。","罄囊持一饭，未结主人欢。"]},{"t":"途中杂咏 其四","f":"五言律诗","c":["肩舆不可度，霜滑磴途赊。","倒影疑涵水，长天带落霞。","行人驱蚁队，稚子挽牛车。","同旅时相劳，前村日未斜。"]},{"t":"途中杂咏 其五","f":"五言律诗","c":["寒色暝凄凄，荒墟古木齐。","饥乌时自出，瘦马不闻嘶。","夹毂人相叱，畏途剑独携。","由来贪访胜，到处漫留题。"]},{"t":"逍遥台","f":"五言律诗","c":["下马临高台，迢迢但草莱。","雀罗人事改，花发夕阳催。","废井围荒棘，残碑没古苔。","雍门昔有泪，千载思悠哉。"]},{"t":"安远除夕同韩孟郁甘存之守岁 其一","f":"五言律诗","c":["间关馀万里，迢递向京华。","政尔逢除夕，萧然寄酒家。","驿路临淮近，濉流绕郭斜。","悠悠此行迈，离思满天涯。"]},{"t":"安远除夕同韩孟郁甘存之守岁 其二","f":"五言律诗","c":["收盘随俗供，尊酒话平生。","湖海穷交泪，风尘羁旅情。","红颜芳岁换，白眼世途轻。","顾已牵缘役，劳劳何所营。"]},{"t":"登涿州城","f":"五言律诗","c":["危楼抗百雉，锁钥壮神州。","表里连三辅，襟喉属上游。","浮云边塞色，落日蓟门秋。","极目寒烟外，金河百折流。"]},{"t":"京邸立春","f":"五言律诗","c":["瑞雪霭芳辰，轻烟袅袅新。","青阳初应律，朱邸迥临春。","就日披荣早，迎风解冻匀。","自怜衰朽质，嘘咈藉洪钧。"]},{"t":"关门","f":"五言律诗","c":["关门壮国险，寒色迥沈沈。","肃卫千屯合，崇墉百雉阴。","黄尘飞古道，白日下幽岑。","一片陇头月，清霜拂藁砧。"]},{"t":"长城","f":"五言律诗","c":["长城迤万里，落日照黄榆。","饮马交河裂，挥戈塞草枯。","阴山连猎火，寒碛度飞刍。","何限纡金印，横行谁伏胡。"]},{"t":"寒食舟中","f":"五言律诗","c":["旷野四无邻，征途及暮春。","孤舟寒食雨，万里倦游人。","乡垄音书断，松楸涕望频。","一杯今日酒，谁酹故山坟。"]},{"t":"舟中书所见","f":"五言律诗","c":["杨花白于绵，榆策细如钱。","并触征人棹，春愁殊为牵。","冲波无日夜，归梦已经年。","何似忘机鸟，中流去渺然。"]},{"t":"对月","f":"五言律诗","c":["素月澹盈盈，凌波影乍生。","关山一以望，砧杵几家鸣。","箭浮衣荇乱，镜漾布帆轻。","谁解征人怨，萧条此夜情。"]},{"t":"对酒","f":"五言律诗","c":["微风起萍末，凉雨亦丝丝。","征路聊逢此，青尊且自怡。","孤云生掩映，独鸟弄涟漪。","最爱湖光满，轻舟尽日移。"]},{"t":"南池","f":"五言律诗","c":["树隐平桥合，花藏曲坞幽。","昔贤留有咏，兹地成千秋。","桂棹芙蓉渚，菱歌杜若洲。","南池风物好，春日羡遨游。"]},{"t":"经圯上","f":"五言律诗","c":["丈人逢孺子，挟策此相邀。","所以邳城下，今存坠履桥。","灵奇伤往事，契合想前朝。","濉水东流去，英雄恨未销。"]},{"t":"过汨罗吊三闾庙","f":"五言律诗","c":["昔闻楚子怨，今过汉江湄。","山鬼搴萝立，湘灵鼓瑟悲。","茝兰行客荐，时俗土人思。","古庙空山里，阴风闪翠旗。"]},{"t":"登雪浪阁","f":"五言律诗","c":["昔贤辞簪绂，栖遁此山间。","台馆浑如旧，云萝长自閒。","渚花明讲席，溪月照松关。","因悟区中累，倦游吾亦还。"]},{"t":"登九成台","f":"五言律诗","c":["曾闻韶乐奏，鸾凤此来仪。","仙驭杳然去，高台空在兹。","山容如削玉，泉响杂哀丝。","犹似聆馀韵，临风一解颐。"]},{"t":"同王虞石老师湛仲宾年丈经白沙里用区太史韵 其一","f":"五言律诗","c":["危楼恣攀陟，初月印澄潭。","野水明鸥席，松风清麈谈。","宦情悬蓟北，吾道亦天南。","它日留芳躅，因之想盍簪。"]},{"t":"同王虞石老师湛仲宾年丈经白沙里用区太史韵 其二","f":"五言律诗","c":["昔贤栖遁处，水月澹孤村。","绿筱微通径，青山不碍门。","临流一以眺，怀古意空存。","碧玉依然在，千秋共讨论。"]},{"t":"访张约之","f":"五言律诗","c":["曲径转萧森。","幽栖傍竹林。","閒云一榻静，芳草半池阴。","旧好携尊入，新诗抱膝吟。","因知仲蔚宅，未许世人寻。"]},{"t":"送黄达卿游西粤次其留别韵 其一","f":"五言律诗","c":["严风起木末，飒飒动高秋。","正值萧条候，况兼离别愁。","人烟苗子国，桂棹夜郎舟。","向晚频翘首，茫茫天际头。"]},{"t":"送黄达卿游西粤次其留别韵 其二","f":"五言律诗","c":["千山坏断岸，一水绕孤城。","送送河梁别，悠悠空复情。","野云正叆叇，江月淡微明。","定有浮湘赋，飞鸿一寄声。"]},{"t":"定帆亭晚眺和王老师 其一","f":"五言律诗","c":["定帆亭一望，海势净遥空。","落日含馀照，轻霜带薄丛。","烟霞玄圃外，鸡犬碧云中。","向晚缑笙过，飘飘欲驭风。"]},{"t":"定帆亭晚眺和王老师 其二","f":"五言律诗","c":["近山浮浅黛，远水淡微波。","地僻惟松菊，亭閒自薜萝。","桑间时引雉，池畔足笼鹅。","绝壁留题处，空惭和郢歌。"]},{"t":"访余彩震溪居留酌","f":"五言律诗","c":["秋水欲浮郭，维舟便到门。","村舂隔邻巷，书声在竹园。","花间时引步，雨里一开尊。","尽日无人见，焚香展话言。"]},{"t":"彩震碧浪居留题","f":"五言律诗","c":["耽幽此结斋，一径草深霾。","树阴疑压阁，日影不移阶。","竹密成行次，篱蔓没安排。","坐来清露重，花气逗人怀。"]},{"t":"喜高公先过访","f":"五言律诗","c":["相见浑如旧，相怜鬓已非。","壮游馀侠骨，客路换征衣。","野径黄花满，秋山紫蕨肥。","莫嫌生事薄，到处可忘归。"]},{"t":"苦雨柬公先","f":"五言律诗","c":["黄叶飞林外，萧条但闭门。","怀人隔秋雨，相过待朝暾。","水市多鱼馔，比邻是酒村。","盈盈望不极，期共采芳荪。"]},{"t":"送吴彦先扶其兄非熊旅榇还新安 其一","f":"五言律诗","c":["归程不可问，泛泛度河津。","芳草天边路，游魂梦里人。","还惊乡土异，偏觉客怀新。","况复秋风别，空江满白蘋。"]},{"t":"送吴彦先扶其兄非熊旅榇还新安 其二","f":"五言律诗","c":["严程无日夜，幽赏每多违。","鸿雁雨中断，交游岭外稀。","乡心容易折，客计转怜非。","生死虽殊路，云山一处归。"]},{"t":"送吴非熊旅榇还新安 其一","f":"五言律诗","c":["死别已凄恻，送君重可嗟。","空山悬客梦，孤榇独还家。","乡树吴门近，云峰岭路斜。","所嗟魂未定，渺渺越天涯。"]},{"t":"送吴非熊旅榇还新安 其二","f":"五言律诗","c":["独怜芳草遍，之子未宁居。","有弟能收骨，孤儿可付书。","囊因为客尽，句尚苦吟馀。","借问同游辈，谁来策素车。"]},{"t":"过舍弟园馆","f":"五言律诗","c":["云萝如有恋，入径莽牵衣。","献赋不能遇，郊园空掩扉。","门惊罗雀静，燕识主人归。","犹忆池塘梦，残灯对下帷。"]},{"t":"讯何文起","f":"五言律诗","c":["秋风馀几日，亭院定萧閒。","竹径缘谁扫，花扃聊下关。","溪声来一派，峰色净双鬟。","却忆同栖处，余今倦出山。"]},{"t":"送冯县尉解组归","f":"五言律诗","c":["凉飙起木末，江驿动微程。","但解林峦趣，宁知簪绂荣。","云连千嶂暝，风送一帆轻。","不尽江门水，难销此别情。"]},{"t":"对落叶","f":"五言律诗","c":["落叶扫还积，霜林影乍空。","无情偏逐水，有恨但随风。","蝉翳移深树，莺归失旧丛。","可怜萧索候，况是病愁中。"]},{"t":"见白发","f":"五言律诗","c":["衰鬓忽萧飒，霜毫添几茎。","镜前看不见，梳后拔还生。","乍觉游丝绕，还同落絮轻。","凭阑翻自哂，嘿嘿此时情。"]},{"t":"夜行口占示区季誉甘存之","f":"五言律诗","c":["轮蹄交杂遝，夜语不分明。","望火时投店，听鸡夜度城。","堠人严逻柝，驿使抗前旌。","夹毂还相问，乡关第几程。"]},{"t":"新宁道中 其一","f":"五言律诗","c":["荒城才斗大，比屋似星疏。","夜市多蒲席，山猺半穴居。","民贫惟种豆，地瘠不宜蔬。","客况殊无味，悠悠念故庐。"]},{"t":"新宁道中 其二","f":"五言律诗","c":["孤馆不遑寐，迢迢刻漏长。","留灯共客话，催仆检行装。","城角犹残月，河堤半晓霜。","归心正悽恻，欲济又无航。"]},{"t":"新宁道中 其三","f":"五言律诗","c":["行行踰峻坂，望望是那西。","古道无人迹，荒原尽兽蹄。","瓦窑依壑稳，茆屋傍林低。","一阵冲寒过，长风送鸟啼。"]},{"t":"新宁道中 其四","f":"五言律诗","c":["独行三十里，草树密冥濛。","买食投荒店，迷途问小童。","天遥山点翠，霜重叶垂红。","怪石蹲崖立，疑穿虎豹丛。"]},{"t":"新宁道中 其五","f":"五言律诗","c":["翻疑川路尽，回合见江滨。","吹角牛归垄，鸣铎渡唤人。","山光晴冉冉，潭照碧粼粼。","且复随流去，征途休问津。"]},{"t":"新宁道中 其六","f":"五言律诗","c":["维舟沙渚静，霜落见潮痕。","雀噪寒枝聚，人争水渡喧。","畏途藏姓字，混俗变乡言。","今夜浔洋宿，计程近故园。"]},{"t":"同刘平子晚坐溪林","f":"五言律诗","c":["园庐秋方晏，芳树晚条稀。","寒灯听雨罢，淡月出林微。","暝色乍延浦，河流欲漫矶。","如何此时赏，幽抱共依依。"]},{"t":"答文起病中见寄兼订西林之约","f":"五言律诗","c":["秋色今如许，秋期閒未閒。","囊中时贮药，梦里亦寻山。","晓树迎霜早，寒潮带月还。","对景堪延赏，无然静掩关。"]},{"t":"晨起同平子步赊月台望西林因寄怀文起兼书近况","f":"五言律诗","c":["怀君一长望，云木共依依。","病况知无恙，西林应到稀。","秋色遥连水，晨光澹在衣。","正惬芳园赏，中林漫掩扉。"]},{"t":"送区彦斯返馆长沙","f":"五言律诗","c":["津树澹霏霏，兰桡荡晓晖。","空江还独往，投馆未言归。","别路萦芳草，閒房傍翠微。","同衿怜远隔，客里授寒衣。"]},{"t":"送区茂对之五羊","f":"五言律诗","c":["昨日同尊酒，今朝南浦行。","还随一雁去，又度五羊城。","霜岸秋容澹，江流晓气清。","所思无远近，相别总含情。"]},{"t":"为区君玉戏作悼亡诗","f":"五言律诗","c":["罗帏香梦断，夜被不成温。","欲识怀中恨，还看枕上痕。","酣花怜笑影，痴月想奔魂。","纵有新承宠，难忘是旧恩。"]},{"t":"同诸子东浦放舟转入西林","f":"五言律诗","c":["隔浦望不远，登舟行转深。","谁云剩溪水，有路通西林。","山馆遮红叶，人家住绿阴。","閒时亦一到，那解此幽寻。"]},{"t":"重过西林有述","f":"五言律诗","c":["刺眼皆非旧，多时余不来。","浚池穿石脉，移树补墙隈。","虽尔除繁蔓，犹然费品裁。","松阴閒共课，山色照深杯。"]},{"t":"区君玉同访西林还宿中林","f":"五言律诗","c":["买山余未得，溪上且閒居。","趁此登临兴，还来共息庐。","虚牖凉生枕，残灯夜伴书。","相留殊草草，相别意何如。"]},{"t":"潮生","f":"五言律诗","c":["渺渺来何处，悠悠看渐盈。","常随宵月长，偏傍晓霜清。","澶漫原无极，迢遥似有情。","物华向此度，空水自长生。"]},{"t":"浮波片叶石","f":"五言律诗","c":["本是顽固质，何来波面浮。","已怜湛似水，难道幻如沤。","江枫飘一片，断梗截中流。","物情皆有托，泛泛尔何求。"]},{"t":"钟声","f":"五言律诗","c":["流云递幽响，隐隐度层岑。","断续随风绪，微茫带暝阴。","忽惊来枕畔，旋复入空林。","政尔息尘想，遥闻亦警心。"]},{"t":"初出关留宿玄帝观与亲友言别","f":"五言律诗","c":["青郊带暝色，官路少人行。","雨里停车骑，尊前别友生。","一灯明古院，五漏隔严城。","暂此还栖宿，聊宽远道情。"]},{"t":"湴湖驿","f":"五言律诗","c":["迢迢度陇阪，仆马不辞疲。","底事忙如此，征途未有期。","驿垣经雨塌，村灶傍岩炊。","去去无穷已，离怀方在兹。"]},{"t":"夜投官庄","f":"五言律诗","c":["逶迤百里道，登顿几千重。","流水咽危石，阴风啸古松。","晓霜人度碛，暝路仆迷踪。","夜宿投村店，沾襟露气浓。"]},{"t":"望仙台","f":"五言律诗","c":["停桡傍水隈，一上望仙台。","磴道缘溪尽，庵房凿岭开。","即看花散处，疑有鸟衔来。","灵境居然别，鸾笙几度回。"]},{"t":"舟中卧病","f":"五言律诗","c":["世味阅来淡，乡心殊未恬。","扁舟同病载，新水共愁淹。","敲雪添棉袄，遮风下布帘。","归期不敢问，暗把梦来占。"]},{"t":"苦雨","f":"五言律诗","c":["终朝恒苦雨，山径阻招寻。","作客殊无味，逢人难语心。","晓风初出谷，寒叶尚馀阴。","可似羁栖鸟，春来思旧林。"]},{"t":"别舍弟","f":"五言律诗","c":["客程一分手，征雁随南还。","折柳临前浦，听莺怀故山。","清时谁不羡，因病我投閒。","旧业东皋下，残阳深闭关。"]},{"t":"归棹 其一","f":"五言律诗","c":["偶然兴尽返，如愿何曾违。","京路人如织，家山吾独归。","病多身念重，阅久世情微。","稍觉南中煖，春来渐减衣。"]},{"t":"归棹 其二","f":"五言律诗","c":["来路悔已远，算程归尚迟。","乡心篷底月，客况镜中丝。","问我还山事，东波潮涨时。","夕阳深闭巷，去扫旧茆茨。"]},{"t":"江中书事","f":"五言律诗","c":["草色绿于染，江山春雨馀。","客程三月别，亲旧隔年书。","麦垄驱黄犊，沙溪打白鱼。","随缘生事足，吾意亦怀居。"]},{"t":"金华山小庵","f":"五言律诗","c":["庵在半山处，山腰云数层。","上方无觅路，古壁有悬灯。","积霭沈崖栈，消冰见屋棱。","往来舟上客，试问几人登。"]},{"t":"閒步","f":"五言律诗","c":["水宿殊淹滞，閒寻野寺行。","寒山隔岸小，残雪落林轻。","羃䍥连江色，迢遥远俗情。","无僧可共语，寂寂一灯明。"]},{"t":"储潭庙","f":"五言律诗","c":["到此滩声息，平沙一镜涵。","人烟过白涧，江庙赛储潭。","映日帆移岸，摇风火漾龛。","征途殊未歇，催棹又投南。"]},{"t":"晓度梅关","f":"五言律诗","c":["晓霜犹湿径，驱马望山城。","乡月临关近，归云傍岭生。","人今辞北地，雁始背南征。","去住虽殊致，同为羁旅情。"]},{"t":"撷芳亭夜话","f":"五言律诗","c":["闻亭秋气早，芳树晚留飔。","爱此槐阴月，清光来入池。","微吟穿竹径，对语隔花枝。","渐觉明河没，城头晓漏迟。"]},{"t":"送容叔文读书广海","f":"五言律诗","c":["春早远行迈，悠悠剑独携。","山程过石岭，水渡问那西。","风景堪描画，烟花入品题。","孤村读书处，古木有猿啼。"]},{"t":"送黄净友游洞庭","f":"五言律诗","c":["君山如抹黛，湖水贴天青。","一望无边际，孤帆入窅冥。","临风怀帝子，挟瑟访湘灵。","为问空潭月，渔歌谁共听。"]},{"t":"赠端公禅师","f":"五言律诗","c":["金篦导苦海，玉镜照迷方。","煮石临阶月，翻经续鼎香。","众生资慧命，大地尽慈航。","不必知名姓，前身是药王。"]},{"t":"送方士","f":"五言律诗","c":["凄凄芳草遍，之子动征轮。","渡海施来药，书符解活人。","怀中三尺剑，囊里一壶春。","收拾烟霞去，归装莫讶贫。"]},{"t":"送何文起赴廷试便道省觐","f":"五言律诗","c":["桃花新水涨，之子事长征。","玄感千秋遇，青云此日程。","抠衣淮甸月，跃马蓟门城。","正及皇都丽，春风听早莺。"]},{"t":"送傅子彝还金陵","f":"五言律诗","c":["所嗟行役远，念子去如违。","度岭愁闻雁，经秋未授衣。","家山淮甸杳，乡月大江微。","遥忆维舟处，春流满燕矶。"]},{"t":"旅馆书怀 其一","f":"五言律诗","c":["城市休相问，闭门事事疏。","向人求药草，课仆种盆鱼。","补壁悬新画，移床顿古书。","閒庭刚洒扫，纤月到前除。"]},{"t":"旅馆书怀 其二","f":"五言律诗","c":["恰似閒荒院，松门闭寂寥。","催斋常过午，听雨每连朝。","扫地延僧话，裁书谢客招。","茆檐忻日出，向暖护兰苗。"]},{"t":"旅馆书怀 其三","f":"五言律诗","c":["住处当官路，转过门巷斜。","借经来静院，贷米向邻家。","病眼长亲药，衰脾尚癖茶。","偶逢方外士，劝我炼黄芽。"]},{"t":"旅馆书怀 其四","f":"五言律诗","c":["病来慵约束，舒散快心灵。","客到频题字，童关渐解经。","小池过雨碧，砌草闭门青。","为惜春朝去，移花插胆瓶。"]},{"t":"旅馆书怀 其五","f":"五言律诗","c":["铺设閒供具，常时净扫房。","竹间安茗灶，花下置藜床。","学演戏禽法，多传却老方。","昼长无事事，小步绕巡廊。"]},{"t":"赠无树上人 其一","f":"五言律诗","c":["住山凡几腊，渡海忽经年。","布衲冲云破，芒难踏岭穿。","拈诗呈了义，不语悟单传。","我亦同飘梗，茶香暂结缘。"]},{"t":"赠无树上人 其二","f":"五言律诗","c":["弥天江路迥，一锡向南飞。","幻影原无住，逢山可当归。","行随湘浦雁，身老粤中薇。","相遇溪堂上，香云满衲衣。"]},{"t":"小年夕同杨亦琳胡伯连对酌分赋明日立春","f":"五言律诗","c":["扁舟徒泛泛，野泊傍江渔。","客况惊残腊，流年逼小除。","消愁今夜酒，偿债几行书。","独有乡园梦，先春到敝庐。"]},{"t":"上萧拙修太史","f":"五言律诗","c":["秋杪离乡井，经春阻白门。","风萍嗟浪迹，感激为酬恩。","一顾时名重，千秋古谊存。","尊前纡硕画，借箸向谁论。"]},{"t":"吴彦先过访旅舍留宿","f":"五言律诗","c":["岭上一为别，那堪十载馀。","难将心曲事，去觅往来书。","以我伤萍梗，逢君问起居。","相留惟脱粟，休叹食无鱼。"]},{"t":"访邱宗上人留宿","f":"五言律诗","c":["逢师寂无语，宴坐一炉香。","空水摇山户，閒云宿石床。","松因经腊古，草不待时芳。","向晚檐鸦息，闻钟未下堂。"]},{"t":"舟次同杨应先谭敬质玩月","f":"五言律诗","c":["乡心同此地，旅食算流年。","几度天边月，虚从望里圆。","凉风低烛影，清露湿茶烟。","为爱连宵话，推篷未忍眠。"]},{"t":"余自金陵与西粤文程可杨不群同舟屈指月馀念抵庾关行将告别临风对酒聊赠短章","f":"五言律诗","c":["孤棹自京华，迢迢水一涯。","他乡同对酒，旅梦未还家。","庾岭联归骑，淳江独泛槎。","时危各努力，离索未应嗟。"]},{"t":"除夕前二日送李解一还鹿门","f":"五言律诗","c":["晏岁促归程，兰桡趁晓行。","客心随候雁，乡梦记啼莺。","冻雪融坭湿，残梅点袂轻。","暂时还此别，相望隔年情。"]},{"t":"羽甫家兄同容知微花下弹琴","f":"五言律诗","c":["幽人款竹扉，相对理清徽。","夕霭下庭薄，轻风生袷衣。","宛宛指间语，寥寥思际微。","乍觉春寒重，流泉花外飞。"]},{"t":"同陈叔和过知微斋中听雨","f":"五言律诗","c":["云光与草色，清影碧参差。","夜榻留灯处，閒窗听雨时。","炉香飘茗盏，瓶露醒花枝。","忽作沈沈溜，馀流迸入池。"]},{"t":"苦雨柬何文起 其一","f":"五言律诗","c":["春愁不可奈，苦雨又连朝。","架沁琴书湿，庭添几案潮。","芳游能几许，索处更难销。","为问花安否，相将护短条。"]},{"t":"苦雨柬何文起 其二","f":"五言律诗","c":["雨湿燕坭重，花飞故傍帘。","宿云痴欲堕，砌草嫩成淹。","倦觉茶勋薄，寒欺酒力严。","遥峰如可数，霁色露茆檐。"]},{"t":"晚过容知微园馆","f":"五言律诗","c":["庭皋望空阔，山霭晚烟微。","犬护篱根静，蜂抟花粉归。","暖风来燕雀，香露浥蔷薇。","亦有中林客，乘閒款夕扉。"]},{"t":"过羽甫家兄池馆留赠 其一","f":"五言律诗","c":["芳树接池阴，幽斋依小林。","花标閒逸韵，松作淡虚音。","过雨忙移药，拈香静谱琴。","离居犹混俗，自是少尘心。"]},{"t":"过羽甫家兄池馆留赠 其二","f":"五言律诗","c":["深巷市喧隔，虚亭长寂寥。","穿阶留绿笋，级树缀红椒。","童子收松粉，山樵送药苗。","诗筒兼酒盏，忙过百花朝。"]},{"t":"题陈叔和馆","f":"五言律诗","c":["一区藏窈窕，片石斲云根。","移树高于屋，编篱小作垣。","云应供洒翰，鸟亦课閒言。","不是琴诗侣，夜深谁打门。"]},{"t":"赠容瑞瑜","f":"五言律诗","c":["名山终欲往，昏嫁暂随缘。","候火调丹鼎，烹茶借蒳烟。","閒心花石古，胜具木瓢坚。","时有耽吟癖，孤峰顶上眠。"]},{"t":"雨怀知微","f":"五言律诗","c":["蛙吠水声急，陂塘春涨浮。","草香微有韵，花淡却如秋。","此际难成寐，思君独上楼。","还听蕉叶里，疑入玉琴流。"]},{"t":"过放生社问高公先病","f":"五言律诗","c":["旅馆思难任。","投閒依道林。","青灯孤客梦，白社旧游心。","斋钵分香积，閒阶狎施禽。","毗耶虽示疾，一室散花深。"]},{"t":"苦雨再柬羽甫兄并书所感","f":"五言律诗","c":["雨歇还复注，园庐恒暝阴。","空阶行药遍，芳草闭门深。","计口权留鹤，算囊欲卖琴。","生涯随分过，不羡披裘金。"]},{"t":"羽甫兄嘉荐侄过中林夜话","f":"五言律诗","c":["衡宇晚萧寂，客来破暝烟。","灯影竹间出，屐声花外传。","诗坛新旧局，世态雨晴天。","与尔閒商略，悠悠夜似年。"]},{"t":"听雨","f":"五言律诗","c":["灯火隔篱落，溪桥人夜渔。","树随波影动，萤傍草烟疏。","螟阁报更后，官衙歇鼓初。","此时惟静嘿，听雨掩残书。"]},{"t":"过东皋访区茂对","f":"五言律诗","c":["竹院偕僧住，萧清长道心。","花同禅味淡，草绕定坛深。","斋阁听钟饭，閒廊接偈吟。","书声萝屋里，和磬出疏林。"]},{"t":"赋梅影 其一","f":"五言律诗","c":["半壁疑见画，虚廊月上时。","轻霜含远韵，空水澹寒姿。","祇自沈吟久，还堪折赠谁。","绕檐凡几匝，宿鸟误投枝。"]},{"t":"赋梅影 其二","f":"五言律诗","c":["浮影浑无定，移梢渐过墙。","月残微带晕，风细稍闻香。","野寺斜桥外，孤村浅水旁。","相看如旧识，伫立听更长。"]},{"t":"卢一清过访溪上","f":"五言律诗","c":["旧业在金阊，行踪遍五羊。","游兼春草发，梦与海云长。","新涨菰蒲岸，轻帆书画航。","逢君今夕雨，疑是对潇湘。"]},{"t":"得韩孟郁书知有仲弟之变寄此","f":"五言律诗","c":["得尔还家信，风霜知饱经。","长途怜老马，归梦忆原鸰。","客里囊先尽，愁边酒易酲。","伤心池畔草，不似往年青。"]},{"t":"留别卢一清次陈宪副韵","f":"五言律诗","c":["五月新潮涨，河堤处处通。","远烟含岛碧，残照点帆红。","把酒同听雨，停桡尚候风。","萍踪聊复尔，休叹路西东。"]},{"t":"同诸子赊月台玩月因怀知微","f":"五言律诗","c":["同舟嗟靡及，复此念离群。","今夜高台月，随波流照君。","空阶疑积水，花影乱苔文。","目极江门树，依依隔暮云。"]},{"t":"将之五羊羽甫家兄携酒同诸子话别","f":"五言律诗","c":["相过频如此，相离暂亦难。","兰尊初汎绿，荔浦正垂丹。","孤月悬乡梦，清江破晓寒。","幽怀不可写，明发路漫漫。"]},{"t":"同卢一清黄逢永伍国开集陈集生太史斐园咏白鸭得轻字","f":"五言律诗","c":["澄沙照愈洁，汎汎雪衣明。","带月宿无影，随波浮共轻。","花阴时逐侣，浴罢自呼名。","却谢朱阑斗，来游玉沼清。"]},{"t":"过韩孟郁清居 其一","f":"五言律诗","c":["清幽谁得似，小筑仅如拳。","树古藤交缀，篱疏竹任穿。","室馀虚作白，亭有草成玄。","转觉炎蒸薄，深林咽早蝉。"]},{"t":"过韩孟郁清居 其二","f":"五言律诗","c":["山光纷入户，草色连青郊。","揆地刚盈笏，穿池只一坳。","纸窗萤借焰，阶树鸟同巢。","且喜茆堂近，荆扉带月敲。"]},{"t":"送吴彦先还金陵兼讯冒伯麟林子邱林茂之洪仲韦诸子","f":"五言律诗","c":["轻装频往返，复此暂淹留。","旅馆閒销夏，归期尚及秋。","因君倾别泪，寄语问同游。","目极无来雁，空江日夜流。"]},{"t":"中元节过长寿庵感怀","f":"五言律诗","c":["捣衣惊此月，乡梦起秋砧。","况值盂兰节，谁无寸草心。","金钱资佛曾，香钵趁禅林。","复想家堂荐，遥遥泪满襟。"]},{"t":"罗浮仙籍为潘子仙题","f":"五言律诗","c":["恰有真仙骨，常参四百君。","拾得丹灶药，私窥玉笈文。","松影摇山月，天风吹海云。","弄笛铁桥畔，羽衣凌紫氛。"]},{"t":"赠张白一道人","f":"五言律诗","c":["颇学梅公隐，都忘尘市心。","白云随杖远，红叶住山深。","放鹤夜归洞，种桃春满林。","祇应松下月，长照北堂阴。"]},{"t":"送梁起先游飞来兼讯高斗仲朱惟四曾文卿","f":"五言律诗","c":["猿声啼不尽，霜叶点行舟。","地有飞泉胜，山传古寺留。","玄心寄独往，幻迹恣冥搜。","倘遇清音侣，酣歌月满楼。"]},{"t":"慰羽甫家兄失磬拈得四支韵","f":"五言律诗","c":["清斋閒寂寂，韵友亦何之。","去住同为幻，声闻此暂离。","转经残月后，对客罢谈时。","翻觉无长物，沈冥或在兹。"]},{"t":"羽甫兄得还旧磬赋此志喜","f":"五言律诗","c":["孤磬忽云远，迢迢抱韵归。","摩挲今再觌，清寂幸相依。","灯影摇松月，窗光启曙晖。","主人心似水，来去本忘机。"]},{"t":"送匡云上人归庐山","f":"五言律诗","c":["匡山禅诵处，三叠流泉飞。","花雨飘空梵，晨钟滴翠微。","一筇今独往，五岭送将归。","休说还山好，孤云无是非。"]},{"t":"春日过访陈来献","f":"五言律诗","c":["林影乍回薄，清晖照槿园。","花迎客共笑，春醉鸟无喧。","挥麈参微论，呼童检韵言。","玄心谁独赏，吾兴已腾鶱。"]},{"t":"送周时府入计","f":"五言律诗","c":["夫子中朝彦，风流落下情。","一琴流水远，双舄带星悬。","马踏金门雪，花含玉露烟。","怀芹何以献，天子在甘泉。"]},{"t":"赋得秋荷","f":"五言律诗","c":["盆荷秋欲尽，偏放一枝奇。","皎洁凌霜色，娉婷弄月姿。","轻飔摇影动，香露泫珠垂。","向夕钩帘坐，应添静夜思。"]},{"t":"送容九闳游韶阳","f":"五言律诗","c":["对酒不能别，相看泪欲挥。","河梁一分手，前路换春衣。","柳色经霜嫩，梨花带雨飞。","倘逢山水胜，休令赏心违。"]},{"t":"寄讯曲江梁国桢","f":"五言律诗","c":["君才真扩落，空自带南冠。","梁狱珠光暗，丰城斗气寒。","黄金散欲尽，白眼醉相看。","勿讶虞罗窄，鸿飞厉羽翰。"]},{"t":"鬼灯笼","f":"五言律诗","c":["质与凡根植，名因俗谚传。","绿幕看疑掩，丹心寂不然。","似带青燐色，微含宿草烟。","无心随佛日，故傍法轮悬。"]},{"t":"别邓黄二生","f":"五言律诗","c":["一尊临水曲，露白蒹葭秋。","扬舲不可住，之子去悠悠。","蝉声在乔木，雁影度江楼。","含情各分手，离思满芳洲。"]},{"t":"彭峨昆过访话别","f":"五言律诗","c":["北风入庭户，萧索揽貂裘。","以我栖迟志，逢君不榻留。","江枫黄叶渡，烟舸白蘋洲。","明发凤城去，茫茫不可求。"]},{"t":"长门怨","f":"五言律诗","c":["妾命真成薄，君恩未是疏。","玉楼闻玉漏，金殿度金舆。","长乐歌钟歇，长门夜月虚。","愁颜无复少，传语谢相如。"]},{"t":"巫山高","f":"五言律诗","c":["云雨暮仍朝。","阳台入望遥。","时时横翠馆，往往堕金翘。","乍拂霞裾动，还承羽盖飘。","凄凉千古梦，无语对空寥。"]},{"t":"爱妾换马","f":"五言律诗","c":["祇分辞新宠，宁知念敝帷。","妆台封玉镜，仙苑登金羁。","孤泪双双落，长蹄宛宛垂。","若为丽姬怨，端谢塞公悲。"]},{"t":"明月光","f":"五言律诗","c":["明月一何光，閒愁偏共长。","可怜千里目，犹滞两江乡。","朔雁冲残雪，寒砧拂夜霜。","倚栏空袖手，挥泪湿流黄。"]},{"t":"远别离","f":"五言律诗","c":["生长深闺里，何曾解别离。","可怜今日去，况值春风时。","弱柳维行舫，鸣莺恋旧枝。","长亭千万里，相送日迟迟。"]},{"t":"新婚别","f":"五言律诗","c":["由来生别苦，不似新婚时。","踏月频惊影，临妆懒画眉。","带自同心结，琴调绝命词。","愁心看鸿雁，无字寄相思。"]},{"t":"将别息庐夜坐志感","f":"五言律诗","c":["群喧归一寂，人鸟亦交冥。","暗牖能来月，澄池可数星。","难将今夜意，去问草堂灵。","飒飒疏槐下，风吹几叶青。"]},{"t":"装简","f":"五言律诗","c":["一囊空复尔，客计若为欢。","久矣谋生浅，于今出户难。","疏交谁可托，冷面竟羞干。","且置休相问，回灯语夜阑。"]},{"t":"不寐","f":"五言律诗","c":["微尚将无隔，兴居百念回。","口和心自语，形与影相猜。","圣世谁甘隐，逢时谅不才。","中宵缘底事，起步独徘徊。"]},{"t":"社中琴集送吴生还金陵余亦将北上","f":"五言律诗","c":["别绪人方嘿，离弦泛泛长。","君应携韵去，余亦束琴装。","荷渚擎云翠，枫窗点叶黄。","泉声弥恋恋，似惜马蹄忙。"]},{"t":"游飞来寺题振衣亭","f":"五言律诗","c":["凉风生两腋，步步陟危亭。","石似兼泉坠，云疑恋壑停。","虚光涵远白，零露沁空青。","几度忙游此，难招帝子灵。"]},{"t":"过白下投赠李伯开","f":"五言律诗","c":["浮踪何所住，曾否赋归来。","珠海逢君处，兰桡此际开。","残霜犹酿橘，新雪欲衔梅。","今夜澄江上，离怀向月裁。"]},{"t":"舟次螺江始闻萧伯玉大行奉使还里不及造访怅然有寄","f":"五言律诗","c":["千里劳书问，经途窅不闻。","谁云衣带水，能隔往来云。","清月犹悬梦，皇华独照君。","倚桡频欲寄，沙雁怅离群。"]},{"t":"秉烛赠所欢","f":"五言律诗","c":["萧膏和蜡炬，送喜入欢房。","敛泪当明镜，扬葩助艳妆。","轻摇翠羽幕，半浸象牙床。","好把冰罗护，留欢待玉郎。"]},{"t":"同杨应先朱瞻御梁喈林集程散木中秘园亭用瞻御韵","f":"五言律诗","c":["冥濛香径滑，澹雨洒林扃。","侵晓方趋省，留宾暂憩亭。","花明仙掌露，草带凤池青。","胜念堪留记，浮踪几聚萍。"]},{"t":"过御空上人兰若留题","f":"五言律诗","c":["新草上阶绿，禅房花木妍。","十年重到此，一榻尚依然。","鸟语过林滑，经声绕竹圆。","却怜尘网系，归棹寺门前。"]},{"t":"将北征上侍御老师 其一","f":"五言律诗","c":["寒灯灿幽馆，永夜对沈沈。","政有长途役，难忘迟暮心。","宵钟清远寺，凉露澹疏林。","惜别徒劳念，因风寄短吟。"]},{"t":"将北征上侍御老师 其二","f":"五言律诗","c":["自怜甘懒拙，飒沓误儒冠。","短剑空存铗，敝裘宁耐寒。","戒途犹渺渺，顾径且盘盘。","即未离乡井，已怀行路难。"]},{"t":"将北征上侍御老师 其三","f":"五言律诗","c":["行藏俱莫问，难报是君亲。","风木馀双泪，驱驰剩一身。","半生焚砚债，未老倦游人。","时事方蒿目，聊容招隐沦。"]},{"t":"将北征上侍御老师 其四","f":"五言律诗","c":["尘劳真梦梦，四十未知非。","觉路瞻犹远，空门暂可依。","戒香莲漏永，清梵宝林微。","胜地此为别，长谣始愿违。"]},{"t":"将北征上侍御老师 其五","f":"五言律诗","c":["严程八千里，北极是京华。","藿食犹怀阙，林栖岂恋家。","卖琴充橐俭，策蹇问途赊。","赖有连枝伴，休怜天一涯。"]},{"t":"江上","f":"五言律诗","c":["空江望不极，长天净碧漪。","客心聊共远，江路浩难期。","霜叶纷辞树，流莺未上枝。","及早还乡井，芳菲正此时。"]},{"t":"过十八滩","f":"五言律诗","c":["沙堰船难进，前滩浪复高。","客心殊已倦，舟子亦云劳。","阴碛走万马，冲风度一毛。","往来不及瞬，慎勿弄轻篙。"]},{"t":"道士山房","f":"五言律诗","c":["结庐在山顶，高高傍斗坛。","夜来风飘瓦，吹雪满霞冠。","汲泉留洗药，养火为烧丹。","怕有俗人溷，书符贴板门。"]},{"t":"谭与人过访舟次因留小酌遂拉同舟","f":"五言律诗","c":["以我乡愁剧，逢君旅思新。","同为羁病客，堪作并舟人。","草碧故山路，梅残陇首春。","孤蓬随飘往，尊酒话情亲。"]},{"t":"哭吴非熊","f":"五言律诗","c":["徒云归是客，难道客如归。","易篑僮先散，招魂谁可依。","来惊春浪阔，去及柳条稀。","迢递黄山路，程程入翠微。"]},{"t":"赠逆旅主人","f":"五言律诗","c":["主人忘世味，雅志在林园。","如何市朝隐，不避车马喧。","相逢具鸡黍，佐茗儗清言。","挥手自兹去，前途风雪繁。"]},{"t":"西江晚泛因怀邓梁二山人","f":"五言律诗","c":["西江何清浅，回合卓冈岑。","虽自非吾土，依然生远心。","予徒牵物役，尔辈足山林。","倘许从初服，薜萝春正深。"]},{"t":"送陈冶父还清远","f":"五言律诗","c":["冻雪何霏霏，严寒透衲衣。","故山频入梦，残腊始言归。","末路交情见，长年游道非。","携将春草色，还以献慈闱。"]},{"t":"望圭峰寄道人","f":"五言律诗","c":["乱壑在深翠，禅关不上扃。","衣裁云叶白，座藉草盘青。","施食鸟无怖，驮经虎有灵。","更疑说法处，或者老猿听。"]},{"t":"秋夜答梁天放","f":"五言律诗","c":["夜窗谁共语，清对短檐松。","月浸一池水，风飘何处钟。","寒知天边雁，秋入壁间蛩。","两地俱摇落，怀君隔几重。"]},{"t":"得南海刘方瀛老师书辄赋一律奉答","f":"五言律诗","c":["珠江望不极，晴色霭氤氲。","万里看明月，相思隔暮云。","花间琴自远，桑下雉为群。","想像弦歌处，微茫一水分。"]},{"t":"别李干甫","f":"五言律诗","c":["嗟君不得意，湖海事遨游。","夜雨双龙剑，寒江一叶舟。","澹云孤雁杳，芳树晚风柔。","别后看明月，相思漫倚楼。"]},{"t":"席间赠黄达卿","f":"五言律诗","c":["风流谁藉甚，闽海有狂生。","白眼逢人态，黄金结客情。","诗篇行处满，世事酒中轻。","若问赢输理，相看一局枰。"]},{"t":"秋夕叶而章过饮小园有赠","f":"五言律诗","c":["槐竹互参差，窥林得月迟。","閒庭青霭合，荒径碧苔滋。","浊酒汎篱菊，清霜摘野葵。","相逢无约束，潦倒是襟期。"]},{"t":"过庐陵谒萧拙修太史","f":"五言律诗","c":["暂尔还初服，鸿冥亦可仪。","登堂今日再，倾盖昔年知。","天岂虚麟凤，人其閟鼎彝。","赐还当此际，行矣赴昌期。"]},{"t":"访王君奉于德兴寺留题","f":"五言律诗","c":["虽游京国遍，而独爱禅居。","柿叶留僧偈，莲花借佛炉。","空床储腊酒，高庋顿奇书。","客况无聊赖，思君便策驴。"]},{"t":"晓行河间道中","f":"五言律诗","c":["晓行三十里，白雾尚冥冥。","沾洒俄成霰，微茫不辨星。","马寒嘶欲止，车滑去难停。","隐约见篱舍，疏烟出过坰。"]},{"t":"别广文邓先生","f":"五言律诗","c":["绛帐横经日，黄云接袂时。","春光如有待，花雨本无私。","桃李沾前润，风云想后期。","重游惜分手，南陌柳丝丝。"]},{"t":"区彦斯茂对君玉携酒过中林访平子","f":"五言律诗","c":["故人载酒至，石榻一开樽。","访友来蒿径，课吟傍竹垣。","庭兰芳气合，阶树野禽喧。","值此秋光好，乘閒共晤言。"]},{"t":"同平子君玉玩月","f":"五言律诗","c":["中秋悬雨夕，月色可能同。","素魄微亏晕，流光澹写空。","连溪蘸一碧，鉴叶皎千丛。","清景谁延赏，高台习习风。"]},{"t":"阶前树","f":"五言律诗","c":["嘉树发芳蕤。","亭亭复在兹。","年深霜藓剥，根古石文移。","寒影半栖壁，凉蟾来挂枝。","谁人解幽赏，只是爱华滋。"]},{"t":"喜邢耿乃林学仲同舟赋赠","f":"五言律诗","c":["家乡南极尽，去路与天长。","各自携孤剑，相将上野航。","扬舲遵水次，欣月挹山光。","且喜偕心赏，计程未觉忙。"]},{"t":"夜泊梁口","f":"五言律诗","c":["寒沙一片白，澹月带霜痕。","舟子乍停桨，人家半掩门。","疏烟衔落木，微火辨遥村。","暂觉离乡远，江干劳梦魂。"]},{"t":"过明因寺看如来成道碑","f":"五言律诗","c":["已讶鱼知乐，因寻僧伴閒。","问途经水次，礼磬入云间。","到此偶成趣，逾时忘却还。","如来有遗记，胜会想灵山。"]},{"t":"浴象 其一","f":"五言律诗","c":["译贡来何域，香刍饲一栏。","班行随肃卫，厮养属酋官。","剪拂添光采，梳爬绝垢瘢。","渡河闻内典，今见戏清澜。"]},{"t":"浴象 其二","f":"五言律诗","c":["羲驭当炎候，天閒放浴晨。","魁梧看若辈，豢养几经春。","骑出人争拥，调来性已驯。","应沾新雨露，天子祷郊频。"]},{"t":"浴象 其三","f":"五言律诗","c":["且自辞天仗，群趋向禁壕。","乍泅波欲黑，对立岸难高。","鹓鹭陪曾惯，熊罴气并豪。","年年当此际，湔刷圉人劳。"]},{"t":"浴象 其四","f":"五言律诗","c":["出入随宫禁，烟波沐主恩。","雄堪为兽长，慧亦解人言。","辇道行犹窄，长河搅欲浑。","画桥垂柳外，观者驻游轩。"]},{"t":"浴象 其五","f":"五言律诗","c":["浴罢更昂藏，溅珠满地凉。","归朝添渥泽，散步有辉光。","鼻划荷筒捲，牙垂藕笋长。","遥看真可讶，修影出城墙。"]},{"t":"浴象 其六","f":"五言律诗","c":["纵然生佛国，何似集王家。","竹削四蹄稳，棱分两目斜。","沈疑山落影，喷亦雪飘花。","会向尧阶舞，时清不触邪。"]},{"t":"同杨应先朱瞻御梁喈林集程散木中秘园亭用瞻御韵","f":"五言律诗","c":["画阑藏宛转，芳树互周遮。","斲石片云坠，移筠万玉斜。","浓分宫苑柳，艳缀海榴花。","时复清吟罢，玄言共啜茶。"]},{"t":"雨夜 其一","f":"五言律诗","c":["微雨忽入户，夏云涵暝光。","经旬苦毒热，兹夜浴浮凉。","旅食矜珠桂，乡愁问稔荒。","胡为空役役，终日尚名缰。"]},{"t":"雨夜 其二","f":"五言律诗","c":["从来蓟北地，多旱少愁淋。","残溽蒸成雨，微云荡作阴。","就凉方徙榻，泛爽最宜琴。","自觉身无累，悠悠此夜心。"]},{"t":"雨夜 其三","f":"五言律诗","c":["夜长睡可厌，暑雨快何如。","懒是生来骨，穷留著就书。","一灯清漏下，数杵寺钟馀。","萧爽还如昼，纸窗流影虚。"]},{"t":"雨夜 其四","f":"五言律诗","c":["密云舒又合，雨色尚徘徊。","减膳皇仁渥，升庖国禁开。","微沾宣久郁，薄怒示轻雷。","天意难应问，终宵首重回。"]},{"t":"雨夜 其五","f":"五言律诗","c":["明明真宰意，嘿以示禨祥。","夜久炎如洗，听残喜若狂。","清时无害马，天怒在宏羊。","甘澍应如此，欢呼走成方。"]},{"t":"雨夜 其六","f":"五言律诗","c":["昨有传来信，江关弄甲兵。","人皆数粒粟，野有揭竿行。","夜梦亲儿女，乡书隔友生。","南中天泽远，应不比京城。"]},{"t":"何卜熙刺史过馆话别兼赠以诗即席奉答","f":"五言律诗","c":["君今五马贵，犹说宦情难。","况我垂双鬓，经年博一官。","关山行役苦，雨雪去途寒。","赖有临岐赠，芳词吐若兰。"]},{"t":"夜次大通滘","f":"五言律诗","c":["风便船弥进，中宵尚促程。","一帆江雾重，几片雪灯明。","邮馆风传柝，官艘夜点兵。","畏途频命旅，息桨待潮行。"]},{"t":"寄舍弟","f":"五言律诗","c":["吾侪二三子，大半不逢时。","暂戢飞腾翼，谁图丘壑姿。","生涯七寸管，旧业一茆茨。","出处元同调，栖迟得并枝。"]},{"t":"夜起读陈子明诗","f":"五言律诗","c":["终夜不成寐，披衣检旧编。","遐哉千古事，作者几人焉。","草昧凡三变，精华或一宣。","看君饶著述，他日必能传。"]},{"t":"过潘元明静适堂留题","f":"五言律诗","c":["市朝空役役，此地得真如。","竹影苔痕合，庭阴日色虚。","频来非问字，凭几共观鱼。","啜茗无馀事，焚香读古书。"]},{"t":"除夕","f":"五言律诗","c":["耿耿达长夜，悠悠逼岁除。","时序不相待，头颅变故吾。","生涯看潦倒，礼法任粗疏。","即此销馀日，千秋将焉如。"]},{"t":"访梁孝廉","f":"五言律诗","c":["金鸡下紫宸。","寒谷暗生春。","白发悲游子，丹风度逐臣。","曝背思明主，过庭傍老亲。","图书四壁在，知尔未全贫。"]},{"t":"余方谢客而顺德黄功治邓尔师来访开户延之赋赠二律 其一","f":"五言律诗","c":["经秋无一事，结束类枯禅。","药草罗清供，香花礼法筵。","闭门辞问字，高枕咏残编。","有客来相过，言寻静者缘。"]},{"t":"余方谢客而顺德黄功治邓尔师来访开户延之赋赠二律 其二","f":"五言律诗","c":["幽居惟水竹，息影绝纷呶。","得尔素心侣，真成把臂交。","一瓢常挂树，三径自诛茆。","从此忘来去，蓬门可任敲。"]},{"t":"秋雨园居容九闳过访留酌 其一","f":"五言律诗","c":["颓垣经雨塌，编棘故尝籓。","弱卉斜穿格，垂萝袅荫门。","茶炉置竹脚，药白倚忪根。","晴有高人过，琴书共晤言。"]},{"t":"秋雨园居容九闳过访留酌 其二","f":"五言律诗","c":["微雨飒沓过，凉飔透薄帘。","侵阶时沥沥，映草复纤纤。","谑语堪成韵，轻杯剧可拈。","飞腾君自爱，吾著老夫潜。"]},{"t":"林阳仲容九闳过饮凤城旅馆","f":"五言律诗","c":["倦游无岁月，可似滞周南。","客计穷相傍，乡愁酒共酣。","时名骄白眼，世路误青衫。","牢落归何晚，徒令短铗惭。"]},{"t":"汝载山房同诸子话别","f":"五言律诗","c":["见棹迟明发，移尊话竹林。","别离何必远，去住此时心。","作客恬乡梦，因君动苦吟。","刺桐花下月，且与坐更深。"]},{"t":"十三夜","f":"五言律诗","c":["未觉清晖满，还惊皓魄流。","夜凉清似水，云澹曲如钩。","雁影冲寒塞，砧声起暮潮。","孤城一长望，萧飒总悲秋。"]},{"t":"十四夜","f":"五言律诗","c":["素月净明漪，危桥清眺时。","带星光沥沥，蘸水流澌澌。","岸火行相引，渔舟望屡移。","严城不禁夜，玉漏正迟迟。"]},{"t":"十五夜","f":"五言律诗","c":["暝色澹城烟。","中天一镜悬。","薄云微点缀，清影斗弹娟。","狼籍传杯斝，纵横列几筵。","酒阑兴未已，南陌共翩翩。"]},{"t":"同梁伯静舍弟文度送吴彦先于东郊赋别","f":"五言律诗","c":["黯黯那能别，尊前不尽欢。","日色晓衔阁，岚光晴度峦。","起看江上影，遥挂片帆端。","欲发频维棹，偏怜此际难。"]},{"t":"送吴德祖还新安","f":"五言律诗","c":["山山黄叶积，之子汎归舟。","邂逅成今昔，存亡念旧游。","岭云微带雨，江树远含秋。","惆怅西风道，茫茫起旅愁。"]},{"t":"水松","f":"五言律诗","c":["只讶移峰岭，谁知产污坭。","傍柳还垂岸，非桃亦占溪。","照水笼鳞现，翻波麈尾齐。","欲搆茅龛住，怜君在瀼西。"]},{"t":"翠鸟","f":"五言律诗","c":["委毳人争惜，微躯混野蒿。","衔鱼冲水入，避缴掠林豪。","岂不矜文藻，何惭借羽毛。","山鸡频照影，顾盼亦云劳。"]},{"t":"灯","f":"五言律诗","c":["孤光唯一点，清迥若含情。","喜送红珠润，残添碧晕生。","虚晖涵室白，纤隙借邻明。","独有寒襟影，侵人梦不成。"]},{"t":"闺阁灯","f":"五言律诗","c":["珠蕊寒难结，兰膏淡不辉。","情因妮独夜，欢恐夺朝晖。","暧暧送宵梦，澄澄鉴薄帏。","几回羞对影，背立换罗衣。"]},{"t":"禅室灯","f":"五言律诗","c":["已知光是幻，难道照非缘。","灭尽归何处，将残续有权。","分能千百影，聚亦往来烟。","此际原无著，聊凭膏火传。"]},{"t":"佛灯","f":"五言律诗","c":["含灵都向晦，寂照一龛中。","色岂无常幻，光原不住空。","日月灯皆佛，山河影尽同。","静看轮转内，于此悟无穷。"]},{"t":"渔灯","f":"五言律诗","c":["萧萧芦苇岸，点点似流萤。","澹影摇细浪，微光缀曙星。","鱼方思浩荡，鹤或惊空冥。","不是燃犀照，深潭聚百灵。"]},{"t":"村灯","f":"五言律诗","c":["远火明长薄，孤村欲暝时。","人声在篱落，花影宿茆茨。","犬猎遥归垄，鸡栖尽上枝。","田家多夜作，腰斧斫松脂。"]},{"t":"溪边春望","f":"五言律诗","c":["暖烟才著水，澹宕一痕春。","密树深藏寺，修篁翠映人。","拣沙鸿迹净，晒日鹭裳新。","渔子閒摇桨，沧波漾钓纶。"]},{"t":"步月过天宁寺时僧有扫室相留者索笔赠之","f":"五言律诗","c":["榕阴下夕霁，殿角引微凉。","片月流空梵，飘风洒异香。","僧悬半夜榻，净扫一间房。","我亦原无系，江干信短航。"]},{"t":"过宝月台晓不及登","f":"五言律诗","c":["茫茫苍霭外，不复辨台亭。","珠蚌长胎月，烟螺近缀星。","千章环古翠，一抹走空青。","未得闻吟眺，肩舆可暂停。"]},{"t":"赋得虾蟆石","f":"五言律诗","c":["怪石蟾蜍似，蹲蹲立海门。","疑从沙际浴，常吸露华吞。","应月珠生蚌，向风浪拜豚。","千秋形不灭，阴雨想精魂。"]},{"t":"题大小孤山","f":"五言律诗","c":["孤山两片石，分峙蠡湖中。","地控三江险，波连九派通。","断鳌悬左右，卓剑并雌雄。","开凿何年始，川流尽汇东。"]},{"t":"赋得莺声似故山","f":"五言律诗","c":["莺声凡几啭，似报故园春。","梦醒身仍客，乡遥鸟是邻。","连天芳草色，刺眼柳条新。","欲把双柑听，香醪懒入唇。"]},{"t":"谒徐王陵","f":"五言律诗","c":["立马望岧峣，玄宫敞泬漻。","神皋栖瑞露，阴隧飒灵飙。","玉佩趋跄地，翠华想像遥。","河山留砥砺，紫气夜常朝。"]},{"t":"高皇庙","f":"五言律诗","c":["芒砀气何在，遗祠尚俨然。","空留今俎豆，犹想旧山川。","村社酾牛酒，山农偅庙田。","松间老鹤语，疑说歌风年。"]},{"t":"经邹县","f":"五言律诗","c":["邾城兵燹后，茅屋半无邻。","白昼燐随马，青林鬼闹人。","麦田岁不雨，荒垄草难春。","浩劫应如此，翻疑造物仁。"]},{"t":"观鞦韆","f":"五言律诗","c":["枌谢间垂杨，鞦韆出短墙。","佩摇先作响，衣动俏闻香。","片雾颓青鬓，双钩挂玉梁。","恍疑烟霭里，神女下高唐。"]},{"t":"署中病怀示王尧韭 其一","f":"五言律诗","c":["拙宦成何补，羁栖病转淹。","炕衣防湿壁，晒帙向晴檐。","海鸟时窥牖，崖蜂故坠帘。","空阶行药遍，嫩草正廉纤。"]},{"t":"署中病怀示王尧韭 其二","f":"五言律诗","c":["虽然称冷署，强半类僧寮。","折鼎同邻爨，荒畦课仆浇。","清斋供淡笋，苦茗杂陈椒。","且喜无家累，行踪付衲瓢。"]},{"t":"社集同王尧韭潘孟与诸子咏六角井","f":"五言律诗","c":["为泉因地穴，甃石肖其形。","雪蕊纷同出，菱花曲渌青。","凭阑窥面面，施绠汲泠泠。","直接泮池派，芳芹扑鼻馨。"]},{"t":"送陈国徵廷试","f":"五言律诗","c":["寒潮霜渐落，之子去扬舲。","象郡通南极，鹏程溯北溟。","涛来千顷白，天际一帆青。","客思同明月，随君夜度琼。"]},{"t":"和潘孟与山居寒雨 其一","f":"五言律诗","c":["飒沓遍林阿，村居奈雨何。","市声到壑尽，幽事傍农多。","山作重重睡，畦添白白波。","槿垣竹户外，相近不相过。"]},{"t":"和潘孟与山居寒雨 其二","f":"五言律诗","c":["入室始搴萝，支床藉以蓑。","村醪堪一醉，鼓腹亦当歌。","淅淅雨如注，殷殷雷乍过。","惊闻豚犊响，起问夜如何。"]},{"t":"冬雨閒居 其一","f":"五言律诗","c":["寒到天边减，雨偏冬后淫。","一閒消客况，万感入乡心。","乞火修山屐，绽囊护旅琴。","更嫌风稍紧，移药傍廧阴。"]},{"t":"冬雨閒居 其二","f":"五言律诗","c":["也知身是赘，何必更言家。","天外浮皆水，波心泊似槎。","俸贫难宠鹤，门冷任邮鸦。","雨过阶前绿，茸茸茁菜芽。"]},{"t":"冬雨閒居 其三","f":"五言律诗","c":["虽然焚不律，时复搅枯肠。","混沌留顽窍，希夷教睡方。","岂堪题傲吏，或者恕清狂。","窗外人声过，生徒到讲堂。"]},{"t":"冬雨閒居 其四","f":"五言律诗","c":["冻盎花无韵，炽庐香不恬。","已怜人意倦，况值雨情淹。","洗竹安茶白，移泉问水签。","客来唯有此，清供谅无嫌。"]},{"t":"小雨集李影九","f":"五言律诗","c":["幽清谁领略，空馆我同君。","水木閒添韵，禽鱼剧赴群。","诗怀看石貌，客履认苔纹。","一雨池烟澹，寒花对薄醺。"]},{"t":"初抵家园","f":"五言律诗","c":["一为江路客，三负故园春。","水木谁閒主，禽鱼似避人。","庭添初植卉，门迓夙来宾。","本是栖迟地，翻令意转新。"]},{"t":"题伍百亿行乐 其一","f":"五言律诗","c":["画里余曾识，人今立小斋。","镜花微有像，秋水澹无怀。","牝牡观其妙，丹青失所裁。","若将形影问，犹费梦中猜。"]},{"t":"题伍百亿行乐 其二","f":"五言律诗","c":["乍见犹疑似，神情惝恍间。","图云偏傍水，绘月不离山。","埏植凭天巧，铅华洗俗颜。","谁明真幻相，一语破禅关。"]},{"t":"哭羽甫家兄 其一","f":"五言律诗","c":["只道经年别，云胡隔死生。","死馀长恨事，生抱独钟情。","痛极都无泪，哀来不作声。","丧予堪有恸，岂但悼难兄。"]},{"t":"哭羽甫家兄 其二","f":"五言律诗","c":["常时托生死，易箦不相闻。","举世谁知己，偏余独负君。","妻亡谁定谥，友在拾遗文。","冥漠何繇荐，瓣香徒自焚。"]},{"t":"哭羽甫家兄 其三","f":"五言律诗","c":["情深能寓淡，交泛雅存真。","月旦归时彦，风期迈古人。","江山留韵事，石火妒閒身。","惟有它生愿，莲花定结邻。"]},{"t":"哭羽甫家兄 其四","f":"五言律诗","c":["精神原炯炯，混俗示和光。","百忍持公艺，三千客孟尝。","琴心澹益远，诗格雅而苍。","不独音徽邈，人今古谊亡。"]},{"t":"挽陈宪副 其一","f":"五言律诗","c":["斯人皆欲杀，到死不相饶。","怒眦看疑裂，雄心血未销。","情翻新旧局，世阅往来潮。","独有穷交泪，还同絮酒浇。"]},{"t":"挽陈宪副 其二","f":"五言律诗","c":["热肠偏我辈，馀子不堪云。","世法宁容此，伊人讵识君。","气终悬峭壁，笔亦凛雄军。","侠骨归何地，要离岂愿群。"]},{"t":"岁暮苦雨 其一","f":"五言律诗","c":["雨寒亡赖甚，兼值岁云残。","老去逢辰懒，年荒度腊难。","门尝稀出入，性只任眠餐。","粗得调心法，无营梦亦安。"]},{"t":"岁暮苦雨 其二","f":"五言律诗","c":["阴岑难辨晓，黑暗总宜眠。","大梦观生事，长贫谢俗缘。","骨高仍似马，坐冷并无毡。","只道为儒苦，儒官苦更然。"]},{"t":"岁暮苦雨 其三","f":"五言律诗","c":["残冬犹足恋，雪雨太无情。","大地疑长夜，高天不肯明。","四邻皆握粟，合境未休兵。","徒有鱼肠在，终宵迸匣鸣。"]},{"t":"除夕","f":"五言律诗","c":["三百六十日，堪怜是此宵。","金虬听漏永，银蜡守更遥。","觅果儿争栗，陈蔬妇办椒。","流光不可驻，倏忽又来朝。"]},{"t":"题梅赠黎隐君","f":"五言律诗","c":["比韵梅堪侣，孤清占水湄。","古香存老干，冷艳发春枝。","日月沦精魄，冰霜炼骨皮。","宁同兰蕙质，空谷媚华滋。"]},{"t":"次和林阳仲西郭感事 其一","f":"五言律诗","c":["灼日炎方息，连云搆已残。","行人多色惨，啼鸟亦声酸。","燕乳辞巢去，鼯饥掠果餐。","无情应有恨，长寝夕漫漫。"]},{"t":"次和林阳仲西郭感事 其二","f":"五言律诗","c":["还闻翁仲哭，空见石羊眠。","万斧樵邱木，千犁踏垄田。","梦魔人逐鹿，机网雀衔蝉。","因悟阎浮界，谁为解脱仙。"]},{"t":"次和林阳仲西郭感事 其三","f":"五言律诗","c":["青山原递主，芳草若含情。","百舌撩春梦，千林带杀声。","荒村连市徙，官道绝人行。","叹息西流水，谁与挽洗兵。"]},{"t":"过羽甫兄旧馆 其一","f":"五言律诗","c":["几回掩袂过，此地亦西州。","门巷更新搆，林池只旧流。","灶寒烹药火，墙塌养花沟。","犹记翻经处，松风满佛楼。"]},{"t":"过羽甫兄旧馆 其二","f":"五言律诗","c":["门冷唯司蔓，庭空祇守槐。","燕巢秋社剩，客履旧苔霾。","琴想虚悬壁，云疑懒出斋。","伤心非一事，弹泪下荒阶。"]},{"t":"元宵即事呈林阳仲何人止 其一","f":"五言律诗","c":["羯鼓喧残市，妖妆演俗伶。","火莲栽不活，珠蚌吐难明。","地警欢场寂，岁贫灯价轻。","金吾方厉禁，更尽没人行。"]},{"t":"元宵即事呈林阳仲何人止 其二","f":"五言律诗","c":["炙月人难暖，嘶风夜转寥。","如何当此际，都不像元宵。","烛泪民膏尽，金声贼胆骄。","重城刚下钥，是处踏星桥。"]},{"t":"过何文玉青浪园 其一","f":"五言律诗","c":["微澜轻漾绿，空影发天青。","出郭尘方静，到山眼独醒。","阴廊依岸转，霁阁与烟停。","步步堪延伫，回飙瑟瑟听。"]},{"t":"过何文玉青浪园 其二","f":"五言律诗","c":["虹背桥平跨，沙心柳突穿。","水能周户外，山亦到堂前。","此地居然胜，谁云远特偏。","迟来应选屐，踏遍好林泉。"]},{"t":"春日客集歇园","f":"五言律诗","c":["乡心无日夜，飞梦绕天涯。","远道空怀友，残年喜到家。","相逢开臈酒，小步阅春华。","薄酌花阴下，荒池两部蛙。"]},{"t":"偶作示儿侄","f":"五言律诗","c":["劳骛嗟身事，放閒暂适情。","先人遗素业，若辈谢躬耕。","入世宁无累，惭人说寡营。","行藏吾早定，忧汝学难成。"]},{"t":"园居社僧过宿 其一","f":"五言律诗","c":["阴池流活活，独树鉴青冥。","曝日鱼方懒，酣林鸟乍醒。","山僧来借榻，石几共陈经。","忽到新潮水，潺湲倚槛听。"]},{"t":"园居社僧过宿 其二","f":"五言律诗","c":["以余常依止，于尔可当归。","选石安茶灶，借栏挂衲衣。","看经閒月上，施食野禽稀。","不必扃前户，从无人款扉。"]},{"t":"雨卧中林因怀西林寄何人止","f":"五言律诗","c":["微雨暗复滴，长风吹不晴。","灯窗泉独语，林梦叶频惊。","傲岸非关癖，萧閒颇得情。","因之怀夙好，西郭有寒盟。"]},{"t":"怀莫止公 其一","f":"五言律诗","c":["故国应难返，它山何处归。","人情已可见，失路竟安依。","兴寝劳魂梦，传闻有是非。","灯前閒简帙，泪落忽横衣。"]},{"t":"怀莫止公 其二","f":"五言律诗","c":["人前犹寓札，身后曷留名。","寄托情弥苦，羁离意不平。","峨眉插汉峭，巫峡注湍惊。","未卜君何向，余怀与恨并。"]},{"t":"春日柬俞季郎","f":"五言律诗","c":["梦遥犹可接，室迩反多违。","别有司离合，非关会数稀。","诗情高入淡，慧想寂通微。","以此堪逃俗，春来知掩扉。"]},{"t":"题世立澹居","f":"五言律诗","c":["人方炎是逐，君以澹为居。","壁老蜗陈字，带长草护书。","枝头听巧鸟，沼面数行鱼。","客履破苔入，虚庭自晏如。"]},{"t":"赠祝爱林","f":"五言律诗","c":["徒然寄一廛，身已隐壶天。","香篆煨沈水，茶鎗点活泉。","桐君曾授诀，药上许参禅。","亦有诗琴伴，时来问酒钱。"]},{"t":"同梁叔熹过集蒋园时方营筑","f":"五言律诗","c":["邮泉枯得活，叱石嫩能醒。","乍入迷花坞，前题指柳亭。","老篁稀似帚，新萏擢如钉。","灌剔从兹始，再来眼必青。"]},{"t":"春日尹世立携同高仲良陈伯良集放生社是日微雨 其一","f":"五言律诗","c":["微雨洒春枝，芳菲遍水湄。","僧閒出定后，客韵到门时。","律在何妨酒，禅深益悟诗。","暝钟人始散，灯影照茆茨。"]},{"t":"春日尹世立携同高仲良陈伯良集放生社是日微雨 其二","f":"五言律诗","c":["湿烟含阁润，滑雨点林酥。","晴霁虽云好，空濛似此无。","泉堪供碧乳，饭亦出雕胡。","尽日閒吟眺，为欢尚未徂。"]},{"t":"春夜世立携客过访息庐 其一","f":"五言律诗","c":["春光已过半，林卧未知春。","闭户殊无趣，逢君最快人。","敲诗釐韵谱，品水集茶宾。","晏坐林方寂，潮声到耳新。"]},{"t":"春夜世立携客过访息庐 其二","f":"五言律诗","c":["怒石蹲林莽，髡茆贴水涯。","有僧容借榻，逢客可为家。","花气和香韵，禅灯分月华。","流莺方睡稳，聊共听鸣蛙。"]},{"t":"次和尹世立夜过口占","f":"五言律诗","c":["潮响刚到门，客屐临溪驻。","登台目稍宽，倚树得新句。","朦胧月始华，澹宕林多趣。","语罢出林垌，笑指客来处。"]},{"t":"送世立沾麓五羊赴试","f":"五言律诗","c":["禅榻听经处，思君独倚阑。","潮平池响细，风搅叶声乾。","蝶寝余劳梦，鸿飞尔并翰。","一帆破晓去，带雨度江干。"]},{"t":"春雨怀林鹿野先生","f":"五言律诗","c":["点滴催花雨，空濛洒径尘。","是林皆绽锦，无鸟不啼春。","客教修琴法，僮忙剪药晨。","小楼拈笔处，应不坐凡宾。"]},{"t":"得友人山房苦雨诗次答","f":"五言律诗","c":["不复辨昏晓，信知春日迟。","云来翻作嶂，阶漫忽成池。","湿灶沈烟处，閒楹生菌时。","案头光灿灿，昨夜得君诗。"]},{"t":"余将赴琼陈受之解楚绶归移尊话别 其一","f":"五言律诗","c":["余浮溟海去，君挟楚云归。","去住同为恋，行藏愿每违。","惊看时局异，转觉鬓毛非。","况复凉飙至，萧萧满袷衣。"]},{"t":"余将赴琼陈受之解楚绶归移尊话别 其二","f":"五言律诗","c":["移舟临水曲，欲别几夷犹。","海国连三岛，波心见万州。","尊前釐韵谱，天末想诗邮。","独有乡园恋，迢迢路阻修。"]},{"t":"别李公祖用其见赠韵","f":"五言律诗","c":["南溟天最远，离绪与之长。","去路甘棠绕，流波杜若香。","清神分月朗，丽句焕云章。","别后怀明德，盈盈水一方。"]},{"t":"经高凉寄题李曰辅山亭用吴川楼先生韵 其一","f":"五言律诗","c":["名园虽未到，地已数经过。","邃樾藏山秀，浮岚出海多。","凿天分洞穴，翳阁厂藤萝。","正尔怀高躅，因风寄浩歌。"]},{"t":"经高凉寄题李曰辅山亭用吴川楼先生韵 其二","f":"五言律诗","c":["树已屯青霭，泉兼泻碧幽。","高人于此筑，仙子也曾游。","苇葺团瓢屋，荷藏刳木舟。","高凉信不谬，六月已先秋。"]},{"t":"经高凉寄题李曰辅山亭用吴川楼先生韵 其三","f":"五言律诗","c":["地旷宜邀月，楼高可摘星。","海通天外白，山入户来青。","花木釐新谱，禽鱼续旧经。","三桥频立马，注目想嵬亭。"]},{"t":"披莽 其一","f":"五言律诗","c":["披莽从今始，旷然就剪除。","朴椎存古意，疏野可吾庐。","萤熠萝轩火，蜗行石壁书。","因兹便寝处，不乐亦何欤。"]},{"t":"披莽 其二","f":"五言律诗","c":["仄仄鱼鳞径，疏疏虎眼篱。","药移他地本，柳剩去年枝。","忌俗删其偶，蠲繁割所私。","莫言閒閒事，调剂有时宜。"]},{"t":"披莽 其三","f":"五言律诗","c":["鹏翼垂云外，焦冥睫里栖。","人间无不有，物性也难齐。","破梦看隍鹿，观心养木鸡。","翛然唯所适，吾亦任天倪。"]},{"t":"披莽 其四","f":"五言律诗","c":["到海天弥大，应无天外人。","地逢南不满，花度腊犹春。","晦朔通潮息，东西走曜轮。","因知一室内，可以观无垠。"]},{"t":"酌酒戏赠楚江石","f":"五言律诗","c":["把杯浇石丈，冷面一相看。","物有离乡贵，人真作客难。","雨花凝不活，雪蕊冻微残。","终日閒摩弄，惟应共岁寒。"]},{"t":"赠王尧韭移居石门","f":"五言律诗","c":["久嫌城市薄，性只爱邱樊。","卜筑邻沙井，移家向石门。","赊天开古洞，僦月敞幽轩。","不作依人计，琴书聊晤言。"]},{"t":"同诸子游清源庵因寻东坡井 其一","f":"五言律诗","c":["尽堪成小致，乍入即淹留。","始识萧清趣，难从耳目求。","稍嫌池尚涸，添以竹能幽。","偶与閒僧约，迟余月一游。"]},{"t":"同诸子游清源庵因寻东坡井 其二","f":"五言律诗","c":["祇宜城隔断，却有径斜穿。","僧饭抄盘米，园丁入寺钱。","霜催榔子堕，雨濯菜牙鲜。","指点迤西路，来寻学士泉。"]},{"t":"访答玄亮书斋","f":"五言律诗","c":["岂可居无竹，书声乃在兹。","雨来青不断，云过重难移。","空碧摇书幌，翠光入槿篱。","兴来无腹稿，满壁写新诗。"]},{"t":"杜玄洲折柬见邀不果赴次答","f":"五言律诗","c":["惆怅心期阻，端居意绪阑。","喑蝉依柳静，斗雀下庭寒。","终日阖门坐，同人寡所欢。","回灯独自语，兴寝太无端。"]},{"t":"早起","f":"五言律诗","c":["严冬似早春，时物多暄煦。","崇朝澹晦阴，花径冥濛雨。","垂柳助芳柔，繁英亦增妩。","悄然人虑清，屋角流莺语。"]},{"t":"初春出郭访郑圣符","f":"五言律诗","c":["泠然人意远，倚杖眺芳林。","鸟迹窥奇字，泉声入韵琴。","空光分碧霭，积翠澹城阴。","春色从东至，青郊草欲深。"]},{"t":"送林公毅之会同","f":"五言律诗","c":["春装乘晓发，望望博冲河。","海色浮新浪，林芳变旧柯。","排寒风暂细，进暖气微和。","立马南桥畔，听莺一浩歌。"]},{"t":"寒雨怀空可亭却寄陈命美 其一","f":"五言律诗","c":["也知色是幻，故以空名亭。","忍草沿阶长，禅花上架青。","山窗一雨过，客履几人经。","晓露溪痕湿，移泉到佛瓶。"]},{"t":"寒雨怀空可亭却寄陈命美 其二","f":"五言律诗","c":["未知檐溜积，池水底般深。","旧药应成次，新篁定出林。","萧清全洗俗，疏野最宜心。","正有伊人想，冲烟未可寻。"]},{"t":"戏赠郑圣符新婚","f":"五言律诗","c":["多年才射雉，此夕快骑凰。","带结同心缕，衿薰异国香。","低声呼小玉，偷眼觑檀郎。","昨雨连朝暗，为云梦楚王。"]},{"t":"命美邀同冯载赓集空可亭","f":"五言律诗","c":["童方传折柬，步即到精庐。","茗灶还留火，高斋才罢书。","瓶芳梅臈候，砌艳卉冬馀。","为爱椰阴畔，停杯待月初。"]},{"t":"柬冯载赓时新纳宠","f":"五言律诗","c":["家园宴方洽，知不到山房。","积翠如凝黛，添红为洗妆。","芳心传豆蔻，皓齿发槟榔。","若问閒功课，眉尖较短长。"]},{"t":"同载赓命美赐炬公毅夜集圣符宅余独后至时圣符新婚","f":"五言律诗","c":["幽期那忍负，薄暮我能来。","莲蜡分房烛，兰肴续夜杯。","暖风微送酒，芳意密传梅。","城柝频移漏，更深尚未回。"]},{"t":"访潘垣杓别业望山人洞不果游 其一","f":"五言律诗","c":["垂萝今结屋，甘蔗旧名园。","出郭不踰武，离家祇几门。","虽当车马道，别是烟霞村。","因悟考槃趣，非为场圃言。"]},{"t":"访潘垣杓别业望山人洞不果游 其二","f":"五言律诗","c":["兰堪畹以九，竹亦径而三。","蔬甲肥冬雨，油花洗暮岚。","过桥分马埒，望岛岩仙龛。","未许恣游屐，空濛薄霭衔。"]},{"t":"夜起步月烹茶怀周自珍却寄","f":"五言律诗","c":["龛灯留静夜，残梦酒初醒。","起步瞻河汉，微光流户庭。","鸡声破海白，虫语上帘青。","正尔怀同赏，茶香入瓦瓶。"]},{"t":"挽苏新男司训 其一","f":"五言律诗","c":["瘴海聊归骨，家山尚旅魂。","问程指绿水，行哭向青门。","宦薄身同弃，人亡道不尊。","从来生死地，交谊不须论。"]},{"t":"挽苏新男司训 其二","f":"五言律诗","c":["鹏翮志犹壮，蝇头帙已陈。","可怜贫到骨，未免死资人。","丹旐朱厓道，青刍碧海滨。","潸然一相送，不觉已沾巾。"]},{"t":"同彭蒋二寅丈五里亭值雨入白衣庵礼大士 其一","f":"五言律诗","c":["冠盖纷衢路，停舆叩净关。","慈云方覆径，法雨乍弥山。","施食禽忘怖，衔花鹿共閒。","犹然牵物役，到此愧尘颜。"]},{"t":"同彭蒋二寅丈五里亭值雨入白衣庵礼大士 其二","f":"五言律诗","c":["一饭依香积，千花散卜林。","次寻忙处息，聊以幻调心。","铎响摇空砌，潮声吼海浔。","闻思路已绝，因悟观世音。"]},{"t":"次答自珍病中见","f":"五言律诗","c":["闭门缘避客，简出似怀疴。","拾翠谁同伴，听莺独寤歌。","三春行尽矣，一醉奈愁何。","为问青郊道，芳菲几许多。"]},{"t":"次答何人止见怀","f":"五言律诗","c":["即有殊方胜，其谁共讨探。","鼠应穷技五，狙亦赋朝三。","归梦潮来去，离踪海北南。","还将天外信，遥寄榻边谈。"]},{"t":"和坡公倦夜","f":"五言律诗","c":["夜长人意倦，展转候天明。","帐绽容蚊入，窗虚恣鼠行。","渐于乡梦断，翻觉旅魂清。","拟作还山计，初衣补未成。"]},{"t":"有感和坡公和孙叔静韵","f":"五言律诗","c":["世法老难熟，心情近更疏。","眼昏看簿牒，心怯开家书。","造物劳薪甚，吾生爨木馀。","有时拈秃管，空腹不堪摅。"]},{"t":"睡觉和赠子野韵","f":"五言律诗","c":["酒阑初睡觉，残梦未能成。","廿载红灯影，相随白木檠。","窗风敲阵阵，城漏滴声声。","暗数从前事，悠悠似隔生。"]},{"t":"杂感和集归来辞 其一","f":"五言律诗","c":["东风吹百卉，枯条难再荣。","良时一弃置，世路绝逢迎。","迹与飘蓬逝，身将委羽轻。","潸然中夜起，感叹若为情。"]},{"t":"杂感和集归来辞 其二","f":"五言律诗","c":["戒楫拟浮海，巾车命仆夫。","鸟还知倦翮，马老谢长途。","强出官无效，思归园欲芜。","独行何踽踽，背负一青壶。"]},{"t":"杂感和集归来辞 其三","f":"五言律诗","c":["世法不相假，人情强作欢。","鴳鹏均有适，大小等齐观。","敝带犹堪惜，瓶居讵近安。","清时有衡泌，何地不盘桓。"]},{"t":"杂感和集归来辞 其四","f":"五言律诗","c":["藜杖不觉远，春光何处寻。","听鸟清砭耳，窥泉空到心。","山霭天开画，松风涧奏琴。","官閒殊亦好，时不废登临。"]},{"t":"杂感和集归来辞 其五","f":"五言律诗","c":["去去复去去，夷犹马不前。","云心轻出岫，溪语恋鸣泉。","涉世聊委命，将心难问天。","生来不作计，负郭悔无田。"]},{"t":"杂感和集归来辞 其六","f":"五言律诗","c":["渐还归闾里，于役未云休。","来时数僮仆，经过认川邱。","黎母山应远，陆公泉尚流。","吾生亦幸矣，垂老海天游。"]},{"t":"杂感和集归来辞 其七","f":"五言律诗","c":["久客人情厌，归踪那可留。","山灵如惠我，川后幸安流。","剑有冲星佩，槎疑贯月游。","囊中无薏苡，忌者亦何求。"]},{"t":"杂感和集归来辞 其八","f":"五言律诗","c":["三山虽已到，犹未遇安期。","青鸟昨有信，停桡一问之。","饮罢生黎酒，赓钱海外诗。","行携水云去，持以赠相知。"]},{"t":"杂感和集归来辞 其九","f":"五言律诗","c":["归马不用策，畏途难载奔。","问程才海口，乡梦已江门。","下榻陈诗卷，行游络酒樽。","故人天外窅，时遣尺书存。"]},{"t":"杂感和集归来辞 其十","f":"五言律诗","c":["未必归全得，谁云昨尽非。","草应萦墨绶，荷欲制山衣。","久阅宦情淡，忘言交谊微。","一槎醉梦过，数摺健帆飞。"]},{"t":"厓山吊古 其一","f":"七言律诗","c":["逝水东流怒不回，群峰中擘海门开。","两厓波浪成今古，异代衣冠入草莱。","远近林峦开罨画，高低云杪缀楼台。","英雄千载升沈地，击楫悲风万里来。"]},{"t":"厓山吊古 其二","f":"七言律诗","c":["旌旗十万度楼船，地转穷荒别有天。","百战雄图今已矣，九霄龙驭竟茫然。","仓皇梦失襄城路，缥缈魂游瘴海烟。","何处湘灵悲鼓瑟，满江渔火对鸣舷。"]},{"t":"厓山吊古 其三","f":"七言律诗","c":["崚嶒奇石倚晴霄，大海风云压暮潮。","涛覆星辰惊地轴，阵连鱼鸟撼天杓。","人亡故国山河在，碑隐荒苔世代遥。","无限哀魂招不得，断猿啼处草萧萧。"]},{"t":"厓山吊古 其四","f":"七言律诗","c":["濒危已失三千士，誓死犹存六尺孤。","岂是龙蟠跨宝鼎，可堪鳌背奠皇图。","云深越徼胡尘黯，霜冷残潮海日枯。","独有金牌报国恨，至今风雨泣昆吾。"]},{"t":"厓山吊古 其五","f":"七言律诗","c":["废寝遗陵落照间，白云苍雾洒空山。","如闻肃卫趋金闼，是否丰碑掩玉颜。","玄鹤夜归华表唳，黄龙朝捧紫宸班。","当时辇跸驱驰地，松桧无风响佩环。"]},{"t":"厓山吊古 其六","f":"七言律诗","c":["汴杭回首即荒滨，三徙逢厓事竟真。","天地有灵应一涕，风波垂死泣孤臣。","何来赤手堪扶国，即去黄冠亦误身。","还是中华千古地，长风吹雨洗腥尘。"]},{"t":"闻警 其一","f":"七言律诗","c":["中原烽火自妖氛，羽檄飞书处处闻。","虎旅未閒金锁甲，龙池犹鍊水犀军。","天寒古戍连衰草，日落秋笳惨暮云。","六郡材官知不少，阿谁麟阁署奇勋。"]},{"t":"闻警 其二","f":"七言律诗","c":["先朝九镇列如棋，近代团营非昔时。","遂使宵衣勤庙顾，更烦推毂命王师。","秦城自合开天堑，燕将真能饮月支。","见说飞符招募急，绝怜荷戟尽疮痍。"]},{"t":"闻警 其三","f":"七言律诗","c":["东辽本是先王地，千里关津带古城。","山海由来称国险，岔河原自逼神京。","通贡奉朔缘何事，夺市绐和太不情。","此日草茆忧匪细，欲将投笔请长缨。"]},{"t":"闻警 其四","f":"七言律诗","c":["金缯徒自误和戎，究竟殊无五利功。","闻道匈奴频牧马，可怜战士尽如熊。","南侵苜蓿肥□厩，西望葡萄绝汉宫。","漫恃居庸天外险，古来形胜至今同。"]},{"t":"散饮〔馆〕后寄蒋生","f":"七言律诗","c":["君家三径自为堂，忆我横经碧沼旁。","一笑流光怜过鸟，十年岐路叹亡羊。","疏帘钩月琴书净，细雨翻阶橘柚香。","樗散别来成底事，晚风红叶满山房。"]},{"t":"秋日徐子靖携区余诸子过访溪上","f":"七言律诗","c":["秋风门巷足盘桓，散步留宾得并欢。","一叶渔舠藏树窅，几家茆屋傍溪寒。","杯同河朔差无暑，诗比兰亭罚稍宽。","尽日幽林人不见，青山閒对碧巑岏。"]},{"t":"喜晴","f":"七言律诗","c":["积雨全消暑气凉，初晴云物霭苍苍。","沙边宿雾留残景，树杪垂虹带夕阳。","乳燕时时将哺返，游蜂叠叠趁花忙。","岁华人事俱无赖，拄杖狂歌入醉乡。"]},{"t":"送龚学博","f":"七言律诗","c":["笑向明时早挂冠，投閒应藉主恩宽。","三年作吏毡长冷，九折回车路亦难。","岁月已怜新鹤发，江湖终恋旧渔竿。","空馀绛幄谈经地，桃李阴阴春雨寒。"]},{"t":"过蒋伯瑞","f":"七言律诗","c":["曾倚云林搆石堂，归来三径未全荒。","帘分野色千峰暗，日转庭阴万堞黄。","芸阁霞开缃帙满，花台雨散墨池香。","莫言地僻相过少，握手偏怜故意长。"]},{"t":"寄冯文孺","f":"七言律诗","c":["少年射策献长杨，彩笔同驱翰墨场。","君悟莲花窥法藏，我从药里访医王。","迷途转认无生路，度世虚疑不死方。","大地山河皆泡影，不知何处是津梁。"]},{"t":"宿圭峰寺分韵得幽字","f":"七言律诗","c":["绝壑天藏古洞幽，禅堂深夜一灯留。","云边露湿孤峰净，树杪风含万籁秋。","共倚疏林窥月色，更临曲涧听泉流。","自怜浪迹空人世，到处江山足胜游。"]},{"t":"真人庵","f":"七言律诗","c":["海上真人去不回，千年灵洞锁莓苔。","风前尚想朝天舄，云气长封礼斗台。","玉乳时从阴涧落，琪花偏傍石坛开。","红尘扰扰仙都远，日暮空山猿鹤哀。"]},{"t":"游龙潭","f":"七言律诗","c":["飞流万仞捣龙宫，石磴千盘鸟道通。","白昼雷霆光隐见，晴天云雾碧冥濛。","湍声半落鼋鼍窟，日影斜窥虎豹丛。","坐久石林清啸起，恍疑身世欲乘风。"]},{"t":"同韩孟郁夜访方孟旋于万福寺","f":"七言律诗","c":["长安车马如流水，一到香林便不还。","童子汲泉当茗灶，山僧补衲下松关。","灯悬古榻摊书满，月照疏棂伴客閒。","不是风流许玄度，谁令清净此追攀。"]},{"t":"春夜过韩绪仲寺馆谈禅","f":"七言律诗","c":["化宫别院敞垂萝，叩齿焚香夜共过。","谁谓逃名一居士，依然持律老头陀。","莲花不染心同住，贝叶时翻手自摩。","思向祇林皈净业，红尘车马定如何。"]},{"t":"送陶逸则游西山","f":"七言律诗","c":["匹马探奇兴未阑，西山斜雪点征鞍。","天门日射金波动，云气光浮玉阙寒。","地转黄河朝太液，峰回紫塞抱长安。","怜君已就三都赋，秖恐人间属和难。"]},{"t":"送陈当时陈季慈何龙友出京","f":"七言律诗","c":["谁道词人满帝畿，相怜失意不同归。","敝裘为客黄金尽，击筑高歌白日微。","沟水寒流春寂寂，燕山残雪晚霏霏。","因君怀土情弥剧，尊酒河梁泪湿衣。"]},{"t":"舟中漫怀呈杨亦琳林应玺梁毓和","f":"七言律诗","c":["短棹冲寒落日斜，征途回首一长嗟。","谁云季子貂无恙，转觉潘郎鬓有华。","紫燕衔坭知旧垒，白杨飞絮定谁家。","吴山越水无消息，渺渺疑乘博望槎。"]},{"t":"同杨亦琳游报恩寺","f":"七言律诗","c":["初地何年梵刹开，一经残燬半蒿莱。","閒楹雨榻迷蛛网，废井烟沈隐劫灰。","听法愁猿窥宝座，衔花驯鹿上香台。","犹传舍利含光怪，铃铎风生夜月哀。"]},{"t":"寄黄六柳","f":"七言律诗","c":["久辞簪绂返田庐，萝薜森森称隐居。","地近柴桑多种柳，林疑濠濮足观鱼。","彤云染翰开金歼，清月焚香叩玉虚。","此日汉庭求禅草，可云消渴老相如。"]},{"t":"寄何文起","f":"七言律诗","c":["去矣年华雨鬓侵，芳游何日惬招寻。","疏桐露引萝轩月，画栋云移碧砌阴。","曲涧移泉通药圃，当窗列树尽瑶林。","洞门旧有留题在，缘藓春来知几深。"]},{"t":"寄张约之读书白云山中","f":"七言律诗","c":["白云山上白云居，袅袅丹梯万仞馀。","君自磨厓寻胜迹，何须服食检方书。","三冬琪树依瑶圃，半夜银蟾傍土除。","闻道班麟还可驭，凌风聊试碧霞裾。"]},{"t":"秋日园居呈王老师兼寄湛仲宾 其一","f":"七言律诗","c":["蔓草苍藤次第除，小亭灌木共萧疏。","驰驱自信无长策，贫病因知恋敝庐。","时复攒眉过白社，更谁载酒问玄居。","倦游司马多愁渴，犹向文园赋子虚。"]},{"t":"秋日园居呈王老师兼寄湛仲宾 其二","f":"七言律诗","c":["叠石为坛竹作林，编茆幽结薜萝深。","三千客里空长铗，万事邱中有短琴。","静爱松风醒蝶梦，閒调天籁韵禽音。","栖迟漫笑儒冠拙，何地江湖不陆沈。"]},{"t":"秋日园居呈王老师兼寄湛仲宾 其三","f":"七言律诗","c":["落絮游丝片片浮，小园萧索不禁秋。","衰荷欲卸红妆淡，嫩竹疑含粉黛愁。","曲沼平添疏雨润，高台独上晚风遒。","最怜潘岳多情思，不赋閒居亦白头。"]},{"t":"秋日园居呈王老师兼寄湛仲宾 其四","f":"七言律诗","c":["一雨能消暑气残，幽斋晴景更宜看。","床头堕叶摊书满，槛外飞花扑径寒。","山色濛濛当睥睨，商声淅淅戛琅玕。","关河迢递知音隔，独抱丝桐未忍弹。"]},{"t":"恭陪王老师谒白沙先生祠","f":"七言律诗","c":["路转丛篁一径分，遗祠肃穆俨江濆。","閒云不扫苍烟合，湛露长披碧树薰。","曲坞潭清犹贮月，空阶苔古尽成文。","宫墙此日堪翘首，蘋藻何人共荐芬。"]},{"t":"嘉会楼","f":"七言律诗","c":["百尺飞楼抗彩霞，荒村篱畔带渔家。","巡檐老鹤巢朱拱，泛浦春鸥点碧沙。","庐阜堂空山月静，楚台人去暮云斜。","惟馀桃李攒芳径，啼鸟年年对落花。"]},{"t":"途中杂咏同区季誉 其一","f":"七言律诗","c":["马迹难消驿路尘，惊看时序物华新。","流莺出谷初求友，海燕衔坭欲傍人。","榆荚半霏寒食雨，桃花疑带武陵春。","杖藜准儗寻芳去，泽畔行吟问楚臣。"]},{"t":"途中杂咏同区季誉 其二","f":"七言律诗","c":["无才秖合老盐车，敢向穷愁问著书。","贫似张仪犹有舌，病怜潘岳未宁居。","中原游侠千金尽，上苑烟花三月馀。","共道吴门容大隐，恐伤留滞鬓毛疏。"]},{"t":"途中杂咏同区季誉 其三","f":"七言律诗","c":["拂面轻尘捲地遥，杨花点点扑征轺。","疏槐野火连官舍，断碛残冰没短桥。","日落荒原人迹少，风生嫩草马蹄骄。","旗亭处处堪乘兴，拚典鹴裘慰寂寥。"]},{"t":"途中杂咏同区季誉 其四","f":"七言律诗","c":["官衢细柳曲沿堤，晓起冲寒一径迷。","古木断桥频骇马，疏星茆店忽闻鸡。","哨林猎火时时出，腰箭行人队队齐。","同是五陵游侠地，王孙归思草萋萋。"]},{"t":"途中杂咏同区季誉 其五","f":"七言律诗","c":["疲马间关畏路难，每逢村店卸征鞍。","榆钱杖底宁沽酒，柳絮风前不耐寒。","一饭侏儒谁欲饱，千金漂母若为欢。","天南天北无归计，长铗飘零未忍弹。"]},{"t":"途中杂咏同区季誉 其六","f":"七言律诗","c":["晓起登台思惘然，乡书遥滞岭云边。","悲同倦马频思枥，归似宾鸿动隔年。","几点残霞明旧垒，数家榆火试新烟。","青门尚有宜瓜地，何必还山买秫田。"]},{"t":"途中杂咏同区季誉 其七","f":"七言律诗","c":["嫩绿柔红斗晓晖，江南花信未全稀。","镜前病起愁添鬓，马上春寒未授衣。","蔓草似连边外色，遥山半入雨中微。","家园三径知无恙，碧荇苍苔满旧矶。"]}]};